const TORII_TCP_LISTEN_BACKLOG: i32 = 1024;
fn bind_reusable_tcp_listener(addr: std::net::SocketAddr) -> std::io::Result<TcpListener> {
    use socket2::{Domain, Protocol, Socket, Type};
    let domain = if addr.is_ipv4() {
        Domain::IPV4
    } else {
        Domain::IPV6
    };
    let socket = Socket::new(domain, Type::STREAM, Some(Protocol::TCP))?;
    socket.set_reuse_address(true)?;
    socket.set_nonblocking(true)?;
    socket.bind(&addr.into())?;
    socket.listen(TORII_TCP_LISTEN_BACKLOG)?;
    TcpListener::from_std(socket.into())
}
fn bind_reusable_tcp_listener_from_addrs<I>(addrs: I) -> std::io::Result<TcpListener>
where
    I: IntoIterator<Item = std::net::SocketAddr>,
{
    let mut last_error = None;
    for addr in addrs {
        match bind_reusable_tcp_listener(addr) {
            Ok(listener) => return Ok(listener),
            Err(err) => last_error = Some(err),
        }
    }
    Err(last_error.unwrap_or_else(|| {
        std::io::Error::new(
            std::io::ErrorKind::AddrNotAvailable,
            "no socket addresses resolved for Torii listener",
        )
    }))
}
async fn bind_torii_tcp_listener(address: SocketAddr) -> std::io::Result<TcpListener> {
    match address {
        SocketAddr::Ipv4(v) => bind_reusable_tcp_listener(std::net::SocketAddr::V4(v.into())),
        SocketAddr::Ipv6(v) => bind_reusable_tcp_listener(std::net::SocketAddr::V6(v.into())),
        SocketAddr::Host(v) => {
            bind_reusable_tcp_listener_from_addrs((v.host.as_ref(), v.port).to_socket_addrs()?)
        }
    }
}
#[derive(Debug)]
struct SocketAdmissionState {
    active: usize,
    active_by_ip: HashMap<IpAddr, usize>,
}
/// Listener-level connection admission enforced before any HTTP parsing.
#[derive(Debug)]
struct SocketAdmission {
    max_connections: usize,
    max_connections_per_ip: usize,
    state: parking_lot::Mutex<SocketAdmissionState>,
}
impl SocketAdmission {
    fn new(max_connections: NonZeroUsize, max_connections_per_ip: NonZeroUsize) -> Arc<Self> {
        Arc::new(Self {
            max_connections: max_connections.get(),
            max_connections_per_ip: max_connections_per_ip.get(),
            state: parking_lot::Mutex::new(SocketAdmissionState {
                active: 0,
                active_by_ip: HashMap::new(),
            }),
        })
    }
    fn try_acquire(self: &Arc<Self>, remote_ip: IpAddr) -> Option<SocketPermit> {
        let remote_ip = canonical_socket_ip(remote_ip);
        let mut state = self.state.lock();
        let active_for_ip = state.active_by_ip.get(&remote_ip).copied().unwrap_or(0);
        if state.active >= self.max_connections || active_for_ip >= self.max_connections_per_ip {
            return None;
        }
        state.active = state
            .active
            .checked_add(1)
            .expect("Torii active socket count overflow");
        state.active_by_ip.insert(
            remote_ip,
            active_for_ip
                .checked_add(1)
                .expect("Torii per-IP socket count overflow"),
        );
        drop(state);
        Some(SocketPermit {
            admission: Arc::clone(self),
            remote_ip,
        })
    }
}
fn canonical_socket_ip(ip: IpAddr) -> IpAddr {
    match ip {
        IpAddr::V4(ip) => IpAddr::V4(ip),
        IpAddr::V6(ip) => ip.to_ipv4_mapped().map_or(IpAddr::V6(ip), IpAddr::V4),
    }
}
#[derive(Debug)]
struct SocketPermit {
    admission: Arc<SocketAdmission>,
    remote_ip: IpAddr,
}
impl Drop for SocketPermit {
    fn drop(&mut self) {
        let mut state = self.admission.state.lock();
        state.active = state
            .active
            .checked_sub(1)
            .expect("Torii socket permit released more than once");
        let active_for_ip = state
            .active_by_ip
            .get_mut(&self.remote_ip)
            .expect("Torii socket permit source IP missing from admission state");
        *active_for_ip = active_for_ip
            .checked_sub(1)
            .expect("Torii per-IP socket permit released more than once");
        if *active_for_ip == 0 {
            state.active_by_ip.remove(&self.remote_ip);
        }
    }
}
/// Safe Tokio-to-Hyper I/O adapter used by both accepted and proxied sockets.
struct HyperTokioIo<T>(T);
impl<T> hyper::rt::Read for HyperTokioIo<T>
where
    T: AsyncRead + Unpin,
{
    fn poll_read(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        mut buf: hyper::rt::ReadBufCursor<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        let mut scratch = [0_u8; defaults::torii::HTTP_READ_CHUNK_BYTES_V1 as usize];
        let read_len = scratch.len().min(buf.remaining());
        let mut tokio_buf = ReadBuf::new(&mut scratch[..read_len]);
        match AsyncRead::poll_read(std::pin::Pin::new(&mut self.0), cx, &mut tokio_buf) {
            std::task::Poll::Ready(Ok(())) => buf.put_slice(tokio_buf.filled()),
            other => return other,
        }
        std::task::Poll::Ready(Ok(()))
    }
}
impl<T> hyper::rt::Write for HyperTokioIo<T>
where
    T: AsyncWrite + Unpin,
{
    fn poll_write(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &[u8],
    ) -> std::task::Poll<std::io::Result<usize>> {
        AsyncWrite::poll_write(std::pin::Pin::new(&mut self.0), cx, buf)
    }
    fn poll_flush(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        AsyncWrite::poll_flush(std::pin::Pin::new(&mut self.0), cx)
    }
    fn poll_shutdown(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        AsyncWrite::poll_shutdown(std::pin::Pin::new(&mut self.0), cx)
    }
    fn is_write_vectored(&self) -> bool {
        AsyncWrite::is_write_vectored(&self.0)
    }
    fn poll_write_vectored(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        bufs: &[std::io::IoSlice<'_>],
    ) -> std::task::Poll<std::io::Result<usize>> {
        AsyncWrite::poll_write_vectored(std::pin::Pin::new(&mut self.0), cx, bufs)
    }
}
struct ToriiTokioSleep(std::pin::Pin<Box<Sleep>>);
impl core::future::Future for ToriiTokioSleep {
    type Output = ();
    fn poll(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Self::Output> {
        self.0.as_mut().poll(cx)
    }
}
impl hyper::rt::Sleep for ToriiTokioSleep {}
#[derive(Clone, Copy, Debug)]
struct ToriiTokioTimer;
impl hyper::rt::Timer for ToriiTokioTimer {
    fn sleep(&self, duration: Duration) -> std::pin::Pin<Box<dyn hyper::rt::Sleep>> {
        Box::pin(ToriiTokioSleep(Box::pin(tokio::time::sleep(duration))))
    }
    fn sleep_until(&self, deadline: Instant) -> std::pin::Pin<Box<dyn hyper::rt::Sleep>> {
        Box::pin(ToriiTokioSleep(Box::pin(tokio::time::sleep_until(
            deadline.into(),
        ))))
    }
    fn now(&self) -> Instant {
        tokio::time::Instant::now().into()
    }
}
/// Tokio I/O wrapper that terminates a connection when socket writes stop making progress.
struct WriteTimeoutIo<T, L = ()> {
    inner: T,
    write_timeout: Duration,
    pending_write_timeout: Option<std::pin::Pin<Box<Sleep>>>,
    _lease: L,
}
impl<T> WriteTimeoutIo<T> {
    #[cfg(test)]
    fn new(inner: T, write_timeout: Duration) -> Self {
        Self::with_lease(inner, write_timeout, ())
    }
}
impl<T, L> WriteTimeoutIo<T, L> {
    fn with_lease(inner: T, write_timeout: Duration, lease: L) -> Self {
        Self {
            inner,
            write_timeout,
            pending_write_timeout: None,
            _lease: lease,
        }
    }
    fn clear_write_timeout(&mut self) {
        self.pending_write_timeout = None;
    }
    fn poll_write_timeout(
        &mut self,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        let timeout = self
            .pending_write_timeout
            .get_or_insert_with(|| Box::pin(tokio::time::sleep(self.write_timeout)));
        if core::future::Future::poll(timeout.as_mut(), cx).is_ready() {
            return std::task::Poll::Ready(Err(std::io::Error::new(
                std::io::ErrorKind::TimedOut,
                "Torii socket write made no progress before the configured deadline",
            )));
        }
        std::task::Poll::Pending
    }
}
impl<T, L> AsyncRead for WriteTimeoutIo<T, L>
where
    T: AsyncRead + Unpin,
    L: Unpin,
{
    fn poll_read(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &mut ReadBuf<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        let this = self.get_mut();
        std::pin::Pin::new(&mut this.inner).poll_read(cx, buf)
    }
}
impl<T, L> AsyncWrite for WriteTimeoutIo<T, L>
where
    T: AsyncWrite + Unpin,
    L: Unpin,
{
    fn poll_write(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &[u8],
    ) -> std::task::Poll<std::io::Result<usize>> {
        let this = self.get_mut();
        match std::pin::Pin::new(&mut this.inner).poll_write(cx, buf) {
            std::task::Poll::Ready(result) => {
                this.clear_write_timeout();
                std::task::Poll::Ready(result)
            }
            std::task::Poll::Pending => match this.poll_write_timeout(cx) {
                std::task::Poll::Ready(Err(error)) => std::task::Poll::Ready(Err(error)),
                std::task::Poll::Ready(Ok(())) | std::task::Poll::Pending => {
                    std::task::Poll::Pending
                }
            },
        }
    }
    fn poll_flush(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        let this = self.get_mut();
        match std::pin::Pin::new(&mut this.inner).poll_flush(cx) {
            std::task::Poll::Ready(result) => {
                this.clear_write_timeout();
                std::task::Poll::Ready(result)
            }
            std::task::Poll::Pending => this.poll_write_timeout(cx),
        }
    }
    fn poll_shutdown(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        let this = self.get_mut();
        match std::pin::Pin::new(&mut this.inner).poll_shutdown(cx) {
            std::task::Poll::Ready(result) => {
                this.clear_write_timeout();
                std::task::Poll::Ready(result)
            }
            std::task::Poll::Pending => this.poll_write_timeout(cx),
        }
    }
    fn is_write_vectored(&self) -> bool {
        self.inner.is_write_vectored()
    }
    fn poll_write_vectored(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        bufs: &[std::io::IoSlice<'_>],
    ) -> std::task::Poll<std::io::Result<usize>> {
        let this = self.get_mut();
        match std::pin::Pin::new(&mut this.inner).poll_write_vectored(cx, bufs) {
            std::task::Poll::Ready(result) => {
                this.clear_write_timeout();
                std::task::Poll::Ready(result)
            }
            std::task::Poll::Pending => match this.poll_write_timeout(cx) {
                std::task::Poll::Ready(Err(error)) => std::task::Poll::Ready(Err(error)),
                std::task::Poll::Ready(Ok(())) | std::task::Poll::Pending => {
                    std::task::Poll::Pending
                }
            },
        }
    }
}
fn validate_http_transport_config(config: ToriiHttpTransport) -> std::io::Result<usize> {
    if config.max_connections_per_ip > config.max_connections {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Torii max_connections_per_ip exceeds max_connections",
        ));
    }
    if config.header_read_timeout.is_zero() || config.write_timeout.is_zero() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Torii HTTP timeouts must be non-zero",
        ));
    }
    if config.max_headers.get() > 1024 {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Torii max_headers exceeds 1024",
        ));
    }
    let max_header_bytes = usize::try_from(config.max_header_bytes.get()).map_err(|_| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Torii max_header_bytes does not fit this platform",
        )
    })?;
    if !(8 * 1024..=1024 * 1024).contains(&max_header_bytes) {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Torii max_header_bytes is outside 8192..=1048576",
        ));
    }
    Ok(max_header_bytes)
}

#[derive(Clone, Copy)]
struct ValidatedToriiHttpTransport {
    config: ToriiHttpTransport,
    max_header_bytes: usize,
}

impl ValidatedToriiHttpTransport {
    fn new(config: ToriiHttpTransport) -> std::io::Result<Self> {
        Ok(Self {
            config,
            max_header_bytes: validate_http_transport_config(config)?,
        })
    }
}

mod public_tls;
pub use public_tls::native_https_server_identity_v1;

async fn serve_torii_http_connection<S>(
    stream: S,
    remote: std::net::SocketAddr,
    permit: SocketPermit,
    router: Router,
    config: ToriiHttpTransport,
    shutdown_signal: ShutdownSignal,
    max_header_bytes: usize,
) -> Result<(), hyper::Error>
where
    S: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + Send + 'static,
{
    let io = HyperTokioIo(WriteTimeoutIo::with_lease(
        stream,
        config.write_timeout,
        permit,
    ));
    let service = hyper::service::service_fn(move |request: Request<hyper::body::Incoming>| {
        let router = router.clone();
        async move {
            let mut request = request.map(Body::new);
            request
                .extensions_mut()
                .insert(axum::extract::ConnectInfo(remote));
            router.oneshot(request).await
        }
    });
    let mut http = hyper::server::conn::http1::Builder::new();
    http.timer(ToriiTokioTimer)
        .header_read_timeout(config.header_read_timeout)
        .max_headers(config.max_headers.get())
        .max_buf_size(max_header_bytes);
    let connection = http.serve_connection(io, service).with_upgrades();
    tokio::pin!(connection);
    tokio::select! {
        result = connection.as_mut() => result,
        () = shutdown_signal.receive() => {
            connection.as_mut().graceful_shutdown();
            connection.await
        }
    }
}
/// One accepted socket owner for both transports. Admission is already held while
/// HTTPS negotiates; successful TLS adds no authority to the shared router.
async fn serve_torii_public_connection(
    stream: TcpStream,
    remote: std::net::SocketAddr,
    permit: SocketPermit,
    https: Option<(public_tls::HttpsIdentity, tokio::time::Instant)>,
    router: Router,
    transport: ValidatedToriiHttpTransport,
    shutdown_signal: ShutdownSignal,
) -> std::io::Result<()> {
    let config = transport.config;
    let max_header_bytes = transport.max_header_bytes;
    if let Some((identity, deadline)) = https {
        let stream = tokio::select! {
            biased;
            () = shutdown_signal.receive() => return Ok(()),
            result = tokio::time::timeout_at(deadline, identity.acceptor.accept(stream)) => {
                result.map_err(|_| std::io::Error::new(
                    std::io::ErrorKind::TimedOut, "Torii TLS handshake deadline elapsed",
                ))??
            }
        };
        serve_torii_http_connection(
            stream,
            remote,
            permit,
            router,
            config,
            shutdown_signal,
            max_header_bytes,
        )
        .await
        .map_err(std::io::Error::other)
    } else {
        serve_torii_http_connection(
            stream,
            remote,
            permit,
            router,
            config,
            shutdown_signal,
            max_header_bytes,
        )
        .await
        .map_err(std::io::Error::other)
    }
}

fn observe_torii_connection_completion(
    completion: Result<std::thread::Result<(std::net::SocketAddr, std::io::Result<()>)>, JoinError>,
) -> std::io::Result<()> {
    match completion {
        Ok(Ok((remote, Ok(())))) => {
            iroha_logger::trace!(%remote, "Torii public connection closed");
            Ok(())
        }
        Ok(Ok((remote, Err(error)))) => {
            // TLS, malformed HTTP, timeout and reset failures belong only to this socket.
            iroha_logger::debug!(%remote, ?error, "Torii public connection terminated");
            Ok(())
        }
        Ok(Err(_)) => {
            iroha_logger::warn!("Torii public connection panicked and was isolated");
            Ok(())
        }
        Err(error) => Err(std::io::Error::other(format!(
            "Torii public connection task failed: {error}"
        ))),
    }
}
async fn serve_torii_public_inner(
    listener: TcpListener,
    https: Option<public_tls::BoundHttpsListener>,
    router: Router,
    transport: ValidatedToriiHttpTransport,
    shutdown_signal: ShutdownSignal,
) -> std::io::Result<()> {
    let config = transport.config;
    // There is exactly one pool and one task set, including incomplete TLS handshakes.
    let admission = SocketAdmission::new(config.max_connections, config.max_connections_per_ip);
    let mut connections = JoinSet::new();
    enum ServerEvent {
        Shutdown,
        Accepted(
            std::io::Result<(TcpStream, std::net::SocketAddr)>,
            Option<public_tls::HttpsIdentity>,
        ),
        ConnectionFinished(
            Option<
                Result<std::thread::Result<(std::net::SocketAddr, std::io::Result<()>)>, JoinError>,
            >,
        ),
    }
    loop {
        let has_connections = !connections.is_empty();
        let accept = async {
            // Unbiased selection avoids favoring plaintext over TLS under sustained ingress.
            tokio::select! {
                accepted = listener.accept() => ServerEvent::Accepted(accepted, None),
                accepted = async {
                    match &https {
                        Some(https) => ServerEvent::Accepted(https.listener.accept().await, Some(https.identity.clone())),
                        None => std::future::pending().await,
                    }
                } => accepted,
            }
        };
        let event = tokio::select! {
            biased;
            () = shutdown_signal.receive() => ServerEvent::Shutdown,
            completion = connections.join_next(), if has_connections => {
                ServerEvent::ConnectionFinished(completion)
            }
            accepted = accept => accepted,
        };
        match event {
            ServerEvent::Shutdown => break,
            ServerEvent::ConnectionFinished(Some(completion)) => {
                observe_torii_connection_completion(completion)?;
            }
            ServerEvent::ConnectionFinished(None) => {}
            ServerEvent::Accepted(Ok((stream, remote)), identity) => {
                let Some(permit) = admission.try_acquire(remote.ip()) else {
                    iroha_logger::debug!(%remote, "Torii rejected TCP connection at listener capacity");
                    drop(stream);
                    continue;
                };
                let identity = identity.map(|identity| {
                    let deadline = tokio::time::Instant::now() + identity.handshake_timeout;
                    (identity, deadline)
                });
                let router = router.clone();
                let connection_shutdown = shutdown_signal.clone();
                connections.spawn(crate::panic_recovery::catch_async_recoverable(async move {
                    let result = serve_torii_public_connection(
                        stream,
                        remote,
                        permit,
                        identity,
                        router,
                        transport,
                        connection_shutdown,
                    )
                    .await;
                    (remote, result)
                }));
            }
            ServerEvent::Accepted(Err(error), _) => {
                iroha_logger::warn!(?error, "Torii TCP accept failed; retrying");
                tokio::select! {
                    () = shutdown_signal.receive() => break,
                    () = tokio::time::sleep(Duration::from_secs(1)) => {}
                }
            }
        }
    }
    drop(listener);
    drop(https);
    let drain = async {
        while let Some(completion) = connections.join_next().await {
            observe_torii_connection_completion(completion)?;
        }
        Ok::<(), std::io::Error>(())
    };
    match tokio::time::timeout(config.write_timeout, drain).await {
        Ok(result) => result?,
        Err(_) => {
            iroha_logger::warn!(
                timeout_ms = config.write_timeout.as_millis(),
                "Torii graceful connection drain timed out; aborting remaining connections"
            );
            connections.shutdown().await;
        }
    }
    Ok(())
}

async fn serve_torii_public(
    listener: TcpListener,
    https: Option<public_tls::BoundHttpsListener>,
    router: Router,
    transport: ValidatedToriiHttpTransport,
    shutdown_signal: ShutdownSignal,
) -> std::io::Result<()> {
    let result =
        serve_torii_public_inner(listener, https, router, transport, shutdown_signal.clone()).await;
    if result.is_err() {
        shutdown_signal.send();
    }
    result
}

struct ShutdownOnDrop(ShutdownSignal);

impl ShutdownOnDrop {
    fn new(shutdown_signal: ShutdownSignal) -> Self {
        Self(shutdown_signal)
    }
}

impl Drop for ShutdownOnDrop {
    fn drop(&mut self) {
        self.0.send();
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ToriiCriticalWorkerExit {
    StoppedByShutdown,
    UnexpectedExit,
}

struct ToriiCriticalWorker {
    name: &'static str,
    task: tokio::task::JoinHandle<ToriiCriticalWorkerExit>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ToriiCriticalWorkerFailure {
    ExitedUnexpectedly(&'static str),
    Panicked(&'static str),
    Cancelled(&'static str),
    ServerExitedUnexpectedly,
}

impl ToriiCriticalWorkerFailure {
    fn from_join_error(name: &'static str, error: &tokio::task::JoinError) -> Self {
        if error.is_panic() {
            Self::Panicked(name)
        } else {
            Self::Cancelled(name)
        }
    }

    fn diagnostic(self) -> String {
        match self {
            Self::ExitedUnexpectedly(name) => {
                format!("critical Torii worker `{name}` exited before shutdown")
            }
            Self::Panicked(name) => format!("critical Torii worker `{name}` panicked"),
            Self::Cancelled(name) => format!("critical Torii worker `{name}` was cancelled"),
            Self::ServerExitedUnexpectedly => "Torii HTTP server exited before shutdown".to_owned(),
        }
    }
}

async fn rollback_torii_startup_workers(
    shutdown_signal: &ShutdownSignal,
    workers: Vec<ToriiCriticalWorker>,
    mut startup_failure: Report<Error>,
) -> Report<Error> {
    shutdown_signal.send();
    let mut workers = workers
        .into_iter()
        .map(|worker| async move { (worker.name, worker.task.await) })
        .collect::<futures_util::stream::FuturesUnordered<_>>();
    while let Some((name, result)) = workers.next().await {
        let worker_failure = match result {
            Ok(ToriiCriticalWorkerExit::StoppedByShutdown) => None,
            Ok(ToriiCriticalWorkerExit::UnexpectedExit) => {
                Some(ToriiCriticalWorkerFailure::ExitedUnexpectedly(name))
            }
            Err(error) => Some(ToriiCriticalWorkerFailure::from_join_error(name, &error)),
        };
        if let Some(worker_failure) = worker_failure {
            startup_failure = startup_failure.attach(format!(
                "startup rollback observed: {}",
                worker_failure.diagnostic()
            ));
        }
    }
    startup_failure
}

async fn supervise_torii_critical_workers<F>(
    shutdown_signal: ShutdownSignal,
    workers: Vec<ToriiCriticalWorker>,
    server: F,
) -> Result<std::io::Result<()>, ToriiCriticalWorkerFailure>
where
    F: std::future::IntoFuture<Output = std::io::Result<()>>,
{
    let server = server.into_future();
    tokio::pin!(server);
    let mut workers = workers
        .into_iter()
        .map(|worker| async move { (worker.name, worker.task.await) })
        .collect::<futures_util::stream::FuturesUnordered<_>>();
    if workers.is_empty() {
        return Ok(server.await);
    }

    tokio::select! {
        server_result = &mut server => {
            let shutdown_was_sent = shutdown_signal.is_sent();
            if !shutdown_was_sent {
                shutdown_signal.send();
            }
            let mut worker_failure = None;
            while let Some((name, result)) = workers.next().await {
                let failure = match result {
                    Ok(ToriiCriticalWorkerExit::StoppedByShutdown) => None,
                    Ok(ToriiCriticalWorkerExit::UnexpectedExit) => {
                        Some(ToriiCriticalWorkerFailure::ExitedUnexpectedly(name))
                    }
                    Err(error) => {
                        Some(ToriiCriticalWorkerFailure::from_join_error(name, &error))
                    }
                };
                if worker_failure.is_none() {
                    worker_failure = failure;
                }
            }
            if let Some(failure) = worker_failure {
                Err(failure)
            } else if server_result.is_ok() && !shutdown_was_sent {
                Err(ToriiCriticalWorkerFailure::ServerExitedUnexpectedly)
            } else {
                Ok(server_result)
            }
        }
        Some((name, result)) = workers.next() => {
            let shutdown_was_sent = shutdown_signal.is_sent();
            if !shutdown_was_sent {
                shutdown_signal.send();
            }
            let server_result = server.await;
            let first_failure = match result {
                Ok(ToriiCriticalWorkerExit::StoppedByShutdown) if shutdown_was_sent => None,
                Ok(ToriiCriticalWorkerExit::StoppedByShutdown) => {
                    Some(ToriiCriticalWorkerFailure::ExitedUnexpectedly(name))
                }
                Ok(ToriiCriticalWorkerExit::UnexpectedExit) => {
                    Some(ToriiCriticalWorkerFailure::ExitedUnexpectedly(name))
                }
                Err(error) => Some(ToriiCriticalWorkerFailure::from_join_error(name, &error)),
            };
            let mut later_failure = None;
            while let Some((name, result)) = workers.next().await {
                let failure = match result {
                    Ok(ToriiCriticalWorkerExit::StoppedByShutdown) => None,
                    Ok(ToriiCriticalWorkerExit::UnexpectedExit) => {
                        Some(ToriiCriticalWorkerFailure::ExitedUnexpectedly(name))
                    }
                    Err(error) => {
                        Some(ToriiCriticalWorkerFailure::from_join_error(name, &error))
                    }
                };
                if later_failure.is_none() {
                    later_failure = failure;
                }
            }
            if let Some(failure) = first_failure.or(later_failure) {
                Err(failure)
            } else {
                Ok(server_result)
            }
        }
    }
}
