#[cfg(test)]
pub(crate) fn authorize_query_for_test(
    request: iroha_data_model::query::QueryRequest,
    authority: iroha_data_model::account::AccountId,
) -> iroha_data_model::query::QueryRequestWithAuthority {
    use std::sync::atomic::{AtomicU64, Ordering};
    static NEXT_NONCE: AtomicU64 = AtomicU64::new(1);
    let creation_time_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("test clock follows Unix epoch")
        .as_millis()
        .try_into()
        .expect("test query creation time fits u64");
    let mut nonce = [0_u8; 32];
    nonce[24..].copy_from_slice(&NEXT_NONCE.fetch_add(1, Ordering::Relaxed).to_be_bytes());
    request.with_authority(
        signed_query_test_network_id(),
        authority,
        creation_time_ms,
        NonZeroU64::new(100_000).expect("nonzero signed-query test TTL"),
        nonce,
    )
}
#[derive(Clone)]
struct McpDispatchRouterOwner(#[allow(dead_code)] Arc<axum::Router>);

#[derive(Default)]
struct McpDispatchRouterSlot(std::sync::RwLock<std::sync::Weak<axum::Router>>);

impl McpDispatchRouterSlot {
    fn install(&self, router: axum::Router) -> McpDispatchRouterOwner {
        let router = Arc::new(router);
        *self
            .0
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Arc::downgrade(&router);
        McpDispatchRouterOwner(router)
    }

    fn load(&self) -> Option<axum::Router> {
        self.0
            .read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .upgrade()
            .map(|router| (*router).clone())
    }
}

