/// Norito-RPC rollout summary shared with RPC clients.
struct RpcNoritoRpcCapability {
    /// Whether Norito-RPC decoding is enabled.
    enabled: bool,
    /// Whether ingress requires mTLS before allowing Norito-RPC.
    require_mtls: bool,
    /// Rollout stage label (`disabled`, `canary`, `ga`).
    stage: String,
    /// Size of the canary allowlist.
    canary_allowlist_size: usize,
}
impl From<&NoritoRpcTransport> for RpcNoritoRpcCapability {
    fn from(value: &NoritoRpcTransport) -> Self {
        Self {
            enabled: value.enabled,
            require_mtls: value.require_mtls,
            stage: value.stage.label().to_string(),
            canary_allowlist_size: value.allowed_clients.len(),
        }
    }
}
fn evaluate_norito_rpc_gate(
    cfg: &NoritoRpcTransport,
    allowed_client_digests: &limits::ApiTokenDigestSet,
    trusted_proxy_nets: &[limits::IpNet],
    headers: &HeaderMap,
    remote_ip: Option<IpAddr>,
) -> Result<(), NoritoRpcGateFailure> {
    if !cfg.enabled {
        return Err(NoritoRpcGateFailure::Disabled);
    }
    if cfg.require_mtls && !norito_rpc_mtls_present(headers, remote_ip, trusted_proxy_nets) {
        return Err(NoritoRpcGateFailure::MtlsRequired);
    }
    match cfg.stage {
        NoritoRpcStage::Disabled => Err(NoritoRpcGateFailure::Disabled),
        NoritoRpcStage::Ga => Ok(()),
        NoritoRpcStage::Canary => {
            let token =
                norito_rpc_token_from_headers(headers).ok_or(NoritoRpcGateFailure::CanaryDenied)?;
            if allowed_client_digests.authenticate(token).is_some() {
                Ok(())
            } else {
                Err(NoritoRpcGateFailure::CanaryDenied)
            }
        }
    }
}
fn norito_rpc_token_from_headers(headers: &HeaderMap) -> Option<&str> {
    let mut values = headers.get_all(HEADER_API_TOKEN).iter();
    let value = values
        .next()
        .and_then(|value| value.to_str().ok())
        .filter(|value| !value.is_empty())?;
    values.next().is_none().then_some(value)
}
fn norito_rpc_mtls_present(
    headers: &HeaderMap,
    remote: Option<IpAddr>,
    trusted_proxies: &[limits::IpNet],
) -> bool {
    limits::has_trusted_forwarded_header(headers, remote, trusted_proxies, HEADER_MTLS_FORWARD)
}
fn norito_rpc_error_response(failure: NoritoRpcGateFailure) -> axum::response::Response {
    match failure {
        NoritoRpcGateFailure::Disabled => norito_rpc_error(
            StatusCode::FORBIDDEN,
            NORITO_RPC_DISABLED_CODE,
            "Norito-RPC is disabled on this Torii node",
        ),
        NoritoRpcGateFailure::CanaryDenied => norito_rpc_error(
            StatusCode::FORBIDDEN,
            NORITO_RPC_CANARY_DENIED_CODE,
            "Norito-RPC canary allowlist rejected this token",
        ),
        NoritoRpcGateFailure::MtlsRequired => norito_rpc_error(
            StatusCode::FORBIDDEN,
            NORITO_RPC_MTLS_REQUIRED_CODE,
            "Norito-RPC requires mTLS at ingress",
        ),
    }
}
fn norito_rpc_error(
    status: StatusCode,
    code: &str,
    message: &'static str,
) -> axum::response::Response {
    match axum::response::Response::builder()
        .status(status)
        .header(HEADER_NORITO_RPC_ERROR, code)
        .header(
            axum::http::header::RETRY_AFTER,
            NORITO_RPC_RETRY_AFTER_SECONDS,
        )
        .body(Body::from(message))
    {
        Ok(response) => response,
        Err(err) => {
            iroha_logger::error!(?err, "failed to build Norito-RPC gate error response");
            axum::response::Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::from("failed to evaluate Norito-RPC gate"))
                .expect("static response build succeeds")
        }
    }
}
async fn inject_remote_addr_header(
    State(app): State<SharedAppState>,
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    use axum::{extract::ConnectInfo, http::header::HeaderName};
    let header = HeaderName::from_static(limits::REMOTE_ADDR_HEADER);
    let remote_ip = req
        .extensions()
        .get::<ConnectInfo<std::net::SocketAddr>>()
        .map(|connect| connect.0.ip());
    let resolved = limits::ingress_remote_ip(req.headers(), remote_ip, &app.trusted_proxy_nets);
    req.headers_mut().remove(&header);
    if let Some(ip) = resolved {
        if let Ok(value) = ip.to_string().parse() {
            req.headers_mut().insert(header, value);
        }
    }
    Ok(next.run(req).await)
}
const REQUEST_ID_HEADER: &str = "x-request-id";
const MAX_REQUEST_ID_LENGTH: usize = 128;
#[derive(Clone, Debug)]
struct RequestCorrelationId(String);
fn valid_incoming_request_id(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= MAX_REQUEST_ID_LENGTH
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b':'))
}
fn generate_request_id() -> String {
    static SEQUENCE: AtomicU64 = AtomicU64::new(1);
    let timestamp_nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let sequence = SEQUENCE.fetch_add(1, AtomicOrdering::Relaxed);
    let process_id = std::process::id();
    let mut material = Vec::with_capacity(16 + 8 + 4);
    material.extend_from_slice(&timestamp_nanos.to_le_bytes());
    material.extend_from_slice(&sequence.to_le_bytes());
    material.extend_from_slice(&process_id.to_le_bytes());
    hex::encode(blake3_hash(&material).as_bytes())
}
fn single_valid_incoming_request_id(headers: &HeaderMap) -> Option<&str> {
    let mut values = headers.get_all(REQUEST_ID_HEADER).iter();
    let value = values.next()?;
    if values.next().is_some() {
        return None;
    }
    value
        .to_str()
        .ok()
        .filter(|value| valid_incoming_request_id(value))
}
async fn attach_request_id(
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let request_id = single_valid_incoming_request_id(req.headers())
        .map(str::to_owned)
        .unwrap_or_else(generate_request_id);
    req.extensions_mut()
        .insert(RequestCorrelationId(request_id.clone()));
    let mut response = next.run(req).await;
    if let Ok(value) = HeaderValue::from_str(&request_id) {
        response
            .headers_mut()
            .insert(HeaderName::from_static(REQUEST_ID_HEADER), value);
    }
    Ok(response)
}
async fn inject_loopback_connect_info_when_missing(
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    if req
        .extensions()
        .get::<axum::extract::ConnectInfo<std::net::SocketAddr>>()
        .is_none()
    {
        req.extensions_mut()
            .insert(axum::extract::ConnectInfo(std::net::SocketAddr::from((
                [127, 0, 0, 1],
                0,
            ))));
    }
    Ok(next.run(req).await)
}
async fn enforce_preauth(
    State(app): State<SharedAppState>,
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    use axum::extract::ConnectInfo;
    // MCP subrequests are in-process work admitted by the outer connection's
    // pre-auth guard. Counting them again lets one valid tool batch exhaust and
    // ban its own client/NAT address. This extension cannot cross an HTTP
    // listener boundary, so external callers cannot forge the bypass.
    if req.extensions().get::<mcp::InternalMcpDispatch>().is_some() {
        return Ok(next.run(req).await);
    }
    let transport_ip = req
        .extensions()
        .get::<ConnectInfo<std::net::SocketAddr>>()
        .map(|ci| ci.0.ip());
    // `inject_remote_addr_header` runs before this middleware and replaces any
    // untrusted caller-supplied value with the accepted transport address.
    // Use that normalized client address so trusted reverse-proxy traffic does
    // not collapse into a single pre-auth bucket keyed by the proxy itself.
    let remote_ip = limits::effective_remote_ip(req.headers(), transport_ip);
    let scheme = ConnScheme::from_request(&req);
    match app.acquire_preauth(remote_ip, scheme).await {
        Ok(guard) => {
            if matches!(scheme, ConnScheme::Ws) && !request_has_canonical_websocket_handshake(&req)
            {
                drop(guard);
                let mut response = utils::respond_with_status_and_format(
                    StatusCode::BAD_REQUEST,
                    ErrorEnvelope::new(
                        "websocket_handshake_invalid",
                        "WebSocket routes require one canonical RFC 6455 version 13 upgrade handshake",
                    ),
                    early_rejection_response_format(req.headers()),
                );
                append_vary_accept(response.headers_mut());
                return Ok(response);
            }
            if matches!(scheme, ConnScheme::NoritoRpc) {
                if let Err(resp) = app.check_norito_rpc_allowed(req.headers(), remote_ip) {
                    drop(guard);
                    return Ok(*resp);
                }
            }
            let handoff = PreAuthGuardHandoff::new(guard);
            req.extensions_mut().insert(handoff.clone());
            let response = next.run(req).await;
            Ok(match handoff.take() {
                Some(guard) => hold_preauth_guard_in_response_body(response, guard),
                None => response,
            })
        }
        Err(reason) => {
            app.record_preauth_reject(reason);
            let retry_after_seconds = reason.retry_after_seconds();
            let (status, code, message) = match reason {
                limits::RejectReason::GlobalCap => (
                    StatusCode::SERVICE_UNAVAILABLE,
                    "preauth_global_capacity",
                    "Torii pre-auth global connection limit reached.",
                ),
                limits::RejectReason::IpCap => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "preauth_ip_capacity",
                    "Torii pre-auth per-IP connection limit reached.",
                ),
                limits::RejectReason::RateLimited { .. } => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "preauth_rate_limited",
                    "Torii pre-auth rate limit exceeded.",
                ),
                limits::RejectReason::Banned { .. } => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "preauth_temporarily_banned",
                    "Torii pre-auth temporary ban is in effect.",
                ),
                limits::RejectReason::SchemeCap => (
                    StatusCode::SERVICE_UNAVAILABLE,
                    "preauth_scheme_capacity",
                    "Torii pre-auth transport connection limit reached.",
                ),
            };
            let payload = ErrorEnvelope::new(code, message).with_details(ErrorDetails {
                retry_after_seconds: Some(retry_after_seconds),
                ..Default::default()
            });
            let mut response = utils::respond_with_status_and_format(
                status,
                payload,
                early_rejection_response_format(req.headers()),
            );
            response.headers_mut().insert(
                axum::http::header::RETRY_AFTER,
                HeaderValue::from_str(&retry_after_seconds.to_string())
                    .expect("unsigned retry delay is a valid header value"),
            );
            append_vary_accept(response.headers_mut());
            Ok(response)
        }
    }
}
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ApiTokenEvaluation {
    Disabled,
    Unavailable,
    Invalid,
    Authenticated(limits::ApiTokenPrincipal),
}
impl ApiTokenEvaluation {
    /// Returns a rate-limit principal only after successful authentication.
    ///
    /// A caller-supplied header is deliberately ignored in [`Self::Disabled`]
    /// mode so rotating arbitrary token text cannot evade authority-based
    /// quotas.
    fn authenticated_principal(self) -> Option<limits::ApiTokenPrincipal> {
        match self {
            Self::Authenticated(principal) => Some(principal),
            Self::Disabled | Self::Unavailable | Self::Invalid => None,
        }
    }
}
fn evaluate_api_token(
    require_api_token: bool,
    configured_tokens: &limits::ApiTokenDigestSet,
    headers: &HeaderMap,
) -> ApiTokenEvaluation {
    if !require_api_token {
        return ApiTokenEvaluation::Disabled;
    }
    if configured_tokens.is_empty() {
        return ApiTokenEvaluation::Unavailable;
    }
    let mut values = headers.get_all(HEADER_API_TOKEN).iter();
    let Some(value) = values.next() else {
        return ApiTokenEvaluation::Invalid;
    };
    if values.next().is_some() {
        return ApiTokenEvaluation::Invalid;
    }
    value
        .to_str()
        .ok()
        .and_then(|token| configured_tokens.authenticate(token))
        .map_or(
            ApiTokenEvaluation::Invalid,
            ApiTokenEvaluation::Authenticated,
        )
}
fn api_token_rejection(app: &AppState, headers: &HeaderMap) -> Option<Response> {
    api_token_rejection_with_policy(
        app.requires_api_token(),
        app.api_token_digests.as_ref(),
        headers,
    )
}
fn api_token_rejection_with_policy(
    require_api_token: bool,
    configured_tokens: &limits::ApiTokenDigestSet,
    headers: &HeaderMap,
) -> Option<Response> {
    match evaluate_api_token(require_api_token, configured_tokens, headers) {
        ApiTokenEvaluation::Disabled | ApiTokenEvaluation::Authenticated(_) => None,
        ApiTokenEvaluation::Unavailable => {
            let format = early_rejection_response_format(headers);
            let payload = ErrorEnvelope::new(
                "api_token_unavailable",
                "Torii requires an API token, but no tokens are configured.",
            )
            .with_details(ErrorDetails {
                retry_after_seconds: Some(1),
                ..Default::default()
            });
            let mut response = utils::respond_with_status_and_format(
                StatusCode::SERVICE_UNAVAILABLE,
                payload,
                format,
            );
            response.headers_mut().insert(
                axum::http::header::RETRY_AFTER,
                HeaderValue::from_static("1"),
            );
            append_vary_accept(response.headers_mut());
            Some(response)
        }
        ApiTokenEvaluation::Invalid => {
            let format = early_rejection_response_format(headers);
            let mut response = utils::respond_with_status_and_format(
                StatusCode::UNAUTHORIZED,
                ErrorEnvelope::new(
                    "api_token_required",
                    "A valid Torii API token is required for this request.",
                ),
                format,
            );
            response.headers_mut().insert(
                axum::http::header::WWW_AUTHENTICATE,
                HeaderValue::from_static("IrohaApiToken realm=\"torii\""),
            );
            append_vary_accept(response.headers_mut());
            Some(response)
        }
    }
}
#[cfg(feature = "app_api")]
fn authenticate_onboarding_api_token(
    app: &AppState,
    headers: &HeaderMap,
) -> Result<AuthenticatedOnboardingScope, Response> {
    let format = early_rejection_response_format(headers);
    let Some(signer) = app.account_onboarding.as_ref() else {
        let mut response = utils::respond_with_status_and_format(
            StatusCode::SERVICE_UNAVAILABLE,
            ErrorEnvelope::new(
                "onboarding_auth_unavailable",
                "Signer-backed account onboarding is unavailable because its scoped credential token digests are not configured.",
            ),
            format,
        );
        append_vary_accept(response.headers_mut());
        return Err(response);
    };
    if signer.api_token_hashes_by_domain.is_empty()
        && signer.api_token_hashes_by_dataspace.is_empty()
    {
        let mut response = utils::respond_with_status_and_format(
            StatusCode::SERVICE_UNAVAILABLE,
            ErrorEnvelope::new(
                "onboarding_auth_unavailable",
                "Signer-backed account onboarding is unavailable because its scoped credential token digests are not configured.",
            ),
            format,
        );
        append_vary_accept(response.headers_mut());
        return Err(response);
    };
    let mut values = headers.get_all(HEADER_ONBOARDING_API_TOKEN).iter();
    let supplied = values.next().and_then(|value| value.to_str().ok());
    let one_value = values.next().is_none();
    let actual_hash = supplied
        .filter(|token| {
            (32..=256).contains(&token.len())
                && token
                    .as_bytes()
                    .iter()
                    .all(|byte| (b'!'..=b'~').contains(byte))
        })
        .map(|token| *blake3::hash(token.as_bytes()).as_bytes());
    let mut authenticated_scope = None;
    let mut match_count = 0_u8;
    if one_value {
        if let Some(actual_hash) = actual_hash {
            for (domain, expected_hashes) in &signer.api_token_hashes_by_domain {
                for expected_hash in expected_hashes {
                    if iroha_torii_shared::connect_sdk::constant_time_eq(
                        expected_hash,
                        &actual_hash,
                    ) {
                        match_count = match_count.saturating_add(1);
                        authenticated_scope =
                            Some(AuthenticatedOnboardingScope::Domain(domain.clone()));
                    }
                }
            }
            for (dataspace, expected_hashes) in &signer.api_token_hashes_by_dataspace {
                for expected_hash in expected_hashes {
                    if iroha_torii_shared::connect_sdk::constant_time_eq(
                        expected_hash,
                        &actual_hash,
                    ) {
                        match_count = match_count.saturating_add(1);
                        authenticated_scope =
                            Some(AuthenticatedOnboardingScope::Dataspace(dataspace.clone()));
                    }
                }
            }
        }
    }
    if match_count == 1
        && let Some(authenticated_scope) = authenticated_scope
    {
        return Ok(authenticated_scope);
    }
    let mut response = utils::respond_with_status_and_format(
        StatusCode::UNAUTHORIZED,
        ErrorEnvelope::new(
            "onboarding_auth_required",
            "A valid dedicated onboarding token is required.",
        ),
        format,
    );
    response.headers_mut().insert(
        axum::http::header::WWW_AUTHENTICATE,
        HeaderValue::from_static("IrohaOnboardingToken"),
    );
    append_vary_accept(response.headers_mut());
    Err(response)
}
#[cfg(feature = "app_api")]
async fn enforce_onboarding_api_token(
    State(app): State<SharedAppState>,
    mut request: axum::http::Request<Body>,
    next: Next,
) -> Result<Response, Infallible> {
    let protected_route = request
        .extensions()
        .get::<MatchedRouteMetadata>()
        .is_some_and(|route| {
            let stable_route_id = route.stable_route_id();
            stable_route_id
                == route_catalog::application_api::ACCOUNTS_ONBOARD_PLAN_POST.stable_route_id()
                || stable_route_id
                    == route_catalog::application_api::ACCOUNTS_ONBOARD_PREPARE_POST
                        .stable_route_id()
                || stable_route_id
                    == route_catalog::application_api::ACCOUNTS_ONBOARD_POST.stable_route_id()
                || stable_route_id
                    == route_catalog::application_api::ACCOUNTS_ONBOARDING_READINESS_GET
                        .stable_route_id()
        });
    if !protected_route {
        return Ok(next.run(request).await);
    }
    for (name, value) in request.headers_mut().iter_mut() {
        if name.as_str() == HEADER_ONBOARDING_API_TOKEN {
            value.set_sensitive(true);
        }
    }
    let authenticated_scope = match authenticate_onboarding_api_token(&app, request.headers()) {
        Ok(scope) => scope,
        Err(response) => return Ok(response),
    };
    request.headers_mut().remove(HEADER_ONBOARDING_API_TOKEN);
    request
        .extensions_mut()
        .insert(AuthenticatedOnboardingDomain(authenticated_scope));
    Ok(next.run(request).await)
}
fn is_public_sorafs_gateway_route(request: &axum::http::Request<Body>) -> bool {
    request
        .extensions()
        .get::<MatchedRouteMetadata>()
        .is_some_and(is_public_sorafs_gateway_metadata)
}

fn is_public_sorafs_gateway_metadata(route: &MatchedRouteMetadata) -> bool {
    let stable_route_id = route.stable_route_id();
    [
        route_catalog::sorafs::CID_LOOKUP.stable_route_id(),
        route_catalog::sorafs::SITE_MANIFEST.stable_route_id(),
        route_catalog::sorafs::CID_ROOT.stable_route_id(),
        route_catalog::sorafs::CID_PATH.stable_route_id(),
        SORAFS_HOST_SITE_ROOT_ROUTE.stable_route_id(),
        SORAFS_HOST_SITE_PATH_ROUTE.stable_route_id(),
    ]
    .contains(&stable_route_id)
}

fn is_public_sorafs_gateway_path(request: &axum::http::Request<Body>) -> bool {
    if is_public_sorafs_gateway_route(request) {
        return true;
    }
    let path = request.uri().path();
    if path == route_catalog::sorafs::SITE_MANIFEST.path() {
        return true;
    }
    let exact_one_segment = |prefix: &str| {
        path.strip_prefix(prefix)
            .is_some_and(|suffix| !suffix.is_empty() && !suffix.contains('/'))
    };
    let lookup_prefix = route_catalog::sorafs::CID_LOOKUP
        .path()
        .strip_suffix("{cid}")
        .expect("CID lookup route ends in its CID placeholder");
    let gateway_prefix = route_catalog::sorafs::CID_ROOT
        .path()
        .strip_suffix("{cid}")
        .expect("CID root route ends in its CID placeholder");
    exact_one_segment(lookup_prefix)
        || path.strip_prefix(gateway_prefix).is_some_and(|suffix| {
            let mut segments = suffix.split('/');
            segments.next().is_some_and(|cid| !cid.is_empty())
                && segments.all(|segment| !segment.is_empty())
        })
}

async fn enforce_api_token(
    State(app): State<SharedAppState>,
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    if !app.is_private_root() && is_public_sorafs_gateway_route(&req) {
        return Ok(next.run(req).await);
    }
    let api_token_required = app.requires_api_token();
    if let Some(mut response) = api_token_rejection(&app, req.headers()) {
        if api_token_required {
            response.headers_mut().insert(
                axum::http::header::CACHE_CONTROL,
                HeaderValue::from_static("private, no-store"),
            );
        }
        return Ok(response);
    }
    let mut response = next.run(req).await;
    if api_token_required {
        response.headers_mut().insert(
            axum::http::header::CACHE_CONTROL,
            HeaderValue::from_static("private, no-store"),
        );
    }
    Ok(response)
}
/// Prevent a shared intermediary from replaying responses protected by the
/// deployment API token. The exact public SoraFS local-gateway allowlist keeps
/// its immutable content responses anonymously cacheable only on a global root.
async fn enforce_required_api_token_private_no_store(
    State(app): State<SharedAppState>,
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let public_sorafs_gateway_path = is_public_sorafs_gateway_path(&req);
    let mut response = next.run(req).await;
    let public_sorafs_gateway = public_sorafs_gateway_path
        || response
            .extensions()
            .get::<MatchedRouteMetadata>()
            .is_some_and(is_public_sorafs_gateway_metadata);
    if app.is_private_root() || (app.requires_api_token() && !public_sorafs_gateway) {
        response.headers_mut().insert(
            axum::http::header::CACHE_CONTROL,
            HeaderValue::from_static("private, no-store"),
        );
    }
    Ok(response)
}
#[cfg(feature = "app_api")]
const fn canonical_base64_max_len(decoded_len: usize) -> usize {
    4 * decoded_len.div_ceil(3)
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BoundedContentLengthError {
    TooLarge,
    Invalid,
}
fn validate_bounded_content_length(
    headers: &axum::http::HeaderMap,
    max_body_bytes: usize,
) -> Result<Option<usize>, BoundedContentLengthError> {
    use axum::http::header::{CONTENT_LENGTH, TRANSFER_ENCODING};
    let mut values = headers.get_all(CONTENT_LENGTH).iter();
    let Some(value) = values.next() else {
        return Ok(None);
    };
    if values.next().is_some() || headers.contains_key(TRANSFER_ENCODING) {
        return Err(BoundedContentLengthError::Invalid);
    }
    let encoded = value.as_bytes();
    if encoded.is_empty() || !encoded.iter().all(u8::is_ascii_digit) {
        return Err(BoundedContentLengthError::Invalid);
    }
    let declared = match value
        .to_str()
        .ok()
        .and_then(|value| value.parse::<u64>().ok())
    {
        Some(declared) => declared,
        None => return Err(BoundedContentLengthError::TooLarge),
    };
    if declared > u64::try_from(max_body_bytes).unwrap_or(u64::MAX) {
        return Err(BoundedContentLengthError::TooLarge);
    }
    usize::try_from(declared)
        .map(Some)
        .map_err(|_| BoundedContentLengthError::TooLarge)
}
#[cfg(feature = "app_api")]
async fn enforce_soracloud_signed_mutation_request(
    State(app): State<SharedAppState>,
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let authentication_owner =
        match crate::history_producer::HistoryProducerOwner::authentication_read(&app) {
            Ok(owner) => owner,
            Err(error) => {
                return Ok(error.into_response());
            }
        };

    let path = req.uri().path().to_owned();
    let response_format =
        match utils::negotiate_response_format(req.headers().get(axum::http::header::ACCEPT)) {
            Ok(format) => format,
            Err(mut response) => {
                append_vary_accept(response.headers_mut());
                return Ok(response);
            }
        };
    let (mut parts, body) = req.into_parts();
    // These headers are an internal middleware-to-handler channel. Strip all
    // client values before authentication so a future serialization failure
    // can only leave the header absent, never preserve attacker-supplied
    // identity material.
    for header in [
        soracloud::VERIFIED_ACCOUNT_HEADER,
        soracloud::VERIFIED_SIGNER_HEADER,
        soracloud::VERIFIED_SIGNERS_HEADER,
    ] {
        parts.headers.remove(header);
    }
    let body_limit = soracloud_signed_mutation_body_limit(&app);
    let body = match axum::body::to_bytes(body, body_limit).await {
        Ok(body) => body,
        Err(error) => {
            return Ok(soracloud_body_limit_response(
                body_limit,
                &path,
                error,
                response_format,
            ));
        }
    };
    let verified = match crate::app_auth::verify_canonical_network_request(
        &app.state,
        app.state.network_id_ref(),
        &parts.headers,
        &parts.method,
        &parts.uri,
        body.as_ref(),
        None,
        authentication_owner.allocation_context(),
    ) {
        Ok(Some(verified)) => verified,
        Ok(None) => {
            return Ok(Error::Query(iroha_data_model::ValidationFail::NotPermitted(
                "signed account headers are required for SoraCloud command endpoints".to_owned(),
            ))
            .into_response());
        }
        Err(error) => return Ok(error.into_response()),
    };
    let route_group = soracloud_signed_mutation_route_group(&path);
    let rate_key = soracloud_signed_mutation_rate_key(&verified.account, route_group);
    if !app.soracloud_mutation_rate_limiter.allow(&rate_key).await {
        return Ok(soracloud_rate_limit_response(route_group, response_format));
    }
    let _mutation_permit = match app.soracloud_mutation_inflight.clone().try_acquire_owned() {
        Ok(permit) => permit,
        Err(_) => {
            return Ok(soracloud_inflight_limit_response(
                route_group,
                response_format,
            ));
        }
    };
    if let Ok(value) = HeaderValue::from_bytes(verified.account.to_string().as_bytes()) {
        parts.headers.insert(
            HeaderName::from_static(soracloud::VERIFIED_ACCOUNT_HEADER),
            value,
        );
    }
    if let Ok(value) = HeaderValue::from_str(&verified.signer.to_string()) {
        parts.headers.insert(
            HeaderName::from_static(soracloud::VERIFIED_SIGNER_HEADER),
            value,
        );
    }
    if let Ok(encoded) =
        norito::to_bytes(&verified.verified_signers).map(|bytes| BASE64_STANDARD.encode(bytes))
        && let Ok(value) = HeaderValue::from_str(&encoded)
    {
        parts.headers.insert(
            HeaderName::from_static(soracloud::VERIFIED_SIGNERS_HEADER),
            value,
        );
    }
    Ok(next
        .run(axum::http::Request::from_parts(parts, Body::from(body)))
        .await)
}
#[cfg(all(test, feature = "app_api"))]
#[path = "tests/soracloud_signed_mutation_middleware.rs"]
mod soracloud_signed_mutation_middleware_tests;
#[cfg(feature = "app_api")]
fn soracloud_signed_mutation_body_limit(app: &AppState) -> usize {
    app.soracloud_mutation_max_body_bytes.max(1)
}
#[cfg(feature = "app_api")]
fn soracloud_body_limit_response(
    body_limit: usize,
    path: &str,
    error: axum::Error,
    format: ResponseFormat,
) -> axum::response::Response {
    let route_group = if path.starts_with("/v1/soracloud/model/upload/") {
        "upload"
    } else {
        "mutation"
    };
    iroha_logger::warn!(%path, body_limit, ?error, "Soracloud mutation body exceeded limit");
    utils::respond_with_status_and_format(
        StatusCode::PAYLOAD_TOO_LARGE,
        ErrorEnvelope::new(
            "request_payload_too_large",
            format!("Soracloud {route_group} request body exceeds the configured limit."),
        )
        .with_details(ErrorDetails {
            endpoint: Some(path.to_owned()),
            expected: Some(format!("at most {body_limit} bytes")),
            ..Default::default()
        }),
        format,
    )
}
#[cfg(feature = "app_api")]
fn soracloud_signed_mutation_route_group(path: &str) -> &'static str {
    if path.starts_with("/v1/soracloud/model/upload/") {
        "upload"
    } else if path.starts_with("/v1/soracloud/model/") {
        "model"
    } else if path.starts_with("/v1/soracloud/hf/") {
        "hf"
    } else {
        "mutation"
    }
}
#[cfg(feature = "app_api")]
fn soracloud_signed_mutation_rate_key(account: &AccountId, route_group: &str) -> String {
    format!("soracloud:{route_group}:account:{account}")
}
#[cfg(feature = "app_api")]
fn soracloud_rate_limit_response(
    route_group: &str,
    format: ResponseFormat,
) -> axum::response::Response {
    let mut response = utils::respond_with_status_and_format(
        StatusCode::TOO_MANY_REQUESTS,
        ErrorEnvelope::new(
            "request_rate_limited",
            format!("Soracloud {route_group} request rate limit exceeded."),
        )
        .with_details(ErrorDetails {
            retry_after_seconds: Some(1),
            ..Default::default()
        }),
        format,
    );
    response.headers_mut().insert(
        axum::http::header::RETRY_AFTER,
        HeaderValue::from_static("1"),
    );
    response
}
#[cfg(feature = "app_api")]
fn soracloud_inflight_limit_response(
    route_group: &str,
    format: ResponseFormat,
) -> axum::response::Response {
    let mut response = utils::respond_with_status_and_format(
        StatusCode::SERVICE_UNAVAILABLE,
        ErrorEnvelope::new(
            "request_concurrency_limited",
            format!("Soracloud {route_group} request concurrency limit exceeded."),
        )
        .with_details(ErrorDetails {
            retry_after_seconds: Some(1),
            ..Default::default()
        }),
        format,
    );
    response.headers_mut().insert(
        axum::http::header::RETRY_AFTER,
        HeaderValue::from_static("1"),
    );
    response
}
fn is_json_content_type(raw: &str) -> bool {
    let base = raw.split(';').next().map(str::trim).unwrap_or_default();
    if base.is_empty() {
        return false;
    }
    if base.eq_ignore_ascii_case("application/json") {
        return true;
    }
    let lower = base.to_ascii_lowercase();
    lower.starts_with("application/") && lower.ends_with("+json")
}
fn normalize_json_content_type(raw: &str) -> Option<String> {
    if !is_json_content_type(raw) {
        return None;
    }
    let mut parts = raw.split(';');
    let media_type = parts.next()?.trim();
    if media_type.is_empty() {
        return None;
    }
    let mut normalized = String::from(media_type);
    for part in parts {
        let parameter = part.trim();
        if parameter.is_empty() {
            continue;
        }
        let is_charset = parameter.split_once('=').map_or(false, |(name, _)| {
            name.trim().eq_ignore_ascii_case("charset")
        });
        if is_charset {
            continue;
        }
        normalized.push_str("; ");
        normalized.push_str(parameter);
    }
    normalized.push_str("; charset=utf-8");
    Some(normalized)
}
fn normalize_json_response_content_type(headers: &mut HeaderMap) {
    let raw = headers
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok());
    let Some(raw_content_type) = raw else {
        return;
    };
    let Some(normalized) = normalize_json_content_type(raw_content_type) else {
        return;
    };
    if let Ok(value) = HeaderValue::from_str(&normalized) {
        headers.insert(axum::http::header::CONTENT_TYPE, value);
    }
}
async fn enforce_json_utf8_charset(
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let mut response = next.run(req).await;
    normalize_json_response_content_type(response.headers_mut());
    Ok(response)
}
fn coalesced_accept_header(headers: &HeaderMap) -> Result<Option<HeaderValue>, &'static str> {
    let mut values = headers.get_all(axum::http::header::ACCEPT).iter();
    let Some(first) = values.next() else {
        return Ok(None);
    };
    let Some(second) = values.next() else {
        return Ok(None);
    };
    let mut combined = String::new();
    for value in [first, second].into_iter().chain(values) {
        let value = value
            .to_str()
            .map_err(|_| "The Accept header is not valid ASCII.")?;
        if !combined.is_empty() {
            combined.push_str(", ");
        }
        combined.push_str(value);
    }
    HeaderValue::from_str(&combined)
        .map(Some)
        .map_err(|_| "The combined Accept header is invalid.")
}
fn content_type_header_error(headers: &HeaderMap) -> Option<&'static str> {
    let mut values = headers.get_all(axum::http::header::CONTENT_TYPE).iter();
    let first = values.next()?;
    if values.next().is_some() {
        return Some("Content-Type must appear exactly once.");
    }
    first
        .to_str()
        .is_err()
        .then_some("Content-Type is not valid ASCII.")
}
/// Select the best representation for a rejection which deliberately runs
/// before strict Accept validation. Authentication and capacity errors take
/// precedence over malformed or unacceptable media preferences; valid media
/// preferences are still honored, while invalid input receives deterministic
/// JSON so the original rejection cannot be hidden by a secondary 406.
fn early_rejection_response_format(headers: &HeaderMap) -> ResponseFormat {
    let combined = match coalesced_accept_header(headers) {
        Ok(combined) => combined,
        Err(_) => return ResponseFormat::Json,
    };
    let accept = combined
        .as_ref()
        .or_else(|| headers.get(axum::http::header::ACCEPT));
    utils::negotiate_response_format(accept).unwrap_or(ResponseFormat::Json)
}
fn emergency_fast_route_is_available(route: &MatchedRouteMetadata) -> bool {
    let route_id = route.stable_route_id();
    route_id == route_catalog::core::HEALTH.stable_route_id()
        || route_id == route_catalog::core::LIVEZ.stable_route_id()
        || route_id == route_catalog::core::READYZ.stable_route_id()
        || route_id == route_catalog::core::PEERS.stable_route_id()
        || route_id == route_catalog::core::CONFIGURATION_GET.stable_route_id()
        || route_id == "http.route_not_found"
        || route_id == "http.method_not_allowed"
}
async fn enforce_emergency_fast_surface(
    State(app): State<SharedAppState>,
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<AxResponse, Infallible> {
    if !app.kura.emergency_fast_startup_enabled()
        || req
            .extensions()
            .get::<MatchedRouteMetadata>()
            .is_some_and(emergency_fast_route_is_available)
    {
        return Ok(next.run(req).await);
    }
    let format = early_rejection_response_format(req.headers());
    Ok(utils::respond_with_status_and_format(
        StatusCode::SERVICE_UNAVAILABLE,
        ErrorEnvelope::new(
            "emergency_fast_surface_unavailable",
            "This API needs persisted block data, derived state, or a mutable runtime that emergency Fast mode deliberately leaves offline. Use health, liveness, readiness, peer, or configuration diagnostics, or restart in Strict mode.",
        ),
        format,
    ))
}
async fn coalesce_accept_headers(
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let combined = match coalesced_accept_header(req.headers()) {
        Ok(combined) => combined,
        Err(message) => {
            let mut response = utils::respond_with_status_and_format(
                StatusCode::NOT_ACCEPTABLE,
                ErrorEnvelope::new("response_not_acceptable", message),
                ResponseFormat::Json,
            );
            append_vary_accept(response.headers_mut());
            return Ok(response);
        }
    };
    if let Some(combined) = combined {
        req.headers_mut()
            .insert(axum::http::header::ACCEPT, combined);
    }
    if let Some(message) = content_type_header_error(req.headers()) {
        let format =
            match utils::negotiate_response_format(req.headers().get(axum::http::header::ACCEPT)) {
                Ok(format) => format,
                Err(mut response) => {
                    append_vary_accept(response.headers_mut());
                    return Ok(response);
                }
            };
        let mut response = utils::respond_with_status_and_format(
            StatusCode::BAD_REQUEST,
            ErrorEnvelope::new("request_content_type_invalid", message),
            format,
        );
        append_vary_accept(response.headers_mut());
        return Ok(response);
    }
    Ok(next.run(req).await)
}
fn has_percent_encoded_separator(path: &str) -> bool {
    path.as_bytes().windows(3).any(|window| {
        window[0] == b'%'
            && ((window[1] == b'2' && matches!(window[2], b'f' | b'F'))
                || (window[1] == b'5' && matches!(window[2], b'c' | b'C')))
    })
}
fn is_canonical_proof_record_path(path: &str) -> bool {
    let Some(encoded_id) = path.strip_prefix("/v1/proofs/") else {
        return false;
    };
    if encoded_id.contains('/') {
        return false;
    }
    let Ok(decoded_id) = urlencoding::decode(encoded_id) else {
        return false;
    };
    let Ok(id) = decoded_id.parse::<iroha_data_model::proof::ProofId>() else {
        return false;
    };
    // Slash-delimited backend labels are identifier data in this one route's
    // single parameter. Admit their canonical spelling, never path traversal,
    // backslashes, nested escaping, or an arbitrary encoded path separator.
    if id.backend.split('/').any(|part| {
        part.is_empty()
            || matches!(part, "." | "..")
            || !part.bytes().all(|byte| {
                byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b':')
            })
    }) {
        return false;
    }
    let canonical = id.to_string();
    // URL path_segments and Torii's existing component encoder differ only in
    // whether data colons are escaped. Both retain the same exact ProofId.
    canonical.replace('/', "%2F") == encoded_id || urlencoding::encode(&canonical) == encoded_id
}
fn has_dot_segment(path: &str) -> bool {
    path.split('/').any(|segment| {
        segment == "."
            || segment == ".."
            || segment.eq_ignore_ascii_case("%2e")
            || segment.eq_ignore_ascii_case(".%2e")
            || segment.eq_ignore_ascii_case("%2e.")
            || segment.eq_ignore_ascii_case("%2e%2e")
    })
}
fn has_percent_encoded_operator_credential_id(path: &str) -> bool {
    const PREFIX: &str = "/v1/operator/auth/credentials/";
    path.strip_prefix(PREFIX).is_some_and(|credential_id| {
        !credential_id.is_empty() && !credential_id.contains('/') && credential_id.contains('%')
    })
}
fn has_percent_encoded_governance_selector(path: &str) -> bool {
    const PREFIXES: [&str; 4] = [
        "/v1/gov/proposals/",
        "/v1/gov/locks/",
        "/v1/gov/referenda/",
        "/v1/gov/tally/",
    ];
    PREFIXES.iter().any(|prefix| {
        path.strip_prefix(*prefix).is_some_and(|selector| {
            !selector.is_empty() && !selector.contains('/') && selector.contains('%')
        })
    })
}
async fn enforce_strict_request_target(
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let path = req.uri().path();
    let encoded_path_invalid = if path.starts_with("/v1/proofs/") && path.contains('%') {
        !is_canonical_proof_record_path(path)
    } else {
        has_percent_encoded_separator(path)
    };
    let violation = if path.contains("//")
        || path.contains('\\')
        || encoded_path_invalid
        || has_dot_segment(path)
        || has_percent_encoded_operator_credential_id(path)
        || has_percent_encoded_governance_selector(path)
    {
        Some((
            StatusCode::BAD_REQUEST,
            "request_path_invalid",
            "The request path contains a forbidden normalization sequence.",
        ))
    } else if path.len() > 1 && path.ends_with('/') {
        Some((
            StatusCode::NOT_FOUND,
            "route_not_found",
            "The requested route does not exist.",
        ))
    } else {
        None
    };
    let Some((status, code, message)) = violation else {
        return Ok(next.run(req).await);
    };
    let format =
        match utils::negotiate_response_format(req.headers().get(axum::http::header::ACCEPT)) {
            Ok(format) => format,
            Err(mut response) => {
                append_vary_accept(response.headers_mut());
                return Ok(response);
            }
        };
    let mut response =
        utils::respond_with_status_and_format(status, ErrorEnvelope::new(code, message), format);
    append_vary_accept(response.headers_mut());
    Ok(response)
}
fn is_cors_preflight(request: &axum::http::Request<Body>) -> bool {
    request.method() == axum::http::Method::OPTIONS
        && request.headers().contains_key(axum::http::header::ORIGIN)
        && request
            .headers()
            .contains_key(axum::http::header::ACCESS_CONTROL_REQUEST_METHOD)
}
async fn enforce_cataloged_cors_preflight(
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    if !is_cors_preflight(&req) {
        return Ok(next.run(req).await);
    }
    let route = req.extensions().get::<MatchedRouteMetadata>();
    if route.is_some_and(|route| route.stable_route_id() == "http.cors_preflight") {
        return Ok(next.run(req).await);
    }
    let (status, code, message) =
        if route.is_none_or(|route| route.stable_route_id() == "http.route_not_found") {
            (
                StatusCode::NOT_FOUND,
                "route_not_found",
                "The requested route does not exist.",
            )
        } else {
            (
                StatusCode::METHOD_NOT_ALLOWED,
                "method_not_allowed",
                "The requested HTTP method is not allowed for this route.",
            )
        };
    let format =
        match utils::negotiate_response_format(req.headers().get(axum::http::header::ACCEPT)) {
            Ok(format) => format,
            Err(mut response) => {
                append_vary_accept(response.headers_mut());
                return Ok(response);
            }
        };
    let mut response =
        utils::respond_with_status_and_format(status, ErrorEnvelope::new(code, message), format);
    append_vary_accept(response.headers_mut());
    Ok(response)
}
async fn capture_response_format(
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let accept = req.headers().get(axum::http::header::ACCEPT).cloned();
    let allows_native_response = req
        .extensions()
        .get::<MatchedRouteMetadata>()
        .and_then(MatchedRouteMetadata::surface)
        .is_some_and(|surface| {
            matches!(
                surface,
                route_catalog::ApiSurface::Diagnostic | route_catalog::ApiSurface::Protocol
            )
        });
    let safe_method = matches!(
        req.method(),
        &axum::http::Method::GET
            | &axum::http::Method::HEAD
            | &axum::http::Method::OPTIONS
            | &axum::http::Method::TRACE
    );
    let (format, deferred_native_negotiation) =
        match utils::negotiate_response_format(accept.as_ref()) {
            Ok(format) => (format, false),
            Err(mut response) if !safe_method || !allows_native_response => {
                append_vary_accept(response.headers_mut());
                return Ok(response);
            }
            // Only catalogued diagnostic/protocol routes may defer typed
            // negotiation so SSE, Prometheus, health text, raw blobs, and
            // hosted content can select their native media type. Public and
            // operator routes fail before handler execution, including safe
            // conditional requests which could otherwise turn 406 into 304.
            Err(_) => (ResponseFormat::Json, true),
        };
    let mut response = utils::with_current_response_format(format, next.run(req)).await;
    let response_content_type = response
        .headers()
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(str::to_owned);
    let typed_format = response_content_type
        .as_deref()
        .and_then(utils::typed_response_format_for_content_type);
    if deferred_native_negotiation && !response.status().is_success() {
        append_vary_accept(response.headers_mut());
        return Ok(response);
    }
    if let Some(typed_format) = typed_format {
        // The outer typed-error boundary decodes an error using this declared
        // representation, then re-encodes it using the request's negotiated
        // representation. Rejecting a mismatched error here would replace the
        // real failure with a spurious 406 before that canonicalization can
        // occur. Successful typed responses must already match `Accept`.
        if response.status().is_client_error() || response.status().is_server_error() {
            append_vary_accept(response.headers_mut());
            return Ok(response);
        }
        if let Err(mut rejection) =
            utils::ensure_typed_response_format_acceptable(accept.as_ref(), typed_format)
        {
            append_vary_accept(rejection.headers_mut());
            return Ok(rejection);
        }
        append_vary_accept(response.headers_mut());
    } else if let Some(content_type) = response_content_type.as_deref() {
        if let Err(mut rejection) =
            utils::ensure_response_media_type_acceptable(accept.as_ref(), content_type)
        {
            append_vary_accept(rejection.headers_mut());
            return Ok(rejection);
        }
        append_vary_accept(response.headers_mut());
    }
    Ok(response)
}
const MAX_TYPED_ERROR_BODY_BYTES: usize = 256 * 1024;
// Handler error bodies are expected to be local and immediately available;
// cap their drain at the same ten-second scale used by bounded Torii ingress.
const TYPED_ERROR_BODY_READ_TIMEOUT: Duration = Duration::from_secs(10);
fn generic_error_for_status(status: StatusCode) -> (&'static str, &'static str) {
    match status {
        StatusCode::BAD_REQUEST => ("bad_request", "The request is invalid."),
        StatusCode::UNAUTHORIZED => ("unauthorized", "Authentication is required."),
        StatusCode::FORBIDDEN => ("forbidden", "The request is not permitted."),
        StatusCode::NOT_FOUND => ("not_found", "The requested resource was not found."),
        StatusCode::METHOD_NOT_ALLOWED => (
            "method_not_allowed",
            "The requested HTTP method is not allowed for this resource.",
        ),
        StatusCode::REQUEST_TIMEOUT => ("request_timeout", "The request timed out."),
        StatusCode::CONFLICT => ("conflict", "The request conflicts with current state."),
        StatusCode::GONE => ("gone", "The requested resource is no longer available."),
        StatusCode::PAYLOAD_TOO_LARGE => (
            "request_payload_too_large",
            "The request payload exceeds the configured limit.",
        ),
        StatusCode::UNSUPPORTED_MEDIA_TYPE => (
            "request_content_type_unsupported",
            "The request content type is not supported.",
        ),
        StatusCode::UNPROCESSABLE_ENTITY => (
            "unprocessable_entity",
            "The request cannot be processed as submitted.",
        ),
        StatusCode::TOO_MANY_REQUESTS => (
            "request_rate_limited",
            "Request capacity is temporarily exhausted.",
        ),
        StatusCode::NOT_IMPLEMENTED => (
            "not_implemented",
            "The requested capability is not implemented.",
        ),
        StatusCode::BAD_GATEWAY => ("bad_gateway", "An upstream service returned an error."),
        StatusCode::SERVICE_UNAVAILABLE => (
            "service_unavailable",
            "The service is temporarily unavailable.",
        ),
        StatusCode::GATEWAY_TIMEOUT => (
            "gateway_timeout",
            "An upstream service did not respond in time.",
        ),
        _ if status.is_server_error() => (
            "internal_server_error",
            "Torii could not complete the request.",
        ),
        _ => ("http_error", "The request did not complete successfully."),
    }
}
fn decode_error_envelope(bytes: &[u8], format: ResponseFormat) -> Option<ErrorEnvelope> {
    match format {
        ResponseFormat::Json => norito::json::from_slice(bytes).ok(),
        ResponseFormat::Norito => norito::decode_from_bytes(bytes).ok(),
    }
}
fn encode_error_envelope(envelope: &ErrorEnvelope, format: ResponseFormat) -> Option<Vec<u8>> {
    match format {
        ResponseFormat::Json => norito::json::to_vec(envelope).ok(),
        ResponseFormat::Norito => norito::to_bytes(envelope).ok(),
    }
}
fn retry_after_seconds(headers: &HeaderMap) -> u64 {
    headers
        .get(axum::http::header::RETRY_AFTER)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse::<u64>().ok())
        .filter(|seconds| *seconds > 0)
        .unwrap_or(1)
}
fn retain_valid_error_detail(value: &mut Option<String>) {
    if value
        .as_deref()
        .is_some_and(|value| !utils::is_valid_error_detail_text(value))
    {
        *value = None;
    }
}
fn axt_error_details_is_empty(details: &AxtErrorDetails) -> bool {
    details.code.is_none()
        && details.reason.is_none()
        && details.snapshot_version.is_none()
        && details.dataspace.is_none()
        && details.lane.is_none()
        && details.active_handle_era.is_none()
        && details.next_handle_counter.is_none()
}
fn sanitize_fee_error_details(details: &mut FeeErrorDetails) -> bool {
    if FeeRejectionCode::from_str(&details.code).is_err() {
        return false;
    }
    if details.program_id.as_deref().is_some_and(|literal| {
        literal
            .parse::<iroha_data_model::nexus::FeeSponsorProgramId>()
            .map_or(true, |id| id.to_string() != literal)
    }) {
        details.program_id = None;
    }
    if details.program_revision == Some(0) {
        details.program_revision = None;
    }
    if details
        .asset_definition_id
        .as_deref()
        .is_some_and(|literal| {
            literal
                .parse::<AssetDefinitionId>()
                .map_or(true, |id| id.to_string() != literal)
        })
    {
        details.asset_definition_id = None;
    }
    for amount in [&mut details.required, &mut details.available] {
        if amount.as_deref().is_some_and(|literal| {
            literal
                .parse::<Quantity>()
                .map_or(true, |quantity| quantity.to_string() != literal)
        }) {
            *amount = None;
        }
    }
    if details.rule_id.as_deref().is_some_and(|literal| {
        Name::from_str(literal).map_or(true, |name| name.to_string() != literal)
    }) {
        details.rule_id = None;
    }
    retain_valid_error_detail(&mut details.remediation);
    true
}
fn sanitize_alias_setup_report(
    report: &mut iroha_data_model::alias_setup::AliasSetupReportV1,
) -> bool {
    use iroha_data_model::alias_setup::{AliasSetupReportV1, AliasSetupStatusV1};
    if report.version != AliasSetupReportV1::VERSION
        || report.diagnostics.is_empty()
        || !matches!(
            report.status,
            AliasSetupStatusV1::Blocked | AliasSetupStatusV1::Pending
        )
        || report.diagnostics.windows(2).any(|pair| pair[0] > pair[1])
    {
        return false;
    }
    for diagnostic in &mut report.diagnostics {
        if !utils::is_valid_reject_code(&diagnostic.code)
            || !utils::is_valid_error_detail_text(&diagnostic.remediation)
        {
            return false;
        }
        for value in [
            &mut diagnostic.resource,
            &mut diagnostic.config_path,
            &mut diagnostic.expected,
            &mut diagnostic.actual,
        ] {
            retain_valid_error_detail(value);
        }
    }
    report.diagnostics.sort();
    true
}
fn sanitize_error_details(details: &mut ErrorDetails) {
    if details
        .alias_setup_report
        .as_mut()
        .is_some_and(|report| !sanitize_alias_setup_report(report))
    {
        details.alias_setup_report = None;
    }
    if details
        .account_alias_not_found
        .as_ref()
        .is_some_and(|absence| {
            absence
                .alias
                .parse::<iroha_data_model::alias_setup::AccountAliasName>()
                .map_or(true, |alias| alias.to_string() != absence.alias)
        })
    {
        details.account_alias_not_found = None;
    }
    if details
        .account_aliases_by_account_not_found
        .as_ref()
        .is_some_and(|absence| {
            if parse_exact_account_id_literal(&absence.account_id).is_err() {
                return true;
            }
            match (absence.dataspace.as_deref(), absence.domain.as_deref()) {
                (None, None) => false,
                (None, Some(_)) => true,
                (Some(dataspace), domain) => {
                    iroha_data_model::alias_setup::AccountAliasName::try_new(
                        "lookup", domain, dataspace,
                    )
                    .map_or(true, |alias| {
                        alias.dataspace.as_ref() != dataspace
                            || alias.domain.as_ref().map(AsRef::as_ref) != domain
                    })
                }
            }
        })
    {
        details.account_aliases_by_account_not_found = None;
    }
    if details
        .sns_registration_not_found
        .as_ref()
        .is_some_and(|absence| {
            !matches!(
                absence.suffix_id,
                iroha_data_model::sns::ACCOUNT_ALIAS_SUFFIX_ID
                    | iroha_data_model::sns::DOMAIN_NAME_SUFFIX_ID
                    | iroha_data_model::sns::DATASPACE_ALIAS_SUFFIX_ID
            ) || !utils::is_valid_error_detail_text(&absence.label)
        })
    {
        details.sns_registration_not_found = None;
    }
    retain_valid_error_detail(&mut details.layer);
    if details
        .reject_code
        .as_deref()
        .is_some_and(|code| !utils::is_valid_reject_code(code))
    {
        details.reject_code = None;
    }
    if details.queue.as_ref().is_some_and(|queue| {
        !matches!(queue.state.as_str(), "healthy" | "saturated")
            || queue.saturated != (queue.state == "saturated")
    }) {
        details.queue = None;
    }
    retain_valid_error_detail(&mut details.endpoint);
    if details
        .endpoint
        .as_deref()
        .is_some_and(|endpoint| endpoint.contains('?') || endpoint.contains('#'))
    {
        details.endpoint = None;
    }
    retain_valid_error_detail(&mut details.field);
    retain_valid_error_detail(&mut details.expected);
    retain_valid_error_detail(&mut details.actual);
    retain_valid_error_detail(&mut details.profile);
    retain_valid_error_detail(&mut details.entrypoint_hash);
    retain_valid_error_detail(&mut details.tx_hash);
    if details
        .pipeline_transaction_status_not_found
        .as_ref()
        .is_some_and(|absence| !absence.is_valid())
    {
        details.pipeline_transaction_status_not_found = None;
    }
    if details
        .finality_attestation_failure
        .as_ref()
        .is_some_and(|failure| !failure.is_valid())
    {
        details.finality_attestation_failure = None;
    }
    retain_valid_error_detail(&mut details.last_status);
    retain_valid_error_detail(&mut details.hint);
    if let Some(axt) = details.axt.as_mut() {
        if axt
            .code
            .as_deref()
            .is_some_and(|code| !utils::is_valid_reject_code(code))
        {
            axt.code = None;
        }
        retain_valid_error_detail(&mut axt.reason);
        if axt_error_details_is_empty(axt) {
            details.axt = None;
        }
    }
    if details
        .fee
        .as_mut()
        .is_some_and(|fee| !sanitize_fee_error_details(fee))
    {
        details.fee = None;
    }
}
fn canonical_error_response(
    mut parts: axum::http::response::Parts,
    mut envelope: ErrorEnvelope,
    format: ResponseFormat,
    head_only: bool,
) -> AxResponse {
    parts.headers.remove("x-iroha-stream-error");
    parts.headers.remove(MCP_NATIVE_ERROR_HEADER);
    parts.extensions.remove::<ReviewedProtocolNativeError>();
    // Recognize the closed finality observation before generic 500 sanitization.
    // Rebuild its fixed public message and sole detail instead of trusting any
    // handler-provided diagnostics, including on the InternalFailure path.
    let finality_failure = if envelope.code()
        == iroha_torii_shared::bridge_attestation::FINALITY_ATTESTATION_FAILURE_CODE
    {
        let mut details = envelope.details.take().unwrap_or_default();
        details
            .finality_attestation_failure
            .take()
            .filter(|failure| {
                details.is_empty()
                    && failure.is_valid()
                    && failure.reason.http_status_code() == parts.status.as_u16()
            })
    } else {
        None
    };
    let exact_finality_failure = finality_failure.is_some();
    if let Some(failure) = finality_failure {
        envelope = failure.into_error_envelope();
    } else if envelope.code()
        == iroha_torii_shared::bridge_attestation::FINALITY_ATTESTATION_FAILURE_CODE
    {
        let (code, message) = generic_error_for_status(parts.status);
        envelope = ErrorEnvelope::new(code, message);
    }
    if parts.status == StatusCode::INTERNAL_SERVER_ERROR {
        if !exact_finality_failure {
            envelope = ErrorEnvelope::new(
                "internal_server_error",
                "Torii could not complete the request.",
            );
        }
        for name in [
            "x-iroha-reject-code",
            "x-iroha-axt-code",
            "x-iroha-axt-reason",
            "x-iroha-axt-snapshot-version",
            "x-iroha-axt-dataspace",
            "x-iroha-axt-lane",
            "x-iroha-axt-active-handle-era",
            "x-iroha-axt-next-handle-counter",
            "x-iroha-queue-depth",
            "x-iroha-queue-capacity",
            "x-iroha-queue-state",
        ] {
            parts.headers.remove(name);
        }
    } else if !utils::is_valid_error_code(envelope.code()) {
        let rejected_code = std::mem::take(&mut envelope.code);
        let (code, message) = generic_error_for_status(parts.status);
        envelope.code = code.to_owned();
        envelope.message = message.to_owned();
        if utils::is_valid_reject_code(&rejected_code) {
            let details = envelope.details.get_or_insert_with(Default::default);
            if details.reject_code.is_none() {
                details.reject_code = Some(rejected_code);
            }
        }
    }
    if !utils::is_valid_error_message(envelope.message()) {
        let (_, message) = generic_error_for_status(parts.status);
        envelope.message = message.to_owned();
    }
    // Finality reasons own their retry semantics. The canonical dedicated detail
    // stays sole; generic 503/429 errors retain their existing Retry-After fields.
    if exact_finality_failure {
        parts.headers.remove(axum::http::header::RETRY_AFTER);
    }
    if matches!(
        parts.status,
        StatusCode::TOO_MANY_REQUESTS | StatusCode::SERVICE_UNAVAILABLE
    ) && !exact_finality_failure
    {
        let seconds = retry_after_seconds(&parts.headers);
        let details = envelope.details.get_or_insert_with(Default::default);
        details.retry_after_seconds = Some(seconds);
        if let Ok(value) = HeaderValue::from_str(&seconds.to_string()) {
            parts.headers.insert(axum::http::header::RETRY_AFTER, value);
        }
    }
    if let Some(details) = envelope.details.as_mut() {
        use iroha_torii_shared::aliases::{
            ACCOUNT_ALIAS_NOT_FOUND_CODE, ACCOUNT_ALIASES_BY_ACCOUNT_NOT_FOUND_CODE,
            ALIAS_SETUP_PENDING_CODE, ALIAS_SETUP_REJECTED_CODE,
        };
        if parts.status != StatusCode::NOT_FOUND || envelope.code != ACCOUNT_ALIAS_NOT_FOUND_CODE {
            details.account_alias_not_found = None;
        }
        if parts.status != StatusCode::NOT_FOUND
            || envelope.code != ACCOUNT_ALIASES_BY_ACCOUNT_NOT_FOUND_CODE
        {
            details.account_aliases_by_account_not_found = None;
        }
        if details
            .alias_setup_report
            .as_ref()
            .is_some_and(|report| match report.status {
                iroha_data_model::alias_setup::AliasSetupStatusV1::Blocked => {
                    !matches!(
                        parts.status,
                        StatusCode::BAD_REQUEST | StatusCode::FORBIDDEN | StatusCode::CONFLICT
                    ) || envelope.code != ALIAS_SETUP_REJECTED_CODE
                }
                iroha_data_model::alias_setup::AliasSetupStatusV1::Pending => {
                    parts.status != StatusCode::SERVICE_UNAVAILABLE
                        || envelope.code != ALIAS_SETUP_PENDING_CODE
                }
                iroha_data_model::alias_setup::AliasSetupStatusV1::Ready => true,
            })
        {
            details.alias_setup_report = None;
        }
        if parts.status != StatusCode::NOT_FOUND
            || envelope.code != iroha_torii_shared::sns::SNS_REGISTRATION_NOT_FOUND_CODE
        {
            details.sns_registration_not_found = None;
        }
        if parts.status != StatusCode::NOT_FOUND || envelope.code != "query_asset_not_found" {
            details.query_asset_not_found = None;
        }
        if parts.status != StatusCode::NOT_FOUND
            || envelope.code != iroha_torii_shared::PIPELINE_TRANSACTION_STATUS_NOT_FOUND_CODE
        {
            details.pipeline_transaction_status_not_found = None;
        }
        if !exact_finality_failure {
            details.finality_attestation_failure = None;
        }
        sanitize_error_details(details);
    }
    if envelope
        .details
        .as_ref()
        .is_some_and(ErrorDetails::is_empty)
    {
        envelope.details = None;
    }
    if parts.status == StatusCode::UNAUTHORIZED
        && !parts
            .headers
            .contains_key(axum::http::header::WWW_AUTHENTICATE)
    {
        parts.headers.insert(
            axum::http::header::WWW_AUTHENTICATE,
            HeaderValue::from_static("Iroha realm=\"torii\""),
        );
    }
    let (bytes, encoded_format) = encode_error_envelope(&envelope, format).map_or_else(
        || {
            let fallback = ErrorEnvelope::new(
                "response_serialization_failed",
                "Torii could not encode the error response.",
            );
            (
                encode_error_envelope(&fallback, ResponseFormat::Json).unwrap_or_default(),
                ResponseFormat::Json,
            )
        },
        |bytes| (bytes, format),
    );
    parts.headers.insert(
        axum::http::header::CONTENT_TYPE,
        match encoded_format {
            ResponseFormat::Json => HeaderValue::from_static("application/json; charset=utf-8"),
            ResponseFormat::Norito => HeaderValue::from_static(utils::NORITO_MIME_TYPE),
        },
    );
    parts.headers.remove(axum::http::header::CONTENT_ENCODING);
    parts.headers.remove(axum::http::header::TRANSFER_ENCODING);
    if let Ok(value) = HeaderValue::from_str(&bytes.len().to_string()) {
        parts
            .headers
            .insert(axum::http::header::CONTENT_LENGTH, value);
    }
    append_vary_accept(&mut parts.headers);
    parts
        .extensions
        .insert(utils::HttpErrorCode::from_envelope(&envelope));
    AxResponse::from_parts(
        parts,
        if head_only {
            Body::empty()
        } else {
            Body::from(bytes)
        },
    )
}
/// Explicit marker for a reviewed protocol-native error response.
/// Adding a variant requires an exact route, status, media-type, and public
/// error-header entry in [`reviewed_protocol_native_error_code`]. Unmarked
/// failures always use [`ErrorEnvelope`], including failures from other
/// protocol-surface handlers.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ReviewedProtocolNativeError {
    /// SSE event explaining that this live stream cannot resume from a cursor.
    StreamResumeUnsupported,
    /// JSON-RPC transport error owned by the native MCP POST handler.
    McpJsonRpc(ReviewedMcpJsonRpcError),
}
/// Closed set of MCP transport errors allowed to retain JSON-RPC framing.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ReviewedMcpJsonRpcError {
    /// The request bytes were not valid JSON.
    ParseError,
    /// The parsed JSON was not one supported MCP request object.
    InvalidRequest,
    /// Required stateless MCP request metadata was missing or malformed.
    InvalidParams,
    /// Mirrored MCP HTTP routing metadata did not match the JSON-RPC body.
    HeaderMismatch,
    /// The request requires an optional capability the client did not declare.
    MissingRequiredClientCapability,
    /// The MCP protocol version header was missing, duplicated, or unsupported.
    UnsupportedProtocolVersion,
    /// The modern MCP request named a method Torii does not implement.
    MethodNotFound,
    /// The HTTP body stream failed before a complete request was available.
    RequestBodyReadFailed,
    /// A browser origin did not exactly match the configured allowlist.
    OriginForbidden,
    /// The HTTP body stream exceeded its collection deadline.
    RequestTimeout,
    /// The HTTP body exceeded the configured MCP request cap.
    RequestPayloadTooLarge,
    /// The MCP-specific token bucket rejected the request.
    RateLimited,
}
const MCP_NATIVE_ERROR_HEADER: &str = "x-iroha-mcp-error";
impl ReviewedMcpJsonRpcError {
    /// Exact HTTP status permitted for this reviewed JSON-RPC error.
    pub(crate) const fn status(self) -> StatusCode {
        match self {
            Self::ParseError
            | Self::InvalidRequest
            | Self::InvalidParams
            | Self::HeaderMismatch
            | Self::MissingRequiredClientCapability
            | Self::UnsupportedProtocolVersion
            | Self::RequestBodyReadFailed => StatusCode::BAD_REQUEST,
            Self::MethodNotFound => StatusCode::NOT_FOUND,
            Self::OriginForbidden => StatusCode::FORBIDDEN,
            Self::RequestTimeout => StatusCode::REQUEST_TIMEOUT,
            Self::RequestPayloadTooLarge => StatusCode::PAYLOAD_TOO_LARGE,
            Self::RateLimited => StatusCode::TOO_MANY_REQUESTS,
        }
    }
    /// Stable public error label shared by the body, marker header, and telemetry.
    pub(crate) const fn code(self) -> &'static str {
        match self {
            Self::ParseError => "parse_error",
            Self::InvalidRequest => "invalid_request",
            Self::InvalidParams => "invalid_params",
            Self::HeaderMismatch => "header_mismatch",
            Self::MissingRequiredClientCapability => "missing_required_client_capability",
            Self::UnsupportedProtocolVersion => "unsupported_protocol_version",
            Self::MethodNotFound => "method_not_found",
            Self::RequestBodyReadFailed => "request_body_read_failed",
            Self::OriginForbidden => "origin_forbidden",
            Self::RequestTimeout => "request_timeout",
            Self::RequestPayloadTooLarge => "request_payload_too_large",
            Self::RateLimited => "rate_limited",
        }
    }
}
fn response_boundary_accept_header(
    headers: &HeaderMap,
) -> Result<Option<HeaderValue>, &'static str> {
    match coalesced_accept_header(headers)? {
        Some(combined) => Ok(Some(combined)),
        None => Ok(headers.get(axum::http::header::ACCEPT).cloned()),
    }
}
fn reviewed_protocol_native_error_code(
    route: Option<&MatchedRouteMetadata>,
    response: &AxResponse,
) -> Option<&'static str> {
    let marker = response.extensions().get::<ReviewedProtocolNativeError>()?;
    let route = route.filter(|route| {
        route.surface() == Some(iroha_torii_shared::route_catalog::ApiSurface::Protocol)
    })?;
    let content_type = response
        .headers()
        .get(axum::http::header::CONTENT_TYPE)?
        .to_str()
        .ok()?
        .split(';')
        .next()
        .map(str::trim)?;
    match marker {
        ReviewedProtocolNativeError::StreamResumeUnsupported
            if response.status() == StatusCode::BAD_REQUEST
                && content_type.eq_ignore_ascii_case("text/event-stream")
                && response
                    .headers()
                    .get("x-iroha-stream-error")
                    .and_then(|value| value.to_str().ok())
                    == Some("stream_resume_unsupported")
                && (route.stable_route_id()
                    == route_catalog::streaming::EVENTS_SSE.stable_route_id()
                    || route.stable_route_id()
                        == route_catalog::streaming::CONTRACT_EVENTS_SSE.stable_route_id()) =>
        {
            Some("stream_resume_unsupported")
        }
        ReviewedProtocolNativeError::McpJsonRpc(kind)
            if response.status() == kind.status()
                && content_type.eq_ignore_ascii_case("application/json")
                && response
                    .headers()
                    .get(MCP_NATIVE_ERROR_HEADER)
                    .and_then(|value| value.to_str().ok())
                    == Some(kind.code())
                && response
                    .headers()
                    .get(axum::http::header::CACHE_CONTROL)
                    .and_then(|value| value.to_str().ok())
                    == Some("private, no-store")
                && (*kind != ReviewedMcpJsonRpcError::RateLimited
                    || response
                        .headers()
                        .get(axum::http::header::RETRY_AFTER)
                        .and_then(|value| value.to_str().ok())
                        == Some("1"))
                && route.stable_route_id()
                    == route_catalog::mcp_transport::JSON_RPC.stable_route_id() =>
        {
            Some(kind.code())
        }
        _ => None,
    }
}
/// Enforce one finite error contract at the HTTP response boundary.
///
/// Ordinary public, operator, diagnostic, router, and middleware failures are
/// canonicalized to a decodable [`ErrorEnvelope`]. Reviewed protocol-native
/// responses may retain a non-typed media type, but still receive a bounded
/// telemetry code. This makes a stray bare status or ad-hoc JSON object fail
/// closed without requiring every handler author to remember the invariant.
async fn enforce_typed_error_contract(
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<AxResponse, Infallible> {
    enforce_typed_error_contract_with_body_timeout(req, next, TYPED_ERROR_BODY_READ_TIMEOUT).await
}
async fn enforce_typed_error_contract_with_body_timeout(
    req: axum::http::Request<Body>,
    next: Next,
    body_read_timeout: Duration,
) -> Result<AxResponse, Infallible> {
    let method = req.method().clone();
    let accept = response_boundary_accept_header(req.headers());
    let route = req.extensions().get::<MatchedRouteMetadata>().cloned();
    let mut response = next.run(req).await;
    let status = response.status();
    if !status.is_client_error() && !status.is_server_error() {
        return Ok(response);
    }
    if let Some(code) = reviewed_protocol_native_error_code(route.as_ref(), &response) {
        let content_type = response
            .headers()
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .unwrap_or_default();
        let native_accept = accept
            .as_ref()
            .map_err(|message| {
                utils::respond_with_status_and_format(
                    StatusCode::NOT_ACCEPTABLE,
                    ErrorEnvelope::new("response_not_acceptable", *message),
                    ResponseFormat::Json,
                )
            })
            .and_then(|accept| {
                utils::ensure_response_media_type_acceptable(accept.as_ref(), content_type)
            });
        match native_accept {
            Ok(()) => {
                response
                    .extensions_mut()
                    .remove::<ReviewedProtocolNativeError>();
                response
                    .extensions_mut()
                    .insert(utils::HttpErrorCode::new(code));
                append_vary_accept(response.headers_mut());
                return Ok(response);
            }
            Err(mut rejection) => {
                rejection
                    .extensions_mut()
                    .remove::<ReviewedProtocolNativeError>();
                rejection.headers_mut().remove("x-iroha-stream-error");
                rejection.headers_mut().remove(MCP_NATIVE_ERROR_HEADER);
                append_vary_accept(rejection.headers_mut());
                response = rejection;
            }
        }
    }
    response
        .extensions_mut()
        .remove::<ReviewedProtocolNativeError>();
    response.headers_mut().remove("x-iroha-stream-error");
    response.headers_mut().remove(MCP_NATIVE_ERROR_HEADER);
    let typed_format = response
        .headers()
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .and_then(utils::typed_response_format_for_content_type);
    // Content-Type controls decoding only. The request's Accept negotiation is
    // authoritative for the representation emitted by this boundary. A
    // malformed/coalescing-failed or unsupported Accept value uses JSON for
    // the unavoidable negotiation error because no requested format exists.
    let negotiated_format = accept
        .as_ref()
        .ok()
        .and_then(|accept| utils::negotiate_response_format(accept.as_ref()).ok())
        .unwrap_or(ResponseFormat::Json);
    let (parts, body) = response.into_parts();
    let bytes = tokio::time::timeout(
        body_read_timeout,
        axum::body::to_bytes(body, MAX_TYPED_ERROR_BODY_BYTES),
    )
    .await
    .ok()
    .and_then(Result::ok);
    let envelope = bytes
        .as_deref()
        .filter(|bytes| !bytes.is_empty())
        .and_then(|bytes| typed_format.and_then(|format| decode_error_envelope(bytes, format)))
        .unwrap_or_else(|| {
            let (code, message) = generic_error_for_status(parts.status);
            ErrorEnvelope::new(code, message)
        });
    Ok(canonical_error_response(
        parts,
        envelope,
        negotiated_format,
        method == axum::http::Method::HEAD,
    ))
}
fn append_vary_accept(headers: &mut HeaderMap) {
    let already_varies = headers
        .get_all(axum::http::header::VARY)
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(','))
        .any(|name| name.trim().eq_ignore_ascii_case("accept"));
    if !already_varies {
        headers.append(axum::http::header::VARY, HeaderValue::from_static("Accept"));
    }
}
async fn handler_route_not_found() -> Response {
    utils::respond_with_status_and_format(
        StatusCode::NOT_FOUND,
        ErrorEnvelope::new("route_not_found", "The requested route does not exist."),
        utils::current_response_format(),
    )
}

// These operations are selected by the normalized Host header rather than an
// Axum path template. Keep fixed descriptors so admission, cache policy,
// metrics, and traces observe the same bounded identity as path-selected
// routes. They are intentionally absent from the path catalog: mounting either
// `/` or `/{*path}` there would shadow the ordinary Torii API.
const SORAFS_HOST_SITE_ROOT_ROUTE: route_catalog::RouteDescriptor =
    route_catalog::RouteDescriptor::new(
        "protocol.sorafs.host_site_root",
        route_catalog::HttpMethod::Get,
        "/",
        route_catalog::ApiSurface::Public,
        route_catalog::Listener::Torii,
        route_catalog::RouteEffect::ReadOnly,
        route_catalog::AdmissionPolicy::Public,
    )
    .with_authentication(route_catalog::AuthenticationPolicy::Unauthenticated);
const SORAFS_HOST_SITE_PATH_ROUTE: route_catalog::RouteDescriptor =
    route_catalog::RouteDescriptor::new(
        "protocol.sorafs.host_site_path",
        route_catalog::HttpMethod::Get,
        "/{*path}",
        route_catalog::ApiSurface::Public,
        route_catalog::Listener::Torii,
        route_catalog::RouteEffect::ReadOnly,
        route_catalog::AdmissionPolicy::Public,
    )
    .with_authentication(route_catalog::AuthenticationPolicy::Unauthenticated);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HostSelectedSorafsRoute {
    Root,
    Path,
}

impl HostSelectedSorafsRoute {
    const fn descriptor(self) -> route_catalog::RouteDescriptor {
        match self {
            Self::Root => SORAFS_HOST_SITE_ROOT_ROUTE,
            Self::Path => SORAFS_HOST_SITE_PATH_ROUTE,
        }
    }
}

/// Mark a canonical configured site host before catalog metadata is attached.
/// The catalog layer only consumes this marker when Axum selected no ordinary
/// path route, so a crafted Host header cannot change an API route's security
/// classification.
async fn mark_host_selected_sorafs_route(
    State(app): State<SharedAppState>,
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    if req
        .extensions()
        .get::<axum::extract::MatchedPath>()
        .is_none()
        && sorafs::public_gateway::request_host_selects_site(&app, req.headers())
    {
        let route = if req.uri().path() == "/" {
            HostSelectedSorafsRoute::Root
        } else {
            HostSelectedSorafsRoute::Path
        };
        req.extensions_mut().insert(route);
    }
    Ok(next.run(req).await)
}

async fn handler_route_not_found_or_sorafs_site(
    State(app): State<SharedAppState>,
    host_route: Option<Extension<HostSelectedSorafsRoute>>,
    method: axum::http::Method,
    headers: HeaderMap,
    uri: axum::http::Uri,
) -> Response {
    if host_route.is_none() {
        return handler_route_not_found().await;
    }
    if method != axum::http::Method::GET {
        return handler_method_not_allowed().await;
    }
    let raw_path = uri
        .path()
        .strip_prefix('/')
        .unwrap_or(uri.path())
        .to_owned();
    if raw_path.is_empty() {
        sorafs::public_gateway::handle_get_sorafs_site_root(State(app), headers).await
    } else {
        sorafs::public_gateway::handle_get_sorafs_site_path(
            State(app),
            headers,
            axum::extract::Path(raw_path),
        )
        .await
    }
}
async fn handler_method_not_allowed() -> Response {
    utils::respond_with_status_and_format(
        StatusCode::METHOD_NOT_ALLOWED,
        ErrorEnvelope::new(
            "method_not_allowed",
            "The requested HTTP method is not allowed for this route.",
        ),
        utils::current_response_format(),
    )
}
fn route_timeout_for_path(path: &str) -> Duration {
    match path {
        "/v1/mcp" => mcp::MCP_ROUTE_EXECUTION_TIMEOUT,
        // Keep the outer HTTP timeout at least as large as the internal
        // read-fanout proxy budget so ingress does not emit a bare 408 while a
        // Nexus fanout request is still within its allowed route window.
        _ => DEFAULT_ROUTE_TIMEOUT + Duration::from_secs(5),
    }
}
fn private_no_store_error_response(
    status: StatusCode,
    envelope: ErrorEnvelope,
    format: ResponseFormat,
) -> Response {
    let mut response = utils::respond_with_status_and_format(status, envelope, format);
    response.headers_mut().insert(
        axum::http::header::CACHE_CONTROL,
        HeaderValue::from_static("private, no-store"),
    );
    response
}
fn route_timeout_error_response(format: ResponseFormat) -> Response {
    private_no_store_error_response(
        StatusCode::REQUEST_TIMEOUT,
        ErrorEnvelope::new(
            "request_timeout",
            "The request exceeded the route execution deadline.",
        ),
        format,
    )
}
async fn enforce_route_timeout(
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    // Keep the original outer window. Physical interval work borrows this exact
    // deadline instead of restarting a duration after queue/rate admission.
    let deadline = Instant::now() + route_timeout_for_path(req.uri().path());
    req.extensions_mut()
        .insert(finality_interval::RouteExecutionDeadline(deadline));
    match tokio::time::timeout_at(tokio::time::Instant::from_std(deadline), next.run(req)).await {
        Ok(response) => Ok(response),
        Err(_) => Ok(route_timeout_error_response(
            utils::current_response_format(),
        )),
    }
}
async fn catch_handler_panics(
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let error_format =
        utils::negotiate_response_format(req.headers().get(axum::http::header::ACCEPT))
            .unwrap_or(ResponseFormat::Json);
    let handler = iroha_panic_hook::with_hook_suppressed_async(next.run(req));
    match std::panic::AssertUnwindSafe(handler).catch_unwind().await {
        Ok(response) => Ok(response),
        Err(payload) => {
            let message = payload
                .downcast_ref::<&str>()
                .copied()
                .or_else(|| payload.downcast_ref::<String>().map(String::as_str))
                .unwrap_or("non-string panic payload");
            iroha_logger::error!(%message, "Torii request handler panicked");
            Ok(private_no_store_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                ErrorEnvelope::new(
                    "internal_server_error",
                    "Torii could not complete the request.",
                ),
                error_format,
            ))
        }
    }
}
/// Attach catalog metadata after Axum has selected a route template.
///
/// `MatchedPath` is a router template (for example
/// `/v1/operator/auth/credentials/{credential_id}`), never the concrete request URI.
/// The metadata is copied to the response so outer middleware can observe it
/// without buffering or reconstructing the consumed request.
async fn attach_matched_route_metadata(
    State(index): State<MountedRouteIndex>,
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let matched_path = req
        .extensions()
        .get::<axum::extract::MatchedPath>()
        .map(|path| path.as_str().to_owned());
    let mut metadata = index.resolve(req.method(), matched_path.as_deref());
    if metadata.stable_route_id() == "http.route_not_found"
        && let Some(host_route) = req.extensions().get::<HostSelectedSorafsRoute>().copied()
    {
        let descriptor = host_route.descriptor();
        metadata = if req.method() == axum::http::Method::GET {
            MatchedRouteMetadata::from_descriptor(descriptor)
        } else {
            MatchedRouteMetadata::method_not_allowed_for(descriptor)
        };
    }
    req.extensions_mut().insert(metadata.clone());
    let mut response = next.run(req).await;
    response.extensions_mut().insert(metadata);
    Ok(response)
}
/// Enforce catalog-derived private response caching after the trusted matched-route metadata has
/// been copied onto the response.
async fn enforce_catalog_private_no_store(
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let mut response = next.run(req).await;
    if response
        .extensions()
        .get::<MatchedRouteMetadata>()
        .is_some_and(MatchedRouteMetadata::requires_private_no_store)
    {
        response.headers_mut().insert(
            axum::http::header::CACHE_CONTROL,
            HeaderValue::from_static("private, no-store"),
        );
    }
    Ok(response)
}
fn route_surface_label(metadata: &MatchedRouteMetadata) -> &'static str {
    match metadata.surface() {
        Some(iroha_torii_shared::route_catalog::ApiSurface::Public) => "public",
        Some(iroha_torii_shared::route_catalog::ApiSurface::Operator) => "operator",
        Some(iroha_torii_shared::route_catalog::ApiSurface::Diagnostic) => "diagnostic",
        Some(iroha_torii_shared::route_catalog::ApiSurface::Protocol) => "protocol",
        None if metadata.stable_route_id() == "http.route_not_found" => "unmatched",
        None => "unregistered",
    }
}
fn response_representation_label(response: &Response) -> &'static str {
    if response.status() == StatusCode::SWITCHING_PROTOCOLS {
        return "websocket";
    }
    let Some(content_type) = response
        .headers()
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(';').next())
        .map(str::trim)
    else {
        return "none";
    };
    if content_type.eq_ignore_ascii_case("application/json") {
        "json"
    } else if content_type
        .to_ascii_lowercase()
        .starts_with("application/")
        && content_type.to_ascii_lowercase().ends_with("+json")
    {
        "json"
    } else if content_type.eq_ignore_ascii_case(utils::NORITO_MIME_TYPE) {
        "norito"
    } else if content_type.eq_ignore_ascii_case("text/event-stream") {
        "sse"
    } else if content_type.eq_ignore_ascii_case("application/octet-stream")
        || content_type.starts_with("image/")
        || content_type.starts_with("audio/")
        || content_type.starts_with("video/")
        || content_type == "application/wasm"
    {
        "binary"
    } else if content_type.eq_ignore_ascii_case("text/plain")
        && response
            .headers()
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.to_ascii_lowercase().contains("version=0.0.4"))
    {
        "prometheus"
    } else if content_type.starts_with("text/") {
        "text"
    } else {
        "other"
    }
}
fn sorafs_gateway_request_metric_labels<'a>(
    metadata: &'a MatchedRouteMetadata,
    method: &'a str,
) -> Option<SorafsGatewayRequestMetricLabels<'a>> {
    let (variant, chunker, profile) = match metadata.stable_route_id() {
        route_id if route_id == route_catalog::sorafs::STORAGE_CAR.stable_route_id() => {
            ("car", "unknown", "unknown")
        }
        route_id if route_id == route_catalog::sorafs::STORAGE_CHUNK.stable_route_id() => {
            ("chunk", "unknown", "unknown")
        }
        route_id if route_id == route_catalog::sorafs::PROOF_STREAM.stable_route_id() => (
            "proof_stream",
            "none",
            sorafs_manifest::gateway_fixture::SORAFS_GATEWAY_PROFILE_VERSION,
        ),
        _ => return None,
    };
    Some(SorafsGatewayRequestMetricLabels {
        endpoint: metadata.path_template(),
        method,
        variant,
        chunker,
        profile,
    })
}
async fn record_http_metrics(
    State(app): State<SharedAppState>,
    req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    fn normalise_content_type(raw: &str) -> String {
        let base = raw
            .split(';')
            .next()
            .map(|value| value.trim().to_ascii_lowercase())
            .filter(|value| !value.is_empty())
            .unwrap_or_else(|| "unknown".to_string());
        match base.as_str() {
            "application/json"
            | "application/x-norito"
            | "application/octet-stream"
            | "application/wasm"
            | "text/event-stream"
            | "text/plain" => base,
            value if value.starts_with("image/") => "image/*".to_string(),
            value if value.starts_with("audio/") => "audio/*".to_string(),
            value if value.starts_with("video/") => "video/*".to_string(),
            value if value.starts_with("application/") && value.ends_with("+json") => {
                "application/json".to_string()
            }
            "unknown" => base,
            _ => "other".to_string(),
        }
    }
    use axum::body::HttpBody as _;
    let method = req.method().clone();
    let route_metadata = req
        .extensions()
        .get::<MatchedRouteMetadata>()
        .cloned()
        .unwrap_or_else(|| {
            // This can only happen if this middleware is reused outside the
            // assembled Torii router. Keep the fallback bounded and do not
            // consult the request URI.
            MatchedRouteMetadata::unmatched()
        });
    let request_bytes = req.body().size_hint().exact().or_else(|| {
        req.headers()
            .get(axum::http::header::CONTENT_LENGTH)
            .and_then(|value| value.to_str().ok())
            .and_then(|value| value.parse::<u64>().ok())
    });
    let scheme_label = ConnScheme::from_request(&req).label();
    let telemetry = app.telemetry_handle();
    let gateway_request = sorafs_gateway_request_metric_labels(&route_metadata, method.as_str());
    if let Some(labels) = gateway_request {
        telemetry.with_metrics(|tel| tel.start_sorafs_gateway_request(labels));
    }
    let start = Instant::now();
    let response = next.run(req).await;
    let duration = start.elapsed();
    let status = response.status();
    let content_type_header = response
        .headers()
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok());
    let content_type_label = content_type_header
        .map(normalise_content_type)
        .unwrap_or_else(|| "unknown".to_string());
    let response_bytes = response.body().size_hint().exact().or_else(|| {
        response
            .headers()
            .get(axum::http::header::CONTENT_LENGTH)
            .and_then(|value| value.to_str().ok())
            .and_then(|value| value.parse::<u64>().ok())
    });
    let representation = response_representation_label(&response);
    let error_code = response
        .extensions()
        .get::<utils::HttpErrorCode>()
        .map_or_else(
            || {
                if status.is_success() || status.is_redirection() {
                    "none"
                } else {
                    "unclassified"
                }
            },
            utils::HttpErrorCode::as_str,
        );
    let gateway_response = gateway_request.map(|request| {
        let result = if status.is_success() || status.is_redirection() {
            "success"
        } else {
            "error"
        };
        iroha_logger::telemetry!(
            msg = "sorafs.gateway.request",
            endpoint = request.endpoint,
            method = request.method,
            variant = request.variant,
            result,
            status = status.as_u16(),
            error_code,
            duration_ms = duration.as_secs_f64() * 1000.0
        );
        SorafsGatewayResponseMetricLabels {
            request,
            result,
            status: status.as_u16(),
            error_code,
        }
    });
    telemetry.with_metrics(|tel| {
        if let Some(labels) = gateway_response {
            tel.finish_sorafs_gateway_request(labels, duration);
        }
        tel.observe_torii_http_request(
            route_metadata.stable_route_id(),
            route_metadata.path_template(),
            route_surface_label(&route_metadata),
            method.as_str(),
            status,
            content_type_label.as_str(),
            representation,
            error_code,
            duration,
            request_bytes,
            response_bytes,
        );
        tel.observe_torii_request_by_scheme(scheme_label, status, duration);
    });
    Ok(response)
}
// Small helper to enforce token + rate limit
async fn check_access(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &str,
) -> Result<(), Error> {
    check_access_enforced(app, headers, remote, hint, true).await
}
include!("operator_rate_limit_helpers.rs");
fn validate_api_token(
    app: &AppState,
    headers: &axum::http::HeaderMap,
) -> Result<ApiTokenEvaluation, Error> {
    let evaluation = evaluate_api_token(
        app.requires_api_token(),
        app.api_token_digests.as_ref(),
        headers,
    );
    match evaluation {
        ApiTokenEvaluation::Disabled | ApiTokenEvaluation::Authenticated(_) => Ok(evaluation),
        ApiTokenEvaluation::Unavailable => Err(Error::Query(
            iroha_data_model::ValidationFail::NotPermitted(
                "Torii requires an API token but none are configured".to_string(),
            ),
        )),
        ApiTokenEvaluation::Invalid => Err(Error::Query(
            iroha_data_model::ValidationFail::NotPermitted(
                "missing or invalid API token".to_string(),
            ),
        )),
    }
}
async fn check_access_enforced(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &str,
    enforce_rate: bool,
) -> Result<(), Error> {
    check_access_enforced_with_cost(app, headers, remote, hint, enforce_rate, 1).await
}
async fn check_access_enforced_with_cost(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &str,
    enforce_rate: bool,
    cost: u64,
) -> Result<(), Error> {
    let principal = validate_api_token(app, headers)?.authenticated_principal();
    let key = rate_limit_key(headers, remote, hint, principal);
    let cost = cost.max(1);
    if !limits::allow_cost_conditionally(&app.rate_limiter, &key, cost, enforce_rate).await {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
        )));
    }
    Ok(())
}
/// Owned general, optional heavy-query, and optional body permits retained through physical work.
pub(crate) struct QueryAdmissionPermit {
    // Retire this worker's native memory and specialized permits before waking
    // the next general-query worker. Rust drops fields in declaration order.
    _fanout_memory: Option<QueryFanoutMemoryReservation>,
    _body: Option<tokio::sync::OwnedSemaphorePermit>,
    _heavy: Option<tokio::sync::OwnedSemaphorePermit>,
    _query: tokio::sync::OwnedSemaphorePermit,
}
impl QueryAdmissionPermit {
    /// Use the response phase granted by this worker's retained query owner.
    /// Response custody alone cannot grant producer allocation authority.
    pub(crate) fn response_body_budget(&self) -> Result<usize, Error> {
        self._fanout_memory
            .as_ref()
            .and_then(|owner| owner.admission)
            .map(|admission| admission.envelope.route_body_bytes)
            .ok_or_else(|| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(
                    "The query worker has no admitted response memory owner.".to_owned(),
                ))
            })
    }

    #[cfg(test)]
    fn with_body_permit(mut self, permit: tokio::sync::OwnedSemaphorePermit) -> Self {
        self._body = Some(permit);
        self
    }
}
async fn acquire_query_admission(
    app: &AppState,
    heavy: bool,
) -> Result<QueryAdmissionPermit, Error> {
    fn capacity_limit() -> Error {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
        ))
    }
    if app.query_queue_timeout.is_zero() {
        let heavy = heavy
            .then(|| app.query_heavy_inflight.clone().try_acquire_owned())
            .transpose()
            .map_err(|_| capacity_limit())?;
        let query = app
            .query_inflight
            .clone()
            .try_acquire_owned()
            .map_err(|_| capacity_limit())?;
        return Ok(QueryAdmissionPermit {
            _query: query,
            _heavy: heavy,
            _body: None,
            _fanout_memory: current_query_fanout_memory_for_state(app),
        });
    }
    let acquire = async {
        let heavy = if heavy {
            Some(
                app.query_heavy_inflight
                    .clone()
                    .acquire_owned()
                    .await
                    .map_err(|_| capacity_limit())?,
            )
        } else {
            None
        };
        let query = app
            .query_inflight
            .clone()
            .acquire_owned()
            .await
            .map_err(|_| capacity_limit())?;
        Ok(QueryAdmissionPermit {
            _query: query,
            _heavy: heavy,
            _body: None,
            _fanout_memory: current_query_fanout_memory_for_state(app),
        })
    };
    tokio::time::timeout(app.query_queue_timeout, acquire)
        .await
        .map_err(|_| capacity_limit())?
}
fn rate_limit_key(
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &str,
    authenticated_api_token: Option<limits::ApiTokenPrincipal>,
) -> String {
    limits::key_from_headers(headers, remote, Some(hint), authenticated_api_token)
}
fn signed_query_preauth_rate_limit_key(
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    authenticated_api_token: Option<limits::ApiTokenPrincipal>,
) -> String {
    // API-token text is attacker-controlled unless token authentication is
    // enabled and validated. Otherwise ingress middleware has already replaced
    // the internal remote-address header with the accepted socket address or a
    // value from a configured trusted proxy.
    let caller =
        limits::key_from_headers(headers, remote, Some("unknown"), authenticated_api_token);
    format!("v1/query:preauth:{caller}")
}
fn signed_query_authority_rate_limit_key(authority: &AccountId) -> String {
    format!("v1/query:authority:{authority}")
}
async fn consume_signed_query_rate(
    rate_limiter: &limits::RateLimiter,
    key: &str,
) -> Result<(), Error> {
    if rate_limiter.allow(key).await {
        return Ok(());
    }
    Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
    )))
}
async fn admit_signed_query_preauth(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
) -> Result<(), Error> {
    let principal = validate_api_token(app, headers)?.authenticated_principal();
    let key = signed_query_preauth_rate_limit_key(headers, remote, principal);
    consume_signed_query_rate(&app.query_preauth_rate_limiter, &key).await
}
async fn admit_signed_query_authority(app: &AppState, authority: &AccountId) -> Result<(), Error> {
    let key = signed_query_authority_rate_limit_key(authority);
    consume_signed_query_rate(&app.query_authority_rate_limiter, &key).await
}
async fn acquire_signed_query_physical_admission(
    app: &AppState,
    request: &iroha_data_model::query::QueryRequestWithAuthority,
) -> Result<QueryAdmissionPermit, Error> {
    acquire_query_admission(
        app,
        matches!(
            &request.request,
            iroha_data_model::query::QueryRequest::Start(_)
        ),
    )
    .await
}
struct AdmittedOrdinaryQueryExecution {
    plan: routing::OrdinaryQueryExecutionPlan,
    physical_admission: QueryAdmissionPermit,
    memory_lease: iroha_core::smartcontracts::isi::query::OrdinaryQueryMemoryLease,
}
async fn admit_ordinary_query_execution(
    app: &SharedAppState,
    request: &iroha_data_model::query::QueryRequestWithAuthority,
    opts: &QueryOptions,
) -> Result<AdmittedOrdinaryQueryExecution, Error> {
    let plan = routing::ordinary_query_execution_plan(
        app.state.as_ref(),
        &request.request,
        opts,
        app.ordinary_query_policy,
    )?;
    let stored_start = plan.is_stored_start(&request.request);
    admit_signed_query_authority(app.as_ref(), &request.authority).await?;
    let physical_admission = acquire_signed_query_physical_admission(app.as_ref(), request).await?;
    // Fail-fast promotion cannot pin ingress/proxy body-reading slots.
    let memory_lease =
        try_acquire_ordinary_query_memory(app, stored_start, plan.requires_singular_execution())?;
    Ok(AdmittedOrdinaryQueryExecution {
        plan,
        physical_admission,
        memory_lease,
    })
}
async fn execute_prepared_ordinary_query(
    app: &SharedAppState,
    request: iroha_data_model::query::QueryRequestWithAuthority,
    admitted: AdmittedOrdinaryQueryExecution,
) -> Result<iroha_core::query::snapshot::ServerOwnedQueryResponse, Error> {
    routing::execute_admitted_verified_query_with_server_owned_memory(
        app.query_service.clone(),
        app.state.clone(),
        request,
        app.telemetry.clone(),
        admitted.plan,
        admitted.physical_admission,
        admitted.memory_lease,
    )
    .await
}
async fn execute_admitted_signed_query_with_opts(
    app: &SharedAppState,
    request: iroha_data_model::query::QueryRequestWithAuthority,
    opts: QueryOptions,
) -> Result<iroha_core::query::snapshot::ServerOwnedQueryResponse, Error> {
    let admitted = admit_ordinary_query_execution(app, &request, &opts).await?;
    execute_prepared_ordinary_query(app, request, admitted).await
}
fn query_response_cursor_query_id(
    response: &iroha_data_model::query::QueryResponse,
) -> Option<&str> {
    match response {
        iroha_data_model::query::QueryResponse::Iterable(output) => output
            .continue_cursor
            .as_ref()
            .map(|cursor| cursor.query.as_str()),
        iroha_data_model::query::QueryResponse::Singular(_) => None,
    }
}
fn encode_server_owned_query_response(
    app: &AppState,
    response: iroha_core::query::snapshot::ServerOwnedQueryResponse,
    format: ResponseFormat,
) -> Response {
    let (response, memory_lease) = response.into_parts();
    let cursor_query_id = query_response_cursor_query_id(&response).map(ToOwned::to_owned);
    let max_response_bytes =
        match usize::try_from(app.ordinary_query_policy.limits.max_response_bytes()) {
            Ok(bytes) => bytes,
            Err(_) => {
                if let Some(query_id) = cursor_query_id.as_ref() {
                    app.query_service.drop_query(query_id);
                }
                return torii_proxy_error_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "query_capacity_exceeded",
                    "ordinary query response limit is not representable on this platform",
                );
            }
        };
    encode_query_response_with_memory_lease_bounded(
        app,
        response,
        memory_lease,
        format,
        max_response_bytes,
    )
}
fn encode_query_response_with_memory_lease_bounded(
    app: &AppState,
    response: iroha_data_model::query::QueryResponse,
    memory_lease: iroha_core::smartcontracts::isi::query::OrdinaryQueryMemoryLease,
    format: ResponseFormat,
    max_response_bytes: usize,
) -> Response {
    let cursor_query_id = query_response_cursor_query_id(&response).map(ToOwned::to_owned);
    match crate::utils::respond_with_format_bounded(response, format, max_response_bytes) {
        Ok(response) => hold_ordinary_query_memory_in_response_body(
            response,
            OrdinaryQueryResponseMemory::new(memory_lease),
        ),
        Err(error) => {
            if let Some(query_id) = cursor_query_id.as_ref() {
                app.query_service.drop_query(query_id);
            }
            match error {
                crate::utils::BoundedResponseEncodeError::BodyTooLarge { .. }
                | crate::utils::BoundedResponseEncodeError::JsonBodyTooLarge { .. } => {
                    torii_proxy_error_response(
                        StatusCode::PAYLOAD_TOO_LARGE,
                        "query_capacity_exceeded",
                        "ordinary query response exceeds its admitted body reservation",
                    )
                }
                crate::utils::BoundedResponseEncodeError::Serialization => {
                    torii_proxy_error_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        "query_encoding_failed",
                        "ordinary query response serialization failed",
                    )
                }
            }
        }
    }
}
