#[cfg(all(feature = "app_api", feature = "push"))]
fn push_authenticate_device_request(
    app: &SharedAppState,
    method: &HttpMethod,
    uri: &axum::http::Uri,
    headers: &HeaderMap,
    body: &[u8],
) -> Result<crate::app_auth::VerifiedCanonicalRequest, AxResponse> {
    let authentication_owner =
        match crate::history_producer::HistoryProducerOwner::authentication_read(&app) {
            Ok(owner) => owner,
            Err(error) => {
                return Err(error.into_response());
            }
        };

    match crate::app_auth::verify_canonical_network_request(
        &app.state,
        app.state.network_id_ref(),
        headers,
        method,
        uri,
        body,
        None,
        authentication_owner.allocation_context(),
    ) {
        Ok(Some(verified)) => Ok(verified),
        Ok(None) => Err(push_error_response(
            StatusCode::UNAUTHORIZED,
            "push_auth_required",
            "signed account headers are required",
        )),
        Err(error) => Err(push_auth_error_response(error)),
    }
}
#[cfg(all(feature = "app_api", feature = "push"))]
fn require_push_bridge(app: &SharedAppState) -> Result<(), AxResponse> {
    if app.push.is_none() {
        return Err(push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_disabled",
            "push bridge disabled",
        ));
    }
    Ok(())
}
#[cfg(all(feature = "app_api", feature = "push"))]
fn push_authorize_device_account(
    app: &SharedAppState,
    verified: &crate::app_auth::VerifiedCanonicalRequest,
    account_literal: &str,
) -> Result<AccountId, AxResponse> {
    let account_id = match routing::parse_account_literal_with_state(
        app.state.as_ref(),
        account_literal,
        &app.telemetry,
        "/v1/notify/devices",
    ) {
        Ok((account_id, _)) => account_id,
        Err(_) => {
            return Err(push_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_account",
                format!("invalid account id `{}`", account_literal.trim()),
            ));
        }
    };
    if verified.account == account_id {
        Ok(account_id)
    } else {
        Err(push_error_response(
            StatusCode::FORBIDDEN,
            "push_account_mismatch",
            "signed account does not match device account",
        ))
    }
}
#[cfg(all(feature = "app_api", feature = "push"))]
fn push_auth_error_response(error: Error) -> AxResponse {
    push_error_response(
        StatusCode::UNAUTHORIZED,
        "push_auth_invalid",
        error.to_string(),
    )
}
async fn check_proof_access(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    cost: u64,
    enforce_rate: bool,
) -> Result<(), Error> {
    check_access_enforced(app, headers, remote, hint, enforce_rate).await?;
    let key = rate_limit_key(
        headers,
        remote,
        hint,
        app.authenticated_api_token_principal(headers),
    );
    if limits::allow_cost_conditionally(&app.proof_rate_limiter, &key, cost, enforce_rate).await {
        return Ok(());
    }
    app.telemetry
        .with_metrics(|tel| tel.inc_torii_proof_throttle(hint));
    app.telemetry.with_metrics(|tel| {
        tel.observe_torii_proof_request(hint, "rate_limited", 0, std::time::Duration::from_secs(0))
    });
    let retry_after_secs = app.proof_limits.retry_after.as_secs().max(1);
    iroha_logger::warn!(
        %hint,
        %retry_after_secs,
        "proof endpoint throttled request"
    );
    Err(Error::ProofRateLimited {
        endpoint: hint,
        retry_after_secs,
    })
}
// The proof API rate configuration is expressed in requests per minute with a
// request burst. Body bytes are bounded separately by `max_body_bytes`.
const PROOF_REQUEST_RATE_COST: u64 = 1;
#[derive(Clone, Copy)]
struct BoundedBodyReadMessages {
    context: &'static str,
    too_large: &'static str,
    protocol_error: &'static str,
    timeout: &'static str,
}
async fn collect_bounded_body_with_deadline(
    request: axum::http::Request<Body>,
    max_bytes: usize,
    deadline: Duration,
    messages: BoundedBodyReadMessages,
) -> Result<axum::http::Request<Body>, Response> {
    let (parts, body) = request.into_parts();
    let bytes = match tokio::time::timeout(deadline, axum::body::to_bytes(body, max_bytes)).await {
        Ok(Ok(bytes)) => bytes,
        Ok(Err(error)) => {
            let mut source: Option<&(dyn std::error::Error + 'static)> = Some(&error);
            let mut length_limited = false;
            while let Some(current) = source {
                if current.is::<http_body_util::LengthLimitError>() {
                    length_limited = true;
                    break;
                }
                source = current.source();
            }
            let (status, message) = if length_limited {
                (StatusCode::PAYLOAD_TOO_LARGE, messages.too_large)
            } else {
                iroha_logger::warn!(
                    %error,
                    context = messages.context,
                    "failed to read bounded request body stream"
                );
                (StatusCode::BAD_REQUEST, messages.protocol_error)
            };
            return Err((status, message).into_response());
        }
        Err(_) => {
            return Err((StatusCode::REQUEST_TIMEOUT, messages.timeout).into_response());
        }
    };
    Ok(axum::http::Request::from_parts(parts, Body::from(bytes)))
}
async fn collect_proof_body_with_deadline(
    request: axum::http::Request<Body>,
    max_bytes: usize,
    deadline: Duration,
) -> Result<axum::http::Request<Body>, Response> {
    collect_bounded_body_with_deadline(
        request,
        max_bytes,
        deadline,
        BoundedBodyReadMessages {
            context: "proof request body",
            too_large: "proof request body exceeds the configured byte limit",
            protocol_error: "proof request body stream ended with a protocol error",
            timeout: "proof request body was not completed before the absolute read deadline",
        },
    )
    .await
}
#[cfg(feature = "app_api")]
async fn collect_verified_source_body_with_deadline(
    request: axum::http::Request<Body>,
    max_bytes: usize,
    deadline: Duration,
) -> Result<axum::http::Request<Body>, Response> {
    collect_bounded_body_with_deadline(
        request,
        max_bytes,
        deadline,
        BoundedBodyReadMessages {
            context: "verified-source request body",
            too_large: "verified-source request body exceeds the first-release byte limit",
            protocol_error: "verified-source request body stream ended with a protocol error",
            timeout:
                "verified-source request body was not completed before the absolute read deadline",
        },
    )
    .await
}
#[cfg(feature = "app_api")]
#[derive(Clone)]
struct VerifiedSourceCompileAdmission {
    permit: Arc<std::sync::Mutex<Option<tokio::sync::OwnedSemaphorePermit>>>,
}
#[cfg(feature = "app_api")]
impl VerifiedSourceCompileAdmission {
    fn new(permit: tokio::sync::OwnedSemaphorePermit) -> Self {
        Self {
            permit: Arc::new(std::sync::Mutex::new(Some(permit))),
        }
    }
    fn take(&self) -> Result<tokio::sync::OwnedSemaphorePermit, Error> {
        self.permit
            .lock()
            .map_err(|_| Error::AppServiceUnavailable {
                code: "verified_source_compile_admission_invalid",
                message: "verified-source compiler admission state is unavailable".to_owned(),
            })?
            .take()
            .ok_or_else(|| Error::AppServiceUnavailable {
                code: "verified_source_compile_admission_invalid",
                message: "verified-source compiler admission was already consumed".to_owned(),
            })
    }
}
#[derive(Clone)]
struct CanonicalAccountBodyAuthState {
    app: SharedAppState,
    max_body_bytes: usize,
    missing_auth_code: &'static str,
    missing_auth_message: &'static str,
}
#[derive(Clone)]
struct OptionalCanonicalAccountBodyAuthState {
    app: SharedAppState,
    max_body_bytes: usize,
}
#[cfg(feature = "app_api")]
fn admitted_app_routed_read_body_for_auth(parts: &axum::http::request::Parts) -> Option<Bytes> {
    if !app_routed_read_http_admission_is_active() {
        return None;
    }
    parts
        .extensions
        .get::<AdmittedAppRoutedReadBody>()
        .map(|body| body.bytes.clone())
}
#[cfg(not(feature = "app_api"))]
fn admitted_app_routed_read_body_for_auth(_parts: &axum::http::request::Parts) -> Option<Bytes> {
    None
}
fn canonical_account_body_limit_response() -> Response {
    const REJECT_CODE: &str = "request_payload_too_large";
    let mut response = utils::respond_with_status_and_format(
        StatusCode::PAYLOAD_TOO_LARGE,
        ErrorEnvelope::new(
            REJECT_CODE,
            "The request body exceeds the configured route limit.",
        ),
        utils::current_response_format(),
    );
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-reject-code"),
        HeaderValue::from_static(REJECT_CODE),
    );
    install_canonical_account_private_cache_headers(&mut response);
    response
}
async fn enforce_canonical_account_body_authentication(
    State(state): State<CanonicalAccountBodyAuthState>,
    request: axum::http::Request<Body>,
    next: Next,
) -> Response {
    let authentication_owner =
        match crate::history_producer::HistoryProducerOwner::authentication_read(&state.app) {
            Ok(owner) => owner,
            Err(error) => {
                return error.into_response();
            }
        };

    let (mut parts, body) = request.into_parts();
    let body = if let Some(admitted) = admitted_app_routed_read_body_for_auth(&parts) {
        if admitted.len() > state.max_body_bytes {
            return canonical_account_body_limit_response();
        }
        // Routed-read admission has already drained and retained this exact
        // body under the fanout lease. Reuse its ref-counted bytes instead of
        // collecting a second representation inside authentication.
        drop(body);
        admitted
    } else {
        match axum::body::to_bytes(body, state.max_body_bytes).await {
            Ok(body) => body,
            Err(error) => {
                iroha_logger::warn!(%error, "canonical account request body exceeded its route limit");
                return canonical_account_body_limit_response();
            }
        }
    };
    let network_id = state.app.signed_query_admission.network_id();
    let verified = match crate::app_auth::verify_canonical_network_request(
        &state.app.state,
        &network_id,
        &parts.headers,
        &parts.method,
        &parts.uri,
        body.as_ref(),
        None,
        authentication_owner.allocation_context(),
    ) {
        Ok(Some(verified)) => verified,
        Ok(None) => {
            return Error::AppUnauthorized {
                code: state.missing_auth_code,
                message: state.missing_auth_message.to_owned(),
            }
            .into_response();
        }
        Err(error) => return error.into_response(),
    };
    parts.extensions.insert(verified);
    let mut response = next
        .run(axum::http::Request::from_parts(parts, Body::from(body)))
        .await;
    install_canonical_account_private_cache_headers(&mut response);
    response
}
async fn enforce_optional_canonical_account_body_authentication(
    State(state): State<OptionalCanonicalAccountBodyAuthState>,
    request: axum::http::Request<Body>,
    next: Next,
) -> Response {
    let authentication_owner =
        match crate::history_producer::HistoryProducerOwner::authentication_read(&state.app) {
            Ok(owner) => owner,
            Err(error) => {
                return error.into_response();
            }
        };

    let (mut parts, body) = request.into_parts();
    let body = if let Some(admitted) = admitted_app_routed_read_body_for_auth(&parts) {
        if admitted.len() > state.max_body_bytes {
            return canonical_account_body_limit_response();
        }
        drop(body);
        admitted
    } else {
        match axum::body::to_bytes(body, state.max_body_bytes).await {
            Ok(body) => body,
            Err(error) => {
                iroha_logger::warn!(%error, "optional canonical account request body exceeded its route limit");
                return canonical_account_body_limit_response();
            }
        }
    };
    let network_id = state.app.signed_query_admission.network_id();
    let visibility = match crate::app_auth::verify_canonical_network_request(
        &state.app.state,
        &network_id,
        &parts.headers,
        &parts.method,
        &parts.uri,
        body.as_ref(),
        None,
        authentication_owner.allocation_context(),
    ) {
        Ok(Some(verified)) => ToriiAccountReadVisibility::Signed(verified.account),
        Ok(None) => ToriiAccountReadVisibility::None,
        Err(error) => {
            return Error::AppUnauthorized {
                code: "canonical_authentication_invalid",
                message: error.to_string(),
            }
            .into_response();
        }
    };
    parts.extensions.insert(visibility);
    let mut response = next
        .run(axum::http::Request::from_parts(parts, Body::from(body)))
        .await;
    install_canonical_account_private_cache_headers(&mut response);
    response
}
async fn proof_body_admission_middleware(
    State(admission): State<ProofBodyAdmissionState>,
    request: axum::http::Request<Body>,
    next: Next,
) -> Response {
    let app = &admission.app;
    let permit = match app.proof_body_inflight.clone().try_acquire_owned() {
        Ok(permit) => permit,
        Err(_) => {
            return Error::ProofRateLimited {
                endpoint: "proof request body admission",
                retry_after_secs: app.proof_limits.retry_after.as_secs().max(1),
            }
            .into_response();
        }
    };
    let mut request = match collect_proof_body_with_deadline(
        request,
        admission.max_body_bytes,
        app.proof_limits.body_read_timeout,
    )
    .await
    {
        Ok(request) => request,
        Err(response) => {
            drop(permit);
            return response;
        }
    };
    let lease = ProofBodyAdmissionLease::new(permit);
    request.extensions_mut().insert(lease.clone());
    // Keep physical admission until every downstream operation returns. This
    // bounds concurrent attachment sanitizer blocking tasks and child processes.
    // The request extension is cloned into detached blocking work so cancelling
    // the HTTP future cannot release capacity while that work is still running.
    let response = next.run(request).await;
    drop(lease);
    response
}
#[derive(Clone)]
pub(crate) struct ProofBodyAdmissionLease {
    _permit: Arc<tokio::sync::OwnedSemaphorePermit>,
}
impl ProofBodyAdmissionLease {
    fn new(permit: tokio::sync::OwnedSemaphorePermit) -> Self {
        Self {
            _permit: Arc::new(permit),
        }
    }
}
#[derive(Clone)]
struct ProofBodyAdmissionState {
    app: SharedAppState,
    /// Exact route cap used before authentication buffers the retained body.
    max_body_bytes: usize,
}
impl ProofBodyAdmissionState {
    fn new(app: SharedAppState, max_body_bytes: usize) -> Self {
        Self {
            app,
            max_body_bytes,
        }
    }
}
#[cfg(feature = "app_api")]
async fn verified_source_body_admission_middleware(
    State(app): State<SharedAppState>,
    request: axum::http::Request<Body>,
    next: Next,
) -> Response {
    let permit = match app
        .verified_source_compile_inflight
        .clone()
        .try_acquire_owned()
    {
        Ok(permit) => permit,
        Err(_) => {
            return Error::AppServiceUnavailable {
                code: "verified_source_compile_saturated",
                message: "verified-source compiler capacity is unavailable; retry later".to_owned(),
            }
            .into_response();
        }
    };
    let request = match collect_verified_source_body_with_deadline(
        request,
        contract_sources::VERIFIED_SOURCE_SUBMISSION_MAX_HTTP_BODY_BYTES_V1,
        app.verified_source_body_read_timeout,
    )
    .await
    {
        Ok(mut request) => {
            request
                .extensions_mut()
                .insert(VerifiedSourceCompileAdmission::new(permit));
            request
        }
        Err(response) => return response,
    };
    next.run(request).await
}
#[cfg(test)]
fn proof_post_router_with_body_limits(
    router: Router<SharedAppState>,
    state: SharedAppState,
) -> Router<SharedAppState> {
    let max_body_bytes = state.proof_limits.max_body_bytes;
    let body_limit = DefaultBodyLimit::max(max_body_bytes);
    let admission = axum::middleware::from_fn_with_state(
        ProofBodyAdmissionState::new(state, max_body_bytes),
        proof_body_admission_middleware,
    );
    // The admission middleware is outermost, so aggregate capacity is acquired
    // before Axum buffers/extracts each request body.
    router.layer(body_limit).layer(admission)
}
fn enforce_proof_body_limit(app: &AppState, len: usize, hint: &'static str) -> Result<(), Error> {
    let max = app.proof_limits.max_body_bytes;
    if len <= max {
        return Ok(());
    }
    app.telemetry
        .with_metrics(|tel| tel.inc_torii_proof_throttle(hint));
    Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
            "payload too large for {hint}: {len} > {max}"
        )),
    )))
}
async fn enforce_proof_egress(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    bytes: u64,
    enforce_rate: bool,
) -> Result<(), Error> {
    if bytes == 0 {
        return Ok(());
    }
    let key = rate_limit_key(
        headers,
        remote,
        hint,
        app.authenticated_api_token_principal(headers),
    );
    if limits::allow_cost_conditionally(&app.proof_egress_limiter, &key, bytes, enforce_rate).await
    {
        return Ok(());
    }
    app.telemetry
        .with_metrics(|tel| tel.inc_torii_proof_throttle(hint));
    let retry_after_secs = app.proof_limits.retry_after.as_secs().max(1);
    iroha_logger::warn!(
        %hint,
        %retry_after_secs,
        bytes,
        "proof endpoint egress throttled request"
    );
    Err(Error::ProofRateLimited {
        endpoint: hint,
        retry_after_secs,
    })
}
/// Charge the exact bytes of an internally buffered proof response before it
/// is handed to Hyper. Collecting here also makes the accounting invariant
/// independent of HTTP body size-hint implementations.
async fn proof_response_with_exact_egress(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    response: axum::response::Response,
    enforce_rate: bool,
) -> Result<axum::response::Response, Error> {
    let (parts, body) = response.into_parts();
    let max_response_bytes = app.torii_proxy_max_response_bytes.max(1);
    let body = axum::body::to_bytes(body, max_response_bytes)
        .await
        .map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "buffered {hint} proof response exceeds the configured {max_response_bytes}-byte content limit: {error}"
            )))
        })?;
    enforce_proof_egress(
        app,
        headers,
        remote,
        hint,
        u64::try_from(body.len()).unwrap_or(u64::MAX),
        enforce_rate,
    )
    .await?;
    Ok(axum::response::Response::from_parts(
        parts,
        axum::body::Body::from(body),
    ))
}
#[cfg(test)]
async fn proof_json_response_with_egress<T>(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    payload: T,
    enforce_rate: bool,
) -> Result<axum::response::Response, Error>
where
    T: JsonSerialize,
{
    // Serialize exactly once so the charged byte count is identical to the
    // response body sent to the client.
    let body = norito::json::to_vec(&payload).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            err.to_string(),
        ))
    })?;
    enforce_proof_egress(app, headers, remote, hint, body.len() as u64, enforce_rate).await?;
    let mut response = axum::response::Response::new(axum::body::Body::from(body));
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(response)
}
async fn proof_cached_json_response_with_egress(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    body: Bytes,
    enforce_rate: bool,
) -> Result<axum::response::Response, Error> {
    // Charge the immutable cached representation before the cheap ref-counted
    // clone is handed to Axum. Concurrent GETs therefore cannot duplicate a
    // multi-megabyte proved payload in process memory.
    enforce_proof_egress(app, headers, remote, hint, body.len() as u64, enforce_rate).await?;
    let mut response = axum::response::Response::new(axum::body::Body::from(body));
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(response)
}
fn install_canonical_account_private_cache_headers(response: &mut Response) {
    response.headers_mut().insert(
        axum::http::header::CACHE_CONTROL,
        HeaderValue::from_static("private, no-store"),
    );
    response.headers_mut().insert(
        axum::http::header::VARY,
        HeaderValue::from_static(crate::content::CANONICAL_CONTENT_AUTH_VARY),
    );
}
