/// Forward `/v1/zk/verify-batch` requests with explicit finite diagnostic limits.
///
/// `max_body_bytes` is enforced before either Norito or JSON decoding. The
/// remaining limits bound the decoded batch, each envelope, and native IPA
/// reconstruction.
///
/// # Errors
/// Propagates routing errors when response rendering fails.
#[cfg(all(feature = "app_api", feature = "zk-verify-batch"))]
pub async fn handle_v1_zk_verify_batch_with_limits(
    headers: axum::http::HeaderMap,
    body: axum::body::Bytes,
    open_limits: iroha_zkp_halo2::OpenVerifyLimits,
    max_body_bytes: usize,
    max_batch: usize,
    max_envelope_bytes: usize,
    enforce_transcript_label_ascii: bool,
) -> Result<impl IntoResponse, Error> {
    crate::routing::handle_v1_zk_verify_batch_with_limits(
        headers,
        body,
        crate::routing::ZkVerifyBatchLimits {
            open: open_limits,
            max_body_bytes,
            max_batch,
            max_envelope_bytes,
            enforce_transcript_label_ascii,
        },
    )
    .await
}
#[cfg(feature = "app_api")]
#[axum::debug_handler]
async fn handler_accounts_capabilities(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    uri: axum::http::Uri,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    use iroha_torii_shared::account_capabilities::{
        ACCOUNT_CAPABILITIES_MAX_BYTES_V1, AccountCapabilitiesV1,
    };
    if uri.query().is_some() || !body.is_empty() {
        return Err(Error::AppQueryValidation {
            code: "account_capabilities_request_unsupported",
            message: "Account capability discovery accepts no query parameters or body.".to_owned(),
        });
    }
    check_access(
        &app,
        &headers,
        Some(remote.ip()),
        "v1/accounts/capabilities",
    )
    .await?;
    let crypto = app.state.crypto();
    let payload = AccountCapabilitiesV1::from_admission(
        *app.state.network_id_ref(),
        iroha_data_model::account::address::chain_discriminant(),
        &crypto.allowed_signing,
    )
    .map_err(|message| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            message.to_owned(),
        ))
    })?;
    let bytes = norito::json::to_vec(&payload).map_err(|source| Error::SerializationFailure {
        context: "account_capabilities",
        source: Box::new(source),
    })?;
    if bytes.len() > ACCOUNT_CAPABILITIES_MAX_BYTES_V1 {
        return Err(Error::Query(
            iroha_data_model::ValidationFail::InternalError(
                "account capabilities exceed the V1 representation bound".to_owned(),
            ),
        ));
    }
    Ok((
        [
            (axum::http::header::CONTENT_TYPE, "application/json"),
            (axum::http::header::CACHE_CONTROL, "no-store"),
        ],
        bytes,
    )
        .into_response())
}

