#[cfg(feature = "app_api")]
fn identifier_normalization_label(
    normalization: iroha_data_model::identifier::IdentifierNormalization,
) -> &'static str {
    match normalization {
        iroha_data_model::identifier::IdentifierNormalization::Exact => "exact",
        iroha_data_model::identifier::IdentifierNormalization::LowercaseTrimmed => {
            "lowercase_trimmed"
        }
        iroha_data_model::identifier::IdentifierNormalization::PhoneE164 => "phone_e164",
        iroha_data_model::identifier::IdentifierNormalization::EmailAddress => "email_address",
        iroha_data_model::identifier::IdentifierNormalization::AccountNumber => "account_number",
    }
}
#[cfg(feature = "app_api")]
fn identifier_conversion_error(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(message.into()),
    ))
}
#[cfg(feature = "app_api")]
fn identifier_internal_error(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::InternalError(
        message.into(),
    ))
}
#[cfg(feature = "app_api")]
fn identifier_execution_error(error: identifier_resolution::IdentifierResolutionError) -> Error {
    if matches!(
        &error,
        identifier_resolution::IdentifierResolutionError::Evaluation(
            iroha_crypto::RamLfeError::InsecureBfvProfile
        )
    ) {
        return Error::AppServiceUnavailable {
            code: "ram_lfe_encryption_unavailable",
            message: error.to_string(),
        };
    }
    if matches!(
        &error,
        identifier_resolution::IdentifierResolutionError::UnsupportedBackend(_)
    ) {
        return Error::AppServiceUnavailable {
            code: "ram_lfe_backend_unavailable",
            message: "This backend does not support authenticated owner PRF execution.".to_owned(),
        };
    }
    identifier_internal_error(error.to_string())
}
#[cfg(feature = "app_api")]
fn identifier_owner_unauthorized() -> Error {
    Error::AppUnauthorized {
        code: "identifier_owner_required",
        message: "The current ledger identifier policy owner must authenticate this exact request."
            .to_owned(),
    }
}
#[cfg(feature = "app_api")]
fn authenticate_identifier_owner_request(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
) -> Result<AccountId, Error> {
    if method != axum::http::Method::POST
        || uri.query().is_some()
        || body.is_empty()
        || body.len() > 16_384
    {
        return Err(identifier_conversion_error(
            "owner PRF requires a bounded exact POST body without a query",
        ));
    }
    require_signed_account_request(
        app,
        headers,
        method,
        uri,
        body,
        "identifier_owner_required",
        "The current ledger identifier policy owner must authenticate this exact request.",
    )
}
#[cfg(feature = "app_api")]
fn require_identifier_program_owner(
    caller: &AccountId,
    program_policy: &iroha_data_model::ram_lfe::RamLfeProgramPolicy,
) -> Result<(), Error> {
    if caller != &program_policy.owner {
        return Err(identifier_owner_unauthorized());
    }
    Ok(())
}
#[cfg(feature = "app_api")]
fn identifier_claim_is_live_at(
    claim: &iroha_data_model::identifier::IdentifierClaimRecord,
    now_ms: u64,
) -> bool {
    now_ms > 0
        && claim.verified_at_ms <= now_ms
        && claim.expires_at_ms.is_none_or(|expiry| expiry > now_ms)
}
#[cfg(feature = "app_api")]
fn parse_identifier_input_nonce(raw: &str) -> Result<[u8; 32], Error> {
    if raw.len() != 64
        || !raw
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(identifier_conversion_error(
            "input_nonce must be exactly 64 lowercase hexadecimal characters",
        ));
    }
    let bytes = zeroize::Zeroizing::new(
        hex::decode(raw).map_err(|_| identifier_conversion_error("invalid input_nonce"))?,
    );
    if bytes.len() != 32 {
        return Err(identifier_conversion_error("invalid input_nonce length"));
    }
    let mut nonce = [0_u8; 32];
    nonce.copy_from_slice(bytes.as_slice());
    if nonce.iter().all(|byte| *byte == 0) {
        return Err(identifier_conversion_error(
            "input_nonce must be privately generated and nonzero",
        ));
    }
    Ok(nonce)
}
#[cfg(feature = "app_api")]
fn parse_hex_bytes(raw: &str, field_name: &str) -> Result<Vec<u8>, Error> {
    let literal = raw.trim();
    if literal.is_empty() {
        return Err(identifier_conversion_error(format!(
            "{field_name} must not be empty"
        )));
    }
    hex::decode(literal.trim_start_matches("0x"))
        .map_err(|err| identifier_conversion_error(format!("{field_name} is not valid hex: {err}")))
}
#[cfg(feature = "app_api")]
fn ram_lfe_verification_mode_label(mode: iroha_crypto::RamLfeVerificationMode) -> &'static str {
    match mode {
        iroha_crypto::RamLfeVerificationMode::Signed => "signed",
        iroha_crypto::RamLfeVerificationMode::Proof => "proof",
    }
}
#[cfg(feature = "app_api")]
fn derive_ram_lfe_request_draft(
    resolver: &identifier_resolution::IdentifierResolutionService,
    program_policy: &iroha_data_model::ram_lfe::RamLfeProgramPolicy,
    request: &routing::RamLfeExecuteRequestDto,
    network_id: &iroha_data_model::NetworkId,
) -> Result<identifier_resolution::RamLfeExecutionDraft, Error> {
    identifier_resolution::require_supported_program_policy(program_policy)
        .map_err(identifier_execution_error)?;
    let nonce = zeroize::Zeroizing::new(parse_identifier_input_nonce(&request.input_nonce)?);
    resolver
        .execute_owner_prf(
            program_policy,
            &request.normalized_input,
            &nonce,
            network_id,
        )
        .map_err(identifier_execution_error)
}
#[cfg(feature = "app_api")]
fn derive_identifier_request_draft(
    resolver: &identifier_resolution::IdentifierResolutionService,
    policy: &iroha_data_model::identifier::IdentifierPolicy,
    program_policy: &iroha_data_model::ram_lfe::RamLfeProgramPolicy,
    request: &routing::IdentifierResolveRequestDto,
    network_id: &iroha_data_model::NetworkId,
) -> Result<identifier_resolution::IdentifierResolutionDraft, Error> {
    if request.phase != "claim" {
        return Err(identifier_conversion_error(
            "identifier receipt resolution requires phase claim",
        ));
    }
    identifier_resolution::require_supported_program_policy(program_policy)
        .map_err(identifier_execution_error)?;
    let nonce = zeroize::Zeroizing::new(parse_identifier_input_nonce(&request.input_nonce)?);
    let opening = request.output_opening.clone().ok_or_else(|| {
        identifier_conversion_error("claim requires the original signed native owner PRF opening")
    })?;
    resolver
        .derive_owner_prf(
            policy,
            program_policy,
            &request.normalized_input,
            &nonce,
            opening,
            request.phone_retail_canonicality.clone(),
            network_id,
        )
        .map_err(identifier_execution_error)
}
#[cfg(feature = "app_api")]
fn ram_lfe_proof_verifier_metadata_dto(
    verifier: Option<&iroha_crypto::RamLfeProofVerifierMetadata>,
) -> Option<routing::RamLfeProofVerifierMetadataDto> {
    verifier.map(|metadata| routing::RamLfeProofVerifierMetadataDto {
        proof_backend: metadata.proof_backend.clone(),
        circuit_id: metadata.circuit_id.clone(),
        public_inputs_schema_hash: metadata.public_inputs_schema_hash.to_string(),
        verifying_key_bytes_b64: BASE64_STANDARD.encode(&metadata.verifying_key_bytes),
    })
}
