#[cfg(feature = "app_api")]
fn parse_domain_id(raw: &str) -> Result<DomainId, Error> {
    DomainId::parse_fully_qualified(raw)
        .map_err(|_| Error::Query(iroha_data_model::ValidationFail::TooComplex))
}
#[cfg(feature = "app_api")]
fn parse_kaigi_call_id(raw: &str) -> Result<iroha_data_model::kaigi::KaigiId, Error> {
    let trimmed = raw.trim();
    let (domain_raw, call_name_raw) = trimmed
        .split_once(':')
        .ok_or_else(|| Error::Query(iroha_data_model::ValidationFail::TooComplex))?;
    let domain_id = DomainId::parse_fully_qualified(domain_raw)
        .map_err(|_| Error::Query(iroha_data_model::ValidationFail::TooComplex))?;
    let call_name = call_name_raw
        .parse::<Name>()
        .map_err(|_| Error::Query(iroha_data_model::ValidationFail::TooComplex))?;
    Ok(iroha_data_model::kaigi::KaigiId::new(domain_id, call_name))
}
#[cfg(feature = "app_api")]
fn parse_asset_definition_id_in_world(
    world: &impl WorldReadOnly,
    alias_observation_time_ms: u64,
    raw: &str,
) -> Result<AssetDefinitionId, Error> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Err(Error::Query(iroha_data_model::ValidationFail::TooComplex));
    }
    if let Ok(id) = AssetDefinitionId::parse_address_literal(trimmed) {
        return world.asset_definition(&id).map(|_| id).map_err(|_| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::NotFound,
            ))
        });
    }
    let alias = AssetDefinitionAlias::from_str(trimmed)
        .map_err(|_| Error::Query(iroha_data_model::ValidationFail::TooComplex))?;
    world
        .asset_definition_id_by_alias_at(&alias, alias_observation_time_ms)
        .ok_or_else(|| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::NotFound,
            ))
        })
}
#[cfg(feature = "app_api")]
fn parse_asset_definition_id(app: &AppState, raw: &str) -> Result<AssetDefinitionId, Error> {
    let world = app.state.world_view();
    parse_asset_definition_id_in_world(
        &world,
        routing::asset_alias_observation_time_ms(app.state.as_ref()),
        raw,
    )
}
#[cfg(feature = "app_api")]
fn resolve_tx_history_allowed_asset_definition_id(
    app: &AppState,
) -> Result<Option<AssetDefinitionId>, Error> {
    app.tx_history_access_policy
        .allowed_asset_definition_id
        .as_deref()
        .map(|selector| {
            let trimmed = selector.trim();
            if let Ok(id) = AssetDefinitionId::parse_address_literal(trimmed) {
                return Ok(id);
            }
            parse_asset_definition_id(app, selector)
        })
        .transpose()
}
