fn torii_proxy_error_response(
    status: StatusCode,
    code: &'static str,
    message: impl Into<String>,
) -> Response {
    let payload = ErrorEnvelope::new(code, message.into());
    let mut response = (status, NoritoBody(payload)).into_response();
    if let Ok(header) = HeaderValue::from_str(code) {
        response
            .headers_mut()
            .insert(HeaderName::from_static("x-iroha-reject-code"), header);
    }
    response
}
#[cfg(feature = "app_api")]
fn torii_canonical_auth_required_response(
    code: &'static str,
    message: impl Into<String>,
) -> Response {
    let mut response = torii_proxy_error_response(StatusCode::UNAUTHORIZED, code, message);
    response.headers_mut().insert(
        axum::http::header::WWW_AUTHENTICATE,
        HeaderValue::from_static("Signature"),
    );
    response
}
#[cfg(feature = "app_api")]
fn torii_alias_permission_denied_response(message: impl Into<String>) -> Response {
    torii_proxy_error_response(StatusCode::FORBIDDEN, "permission_denied", message)
}
#[cfg(feature = "connect")]
const TORII_PROXY_DEFAULT_MAX_HOPS: u8 = 3;
/// The public outer route timer is 65 seconds. Keep one second for Torii to
/// serialize and return the final response, so authenticated proxy execution
/// can never outlive the sender's route owner.
#[cfg(feature = "connect")]
const TORII_PROXY_EXECUTION_BUDGET: Duration = Duration::from_secs(64);
/// Reject deadlines whose wall-clock horizon could not have been produced by
/// a compliant sender. Internal HTTP proxy requests use the operator-signature
/// clock contract, so the wire protocol admits exactly that canonical default
/// skew without allowing a wider local execution lifetime.
#[cfg(feature = "connect")]
const TORII_PROXY_DEADLINE_CLOCK_SKEW_ALLOWANCE: Duration = Duration::from_secs(
    iroha_config::parameters::defaults::torii::operator_signatures::MAX_CLOCK_SKEW_SECS,
);
/// Hard absolute-horizon bound, including the audited first-release clock-skew
/// allowance. Runtime work is independently capped by
/// [`TORII_PROXY_EXECUTION_BUDGET`].
#[cfg(feature = "connect")]
const TORII_PROXY_MAX_DEADLINE_HORIZON: Duration = Duration::from_secs(
    TORII_PROXY_EXECUTION_BUDGET.as_secs() + TORII_PROXY_DEADLINE_CLOCK_SKEW_ALLOWANCE.as_secs(),
);
/// Time left inside the authenticated deadline for bounded response encoding
/// and P2P actor handoff after receiver execution stops.
#[cfg(feature = "connect")]
const TORII_PROXY_RESPONSE_EGRESS_RESERVE: Duration = Duration::from_secs(1);
#[cfg(feature = "connect")]
const TORII_INTERNAL_PROXY_HTTP_PATH: &str = "/v1/internal/torii/proxy";
#[cfg(feature = "connect")]
#[derive(Clone, Debug, PartialEq, Eq)]
struct AuthoritativeLanePeerStatus {
    peer_id: PeerId,
    torii_url: Option<String>,
}
#[cfg(feature = "connect")]
#[derive(Debug)]
struct AuthoritativeLanePeers {
    #[cfg(test)]
    authoritative: Vec<PeerId>,
    authoritative_total_count: usize,
    online: Vec<PeerId>,
    offline: Vec<AuthoritativeLanePeerStatus>,
}
#[cfg(feature = "connect")]
fn authoritative_lane_peer_statuses_with_manifest_urls(
    authoritative_peer_ids: Vec<PeerId>,
    manifest_torii_urls: BTreeMap<PeerId, String>,
) -> Vec<AuthoritativeLanePeerStatus> {
    authoritative_peer_ids
        .into_iter()
        .map(|peer_id| AuthoritativeLanePeerStatus {
            torii_url: manifest_torii_urls.get(&peer_id).cloned(),
            peer_id,
        })
        .collect()
}
fn lane_authority_route(
    routing_decision: RoutingDecision,
) -> iroha_core::state::LaneAuthorityRoute {
    iroha_core::state::LaneAuthorityRoute::new(
        routing_decision.lane_id,
        routing_decision.dataspace_id,
    )
}
#[cfg(feature = "connect")]
fn authoritative_lane_peer_statuses(
    app: &AppState,
    routing_decision: RoutingDecision,
) -> Vec<AuthoritativeLanePeerStatus> {
    // State authority is canonical: every route's authority is the global committee (lanes are
    // routing labels; every transaction executes in the global block). Manifest bindings only
    // decorate canonical peers with an optional HTTP bridge URL.
    let committee = match app
        .state
        .resolve_route_authority(lane_authority_route(routing_decision))
    {
        Ok(committee) => committee,
        Err(error) => {
            iroha_logger::warn!(
                lane = routing_decision.lane_id.as_u32(),
                dataspace = routing_decision.dataspace_id.as_u64(),
                %error,
                "Torii failed closed while resolving current route authority"
            );
            return Vec::new();
        }
    };
    let authority_height = committee.authority_height();
    let authoritative_peer_ids = committee.into_validators();
    let manifest_torii_urls: BTreeMap<_, _> = app
        .state
        .manifest_lane_validator_bindings_at_height(routing_decision.lane_id, authority_height)
        .into_iter()
        .filter_map(|binding| {
            binding
                .torii_url
                .map(|torii_url| (binding.peer_id, torii_url))
        })
        .collect();
    authoritative_lane_peer_statuses_with_manifest_urls(authoritative_peer_ids, manifest_torii_urls)
}
#[cfg(all(test, feature = "connect"))]
fn authoritative_lane_peer_statuses_at_height(
    app: &AppState,
    routing_decision: RoutingDecision,
    authority_height: u64,
) -> Vec<AuthoritativeLanePeerStatus> {
    let authoritative_peer_ids = match app
        .state
        .resolve_route_authority_at_height(lane_authority_route(routing_decision), authority_height)
    {
        Ok(committee) => committee.into_validators(),
        Err(error) => {
            iroha_logger::warn!(
                lane = routing_decision.lane_id.as_u32(),
                dataspace = routing_decision.dataspace_id.as_u64(),
                authority_height,
                %error,
                "Torii failed closed while resolving height-bound route authority"
            );
            return Vec::new();
        }
    };
    let manifest_torii_urls: BTreeMap<_, _> = app
        .state
        .manifest_lane_validator_bindings_at_height(routing_decision.lane_id, authority_height)
        .into_iter()
        .filter_map(|binding| {
            binding
                .torii_url
                .map(|torii_url| (binding.peer_id, torii_url))
        })
        .collect();
    authoritative_lane_peer_statuses_with_manifest_urls(authoritative_peer_ids, manifest_torii_urls)
}
#[cfg(feature = "connect")]
fn authoritative_lane_peers(
    app: &AppState,
    routing_decision: RoutingDecision,
) -> AuthoritativeLanePeers {
    let statuses = authoritative_lane_peer_statuses(app, routing_decision);
    partition_authoritative_lane_peer_statuses(&app.online_peers, statuses)
}
#[cfg(feature = "connect")]
fn partition_authoritative_lane_peer_statuses(
    online_peers_provider: &OnlinePeersProvider,
    statuses: Vec<AuthoritativeLanePeerStatus>,
) -> AuthoritativeLanePeers {
    let authoritative_total_count = statuses.len();
    #[cfg(test)]
    let authoritative = statuses
        .iter()
        .map(|status| status.peer_id.clone())
        .collect();
    let mut online = Vec::new();
    let mut offline = Vec::new();
    online_peers_provider.with_snapshot(|online_peers| {
        for status in statuses {
            if online_peers.iter().any(|peer| peer.id() == &status.peer_id) {
                online.push(status.peer_id);
            } else {
                offline.push(status);
            }
        }
    });
    AuthoritativeLanePeers {
        #[cfg(test)]
        authoritative,
        authoritative_total_count,
        online,
        offline,
    }
}
#[cfg(feature = "connect")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ToriiProxyUnavailableReason {
    MissingAuthoritativeBinding,
    AuthoritativePeersOffline,
    LoopPreventionExhausted,
}
#[cfg(feature = "connect")]
impl ToriiProxyUnavailableReason {
    fn as_label(self) -> &'static str {
        match self {
            Self::MissingAuthoritativeBinding => "missing_authoritative_binding",
            Self::AuthoritativePeersOffline => "authoritative_peers_offline",
            Self::LoopPreventionExhausted => "loop_prevention_exhausted",
        }
    }
    fn ingress_message(self, routing_decision: RoutingDecision) -> String {
        match self {
            Self::MissingAuthoritativeBinding => format!(
                "no authoritative peer binding is registered for lane {} dataspace {}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
            Self::AuthoritativePeersOffline => format!(
                "all authoritative peers are currently unavailable for lane {} dataspace {}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
            Self::LoopPreventionExhausted => format!(
                "no authoritative peers remain after loop prevention for lane {} dataspace {}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
        }
    }
    fn forwarded_message(self, routing_decision: RoutingDecision, hop_count: u8) -> String {
        match self {
            Self::LoopPreventionExhausted => format!(
                "no authoritative proxy candidates remain for lane {} dataspace {} after {} hops",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64(),
                hop_count
            ),
            _ => self.ingress_message(routing_decision),
        }
    }
}
#[cfg(feature = "connect")]
#[derive(Clone, Debug, PartialEq, Eq)]
enum ToriiProxyCandidate {
    P2p(PeerId),
    HttpBridge { peer_id: PeerId, torii_url: String },
}
#[cfg(feature = "connect")]
impl ToriiProxyCandidate {
    fn peer_id(&self) -> &PeerId {
        match self {
            Self::P2p(peer_id) | Self::HttpBridge { peer_id, .. } => peer_id,
        }
    }
    fn transport_label(&self) -> &'static str {
        match self {
            Self::P2p(_) => "p2p_proxy",
            Self::HttpBridge { .. } => "http_bridge",
        }
    }
}
#[cfg(feature = "connect")]
#[derive(Debug)]
struct ToriiProxyCandidatePeers {
    peers: Vec<ToriiProxyCandidate>,
    authoritative_count: usize,
    authoritative_total_count: usize,
    offline_authoritative_count: usize,
    bridge_authoritative_count: usize,
    loop_prevention_drops: usize,
    unavailable_reason: Option<ToriiProxyUnavailableReason>,
}
#[cfg(feature = "connect")]
fn insert_route_unavailable_diagnostics(
    response: &mut Response,
    routing_decision: RoutingDecision,
    reason: ToriiProxyUnavailableReason,
    authoritative_total_count: usize,
    offline_authoritative_count: usize,
    loop_prevention_drops: usize,
) {
    insert_routing_headers(response, routing_decision, "proxy");
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-route-unavailable-reason"),
        HeaderValue::from_static(reason.as_label()),
    );
    insert_usize_header(
        response,
        "x-iroha-route-authoritative-total",
        authoritative_total_count,
    );
    insert_usize_header(
        response,
        "x-iroha-route-authoritative-offline",
        offline_authoritative_count,
    );
    insert_usize_header(
        response,
        "x-iroha-route-loop-prevention-drops",
        loop_prevention_drops,
    );
}
#[cfg(feature = "connect")]
fn torii_route_unavailable_response(
    routing_decision: RoutingDecision,
    reason: ToriiProxyUnavailableReason,
    message: impl Into<String>,
    authoritative_total_count: usize,
    offline_authoritative_count: usize,
    loop_prevention_drops: usize,
) -> Response {
    let mut response = torii_proxy_error_response(
        StatusCode::SERVICE_UNAVAILABLE,
        "route_unavailable",
        message,
    );
    insert_route_unavailable_diagnostics(
        &mut response,
        routing_decision,
        reason,
        authoritative_total_count,
        offline_authoritative_count,
        loop_prevention_drops,
    );
    response
}
