#[cfg(feature = "connect")]
#[derive(Debug)]
struct HostedHttpProxyCandidatePeers {
    peers: Vec<PeerId>,
    loop_prevention_drops: usize,
}
#[cfg(feature = "connect")]
fn hosted_http_proxy_candidate_peer_ids(
    app: &AppState,
    local_peer_id: &PeerId,
    authoritative_peer_ids: &[PeerId],
    visited_peer_ids: &[PeerId],
) -> HostedHttpProxyCandidatePeers {
    let exclusion_set: BTreeSet<_> = visited_peer_ids.iter().cloned().collect();
    let mut loop_prevention_drops = 0usize;
    let mut peers = app.online_peers.with_snapshot(|online_peers| {
        authoritative_peer_ids
            .iter()
            .filter(|peer_id| *peer_id != local_peer_id)
            .filter(|peer_id| online_peers.iter().any(|online| online.id() == *peer_id))
            .filter(|peer_id| {
                if exclusion_set.contains(peer_id) {
                    loop_prevention_drops = loop_prevention_drops.saturating_add(1);
                    false
                } else {
                    true
                }
            })
            .cloned()
            .collect::<Vec<_>>()
    });
    peers.sort_by_key(ToString::to_string);
    peers.dedup();
    HostedHttpProxyCandidatePeers {
        peers,
        loop_prevention_drops,
    }
}
#[cfg(feature = "connect")]
fn torii_proxy_candidate_peer_ids(
    app: &AppState,
    local_peer_id: &PeerId,
    routing_decision: RoutingDecision,
    immediate_sender_peer_id: Option<&PeerId>,
    visited_peer_ids: &[PeerId],
) -> ToriiProxyCandidatePeers {
    let mut loop_prevention_drops = 0usize;
    let exclusion_set: BTreeSet<_> = immediate_sender_peer_id
        .into_iter()
        .cloned()
        .chain(visited_peer_ids.iter().cloned())
        .collect();
    let authoritative_peers = authoritative_lane_peers(app, routing_decision);
    let authoritative_total_count = authoritative_peers.authoritative_total_count;
    let offline_authoritative_count = authoritative_peers.offline.len();
    let reachable_authoritative_count = authoritative_peers.online.len().saturating_add(
        authoritative_peers
            .offline
            .iter()
            .filter(|status| status.torii_url.is_some())
            .count(),
    );
    let mut authoritative = Vec::new();
    for peer_id in authoritative_peers.online {
        if &peer_id == local_peer_id {
            continue;
        }
        if exclusion_set.contains(&peer_id) {
            loop_prevention_drops = loop_prevention_drops.saturating_add(1);
            continue;
        }
        authoritative.push(ToriiProxyCandidate::P2p(peer_id));
    }
    let mut bridge_authoritative_count = 0usize;
    for status in authoritative_peers.offline {
        let peer_id = status.peer_id;
        if &peer_id == local_peer_id {
            continue;
        }
        if exclusion_set.contains(&peer_id) {
            loop_prevention_drops = loop_prevention_drops.saturating_add(1);
            continue;
        }
        let Some(torii_url) = status.torii_url else {
            continue;
        };
        bridge_authoritative_count = bridge_authoritative_count.saturating_add(1);
        authoritative.push(ToriiProxyCandidate::HttpBridge { peer_id, torii_url });
    }
    let authoritative_count = authoritative.len();
    let unavailable_reason = if authoritative_count > 0 {
        None
    } else if authoritative_total_count == 0 {
        Some(ToriiProxyUnavailableReason::MissingAuthoritativeBinding)
    } else if reachable_authoritative_count == 0 {
        Some(ToriiProxyUnavailableReason::AuthoritativePeersOffline)
    } else {
        Some(ToriiProxyUnavailableReason::LoopPreventionExhausted)
    };
    ToriiProxyCandidatePeers {
        peers: authoritative,
        authoritative_count,
        authoritative_total_count,
        offline_authoritative_count,
        bridge_authoritative_count,
        loop_prevention_drops,
        unavailable_reason,
    }
}
fn is_local_authoritative_for_peers(app: &AppState, authoritative_peers: &[PeerId]) -> bool {
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return false;
    };
    authoritative_peers
        .iter()
        .any(|peer_id| peer_id == local_peer_id)
}
fn is_local_authoritative_for_route(app: &AppState, routing_decision: RoutingDecision) -> bool {
    let Ok(committee) = app
        .state
        .resolve_route_authority(lane_authority_route(routing_decision))
    else {
        return false;
    };
    is_local_authoritative_for_peers(app, committee.validators())
}
fn should_execute_route_locally(app: &AppState, routing_decision: RoutingDecision) -> bool {
    is_local_authoritative_for_route(app, routing_decision)
}
#[cfg(feature = "connect")]
fn should_execute_incoming_torii_proxy_request_locally(
    app: &AppState,
    request_kind: &ToriiProxyRequestKindV1,
    routing_decision: RoutingDecision,
) -> bool {
    match request_kind {
        // Read-only requests should execute on the first ingress-selected peer. Re-running the
        // authoritative-peer selection on every receiver can create multi-hop proxy cascades when
        // lane-roster views are briefly inconsistent, which turns healthy reads into 60s+ timeouts
        // and late responses.
        ToriiProxyRequestKindV1::SignedQueryRouteScan { .. }
        | ToriiProxyRequestKindV1::SignedQueryFanout { .. }
        | ToriiProxyRequestKindV1::Read(_)
        | ToriiProxyRequestKindV1::ReadFanout(_) => true,
        ToriiProxyRequestKindV1::SubmitTransaction { .. }
        | ToriiProxyRequestKindV1::SignedQuery { .. }
        | ToriiProxyRequestKindV1::HostedHttp(_) => {
            should_execute_route_locally(app, routing_decision)
        }
    }
}
#[cfg(feature = "connect")]
fn validate_incoming_read_proxy_route(
    app: &AppState,
    routing_decision: RoutingDecision,
    request_kind: &'static str,
) -> Result<RoutingDecision, Response> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let resolved = iroha_core::queue::resolve_routing_decision(
        routing_decision,
        &nexus.lane_catalog,
        &nexus.dataspace_catalog,
    )
    .map_err(|error| {
        iroha_logger::warn!(
            request_kind,
            lane = routing_decision.lane_id.as_u32(),
            dataspace = routing_decision.dataspace_id.as_u64(),
            %error,
            "Torii proxy read route no longer resolves against receiver Nexus state"
        );
        let mut response = torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!(
                "proxied {request_kind} route lane {} dataspace {} no longer resolves against receiver Nexus state: {error}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
        );
        insert_routing_headers(&mut response, routing_decision, "proxy");
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-route-unavailable-reason"),
            HeaderValue::from_static("stale_route"),
        );
        response
    })?;
    if !torii_lane_active_for_routing(app, resolved.lane_id) {
        iroha_logger::warn!(
            request_kind,
            lane = routing_decision.lane_id.as_u32(),
            dataspace = routing_decision.dataspace_id.as_u64(),
            "Torii proxy read route is inactive at receiver authority height"
        );
        let mut response = torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!(
                "proxied {request_kind} route lane {} dataspace {} is inactive at receiver authority height",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
        );
        insert_routing_headers(&mut response, routing_decision, "proxy");
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-route-unavailable-reason"),
            HeaderValue::from_static("stale_route"),
        );
        return Err(response);
    }
    Ok(resolved)
}
#[cfg(feature = "app_api")]
fn torii_route_for_lane_id(
    app: &AppState,
    lane_id: iroha_model_base::topology::LaneId,
) -> Result<RoutingDecision, Error> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let Some(lane) = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == lane_id)
    else {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        )));
    };
    if !torii_lane_active_for_routing(app, lane_id) {
        return Err(Error::PushIntoQueue {
            source: Box::new(queue::Error::UnresolvedRoute {
                reason: format!(
                    "lane {} is inactive at the current authority height",
                    lane_id.as_u32()
                ),
            }),
            backpressure: current_torii_backpressure(app),
        });
    }
    iroha_core::queue::resolve_routing_decision(
        RoutingDecision::new(lane_id, lane.dataspace_id),
        &nexus.lane_catalog,
        &nexus.dataspace_catalog,
    )
    .map_err(|error| Error::PushIntoQueue {
        source: Box::new(error.into()),
        backpressure: current_torii_backpressure(app),
    })
}
#[cfg(feature = "app_api")]
fn torii_route_for_public_lane_id(
    app: &AppState,
    lane_id: iroha_model_base::topology::LaneId,
) -> Result<RoutingDecision, Error> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let is_public = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == lane_id)
        .is_some_and(|lane| lane.visibility == iroha_data_model::nexus::LaneVisibility::Public);
    if !is_public {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        )));
    }
    torii_route_for_lane_id(app, lane_id)
}
#[derive(Clone, Debug)]
enum ToriiAccountReadVisibility {
    Signed(AccountId),
    None,
}
impl ToriiAccountReadVisibility {
    fn caller(&self) -> Option<&AccountId> {
        match self {
            Self::Signed(account_id) => Some(account_id),
            Self::None => None,
        }
    }
    fn is_signed(&self) -> bool {
        matches!(self, Self::Signed(_))
    }

    fn into_dataspace_context(self, app: SharedAppState) -> ToriiDataspaceReadContext {
        let caller = match self {
            Self::Signed(account_id) => Some(account_id),
            Self::None => None,
        };
        let admitted_visibility = torii_dataspace_read_visibility(app.as_ref(), caller.as_ref());
        ToriiDataspaceReadContext {
            app,
            caller,
            admitted_visibility,
            #[cfg(test)]
            fixed_visibility: None,
        }
    }
}

/// Canonical caller retained by long-lived and routed dataspace reads.
///
/// The visible set is deliberately recomputed from current state instead of
/// being frozen at connection time, so permission revocation takes effect for
/// the next emitted item.
#[derive(Clone)]
pub(crate) struct ToriiDataspaceReadContext {
    app: SharedAppState,
    caller: Option<AccountId>,
    admitted_visibility: routing::DataspaceReadVisibility,
    #[cfg(test)]
    fixed_visibility: Option<routing::DataspaceReadVisibility>,
}

/// Event plus the complete authorization scope resolved before any
/// subscriber-controlled filtering or projection.
struct ScopedEvent {
    event: EventBox,
    scope: ScopedEventScope,
}

enum ScopedEventScope {
    /// Block lifecycle notices are public and carry no transaction body.
    Public,
    /// Every named dataspace must be visible to the current reader.
    Dataspaces(BTreeSet<DataSpaceId>),
    /// Missing, malformed, or intrinsically global provenance is visible only
    /// to a caller that still holds `CanReadAllLedgerData`.
    GlobalReaderOnly,
}

impl ScopedEvent {
    fn into_visible(self, visibility: &routing::DataspaceReadVisibility) -> Option<EventBox> {
        let visible = match &self.scope {
            ScopedEventScope::Public => true,
            ScopedEventScope::Dataspaces(dataspaces) => dataspaces
                .iter()
                .all(|dataspace| visibility.allows_dataspace(*dataspace)),
            ScopedEventScope::GlobalReaderOnly => visibility.can_read_all(),
        };
        visible.then_some(self.event)
    }
}

impl ToriiDataspaceReadContext {
    fn caller(&self) -> Option<&AccountId> {
        self.caller.as_ref()
    }

    fn current_visibility(&self) -> routing::DataspaceReadVisibility {
        #[cfg(test)]
        if let Some(visibility) = &self.fixed_visibility {
            return visibility.clone();
        }
        torii_dataspace_read_visibility(self.app.as_ref(), self.caller())
    }

    /// Revalidate the exact principal and route scope that admitted a
    /// long-lived stream.
    fn authorization_is_current(&self) -> bool {
        if let Some(caller) = self.caller() {
            let state_view = self.app.state.view();
            if state_view.world().accounts().get(caller).is_none() {
                return false;
            }
        }
        self.current_visibility()
            .retains_authorized_scope(&self.admitted_visibility)
    }

    #[cfg(test)]
    fn all_for_tests() -> Self {
        Self {
            app: crate::mk_app_state_for_tests(),
            caller: None,
            admitted_visibility: routing::DataspaceReadVisibility::all_for_tests(),
            fixed_visibility: Some(routing::DataspaceReadVisibility::all_for_tests()),
        }
    }

    fn filter_event(
        &self,
        kura: &Kura,
        event: EventBox,
    ) -> std::result::Result<
        Option<EventBox>,
        iroha_core::execution_attempt::ExecutionAttemptError<iroha_core::kura::Error>,
    > {
        let visibility = self.current_visibility();
        match event {
            EventBox::PipelineBatch(events) => {
                let mut visible = Vec::new();
                for event in events {
                    if let Some(EventBox::Pipeline(event)) = self
                        .scope_pipeline_event(kura, event)?
                        .into_visible(&visibility)
                    {
                        visible.push(event);
                    }
                }
                Ok((!visible.is_empty()).then_some(EventBox::PipelineBatch(visible)))
            }
            EventBox::Pipeline(event) => Ok(self
                .scope_pipeline_event(kura, event)?
                .into_visible(&visibility)),
            // Data, trigger, and clock events do not yet carry committed route
            // provenance. The explicit envelope fails them closed to a global
            // reader instead of guessing scope from payload data.
            other @ (EventBox::Data(_)
            | EventBox::Time(_)
            | EventBox::ExecuteTrigger(_)
            | EventBox::TriggerCompleted(_)) => Ok(ScopedEvent {
                event: other,
                scope: ScopedEventScope::GlobalReaderOnly,
            }
            .into_visible(&visibility)),
        }
    }

    fn filter_current_event(
        &self,
        event: EventBox,
    ) -> std::result::Result<
        Option<EventBox>,
        iroha_core::execution_attempt::ExecutionAttemptError<iroha_core::kura::Error>,
    > {
        self.filter_event(self.app.kura.as_ref(), event)
    }

    fn scope_pipeline_event(
        &self,
        kura: &Kura,
        event: PipelineEventBox,
    ) -> std::result::Result<
        ScopedEvent,
        iroha_core::execution_attempt::ExecutionAttemptError<iroha_core::kura::Error>,
    > {
        let scope = match &event {
            PipelineEventBox::Block(_) => ScopedEventScope::Public,
            PipelineEventBox::Transaction(transaction) => Self::transaction_event_scope(
                kura,
                transaction,
                &self.app.state.ivm_execution_budget(),
            )?,
            PipelineEventBox::Warning(_) | PipelineEventBox::Witness(_) => {
                ScopedEventScope::GlobalReaderOnly
            }
        };
        Ok(ScopedEvent {
            event: EventBox::Pipeline(event),
            scope,
        })
    }

    fn transaction_event_scope(
        kura: &Kura,
        transaction: &iroha_data_model::events::pipeline::TransactionEvent,
        execution_budget: &iroha_core::state::AllocationBudget,
    ) -> std::result::Result<
        ScopedEventScope,
        iroha_core::execution_attempt::ExecutionAttemptError<iroha_core::kura::Error>,
    > {
        let Some(height) = transaction.block_height() else {
            return Ok(ScopedEventScope::GlobalReaderOnly);
        };
        let Ok(height) = usize::try_from(height.get()) else {
            return Ok(ScopedEventScope::GlobalReaderOnly);
        };
        let Some(height) = NonZeroUsize::new(height) else {
            return Ok(ScopedEventScope::GlobalReaderOnly);
        };
        let Some(block) = kura.get_block(height, execution_budget)? else {
            return Ok(ScopedEventScope::GlobalReaderOnly);
        };
        let mut matched = false;
        let mut dataspaces = BTreeSet::new();
        for index in 0..block.external_entrypoint_count() {
            let Some(candidate) = block.external_signed_transaction_ref_at(index) else {
                return Ok(ScopedEventScope::GlobalReaderOnly);
            };
            if candidate.hash() != *transaction.hash() {
                continue;
            }
            matched = true;
            let Some(entrypoint_dataspaces) =
                routing::DataspaceReadVisibility::external_entrypoint_dataspaces(&block, index)
            else {
                return Ok(ScopedEventScope::GlobalReaderOnly);
            };
            dataspaces.extend(entrypoint_dataspaces);
        }
        Ok(if !matched || dataspaces.is_empty() {
            ScopedEventScope::GlobalReaderOnly
        } else {
            ScopedEventScope::Dataspaces(dataspaces)
        })
    }
}
#[cfg(feature = "app_api")]
fn torii_signed_visibility_headers_present(headers: &HeaderMap) -> bool {
    headers.get(HEADER_SIGNATURE).is_some()
        || headers.get(HEADER_TIMESTAMP_MS).is_some()
        || headers.get(HEADER_NONCE).is_some()
        || headers.get(HEADER_WITNESS).is_some()
}
#[cfg(feature = "app_api")]
fn torii_visibility_account_from_headers(
    app: &SharedAppState,
    headers: &HeaderMap,
    method: &Method,
    uri: &Uri,
    body: &[u8],
    _endpoint: &'static str,
) -> Result<ToriiAccountReadVisibility, Error> {
    let authentication_owner =
        match crate::history_producer::HistoryProducerOwner::authentication_read(&app) {
            Ok(owner) => owner,
            Err(error) => {
                return Err(error);
            }
        };

    if torii_signed_visibility_headers_present(headers) {
        let verified = crate::app_auth::verify_canonical_network_request(
            &app.state,
            app.state.network_id_ref(),
            headers,
            method,
            uri,
            body,
            None,
            authentication_owner.allocation_context(),
        )
        .map_err(|error| Error::AppUnauthorized {
            code: "canonical_authentication_invalid",
            message: error.to_string(),
        })?;
        return Ok(
            verified.map_or(ToriiAccountReadVisibility::None, |request| {
                ToriiAccountReadVisibility::Signed(request.account)
            }),
        );
    }
    if headers.get(HEADER_ACCOUNT).is_some() {
        return Err(Error::AppUnauthorized {
            code: "alias_auth_invalid",
            message: "X-Iroha-Account requires a complete canonical request signature header set"
                .to_owned(),
        });
    }
    Ok(ToriiAccountReadVisibility::None)
}

#[cfg(feature = "app_api")]
fn torii_dataspace_context_from_headers(
    app: &SharedAppState,
    headers: &HeaderMap,
    method: &Method,
    uri: &Uri,
    endpoint: &'static str,
) -> Result<ToriiDataspaceReadContext, Error> {
    torii_visibility_account_from_headers(app, headers, method, uri, &[], endpoint)
        .map(|visibility| visibility.into_dataspace_context(Arc::clone(app)))
}

#[cfg(feature = "app_api")]
fn require_torii_global_reader(
    app: &SharedAppState,
    headers: &HeaderMap,
    method: &Method,
    uri: &Uri,
    endpoint: &'static str,
) -> Result<ToriiDataspaceReadContext, Error> {
    let context = torii_dataspace_context_from_headers(app, headers, method, uri, endpoint)?;
    let Some(caller) = context.caller() else {
        return Err(Error::AppUnauthorized {
            code: "canonical_authentication_required",
            message: "canonical account request authentication is required".to_owned(),
        });
    };
    let permission: Permission = CanReadAllLedgerData.into();
    let state_view = app.state.view();
    if !torii_account_has_permission(state_view.world(), caller, &permission) {
        return Err(Error::Query(
            iroha_data_model::ValidationFail::NotPermitted(format!(
                "CanReadAllLedgerData permission is required for {endpoint}"
            )),
        ));
    }
    Ok(context)
}
fn torii_visible_account_read_routes(
    app: &AppState,
    caller: Option<&AccountId>,
) -> Vec<RoutingDecision> {
    let state_view = app.state.view();
    let world = state_view.world();
    match iroha_core::sumeragi::lanes::routing::committed_root_scope(world) {
        Some(iroha_data_model::block::consensus::SumeragiRootScope::Dataspace {
            dataspace_id,
            ..
        }) => {
            // A private root has no public account-read routes. Logical account
            // labels and UAID materialization cannot replace its revocable grant.
            let Some(caller) = caller else {
                return Vec::new();
            };
            let all: Permission = CanReadAllLedgerData.into();
            let own: Permission = CanReadRestrictedDataspace {
                dataspace: dataspace_id,
            }
            .into();
            if !torii_account_has_permission(world, caller, &all)
                && !torii_account_has_permission(world, caller, &own)
            {
                return Vec::new();
            }
            return resolve_torii_private_root_account_route(&state_view, dataspace_id)
                .ok()
                .into_iter()
                .collect();
        }
        Some(iroha_data_model::block::consensus::SumeragiRootScope::Global) => {}
        None => return Vec::new(),
    }
    let mut visible_dataspaces = torii_public_dataspace_ids(app);
    if let Some(caller) = caller
        && let Ok(account) = world.account(caller)
        && let Some(uaid) = account.value().uaid().copied()
        && let Some(bindings) = world.uaid_dataspaces().get(&uaid)
    {
        visible_dataspaces.extend(bindings.iter().map(|(dataspace_id, _)| *dataspace_id));
    }
    if let Some(caller) = caller {
        let can_read_all: Permission = CanReadAllLedgerData.into();
        if torii_account_has_permission(world, caller, &can_read_all) {
            return torii_all_dataspace_routes(app);
        }
        visible_dataspaces.extend(
            torii_all_dataspace_routes(app)
                .into_iter()
                .filter(|route| {
                    let permission: Permission = CanReadRestrictedDataspace {
                        dataspace: route.dataspace_id,
                    }
                    .into();
                    torii_account_has_permission(world, caller, &permission)
                })
                .map(|route| route.dataspace_id),
        );
    }
    torii_all_dataspace_routes(app)
        .into_iter()
        .filter(|route| visible_dataspaces.contains(&route.dataspace_id))
        .collect()
}

fn torii_dataspace_read_visibility(
    app: &AppState,
    caller: Option<&AccountId>,
) -> routing::DataspaceReadVisibility {
    let can_read_all = caller.is_some_and(|caller| {
        let permission: Permission = CanReadAllLedgerData.into();
        let state_view = app.state.view();
        torii_account_has_permission(state_view.world(), caller, &permission)
    });
    let visible_dataspaces = torii_visible_account_read_routes(app, caller)
        .into_iter()
        .map(|route| route.dataspace_id)
        .collect();
    routing::DataspaceReadVisibility::new(visible_dataspaces, can_read_all)
}
#[cfg(feature = "app_api")]
fn torii_dataspace_read_visibility_for_scope(
    app: &AppState,
    scope: &ToriiFanoutRouteScopeV1,
) -> Result<routing::DataspaceReadVisibility, Response> {
    match scope {
        ToriiFanoutRouteScopeV1::AllDataspaces => Ok(routing::DataspaceReadVisibility::new(
            torii_all_dataspace_routes(app)
                .into_iter()
                .map(|route| route.dataspace_id)
                .collect(),
            true,
        )),
        ToriiFanoutRouteScopeV1::TargetAccount {
            account_id,
            caller_account_id,
        } => {
            let account_id = parse_internal_fanout_account_id(account_id, "target")?;
            if let Some(caller_account_id) = caller_account_id {
                let caller = parse_internal_fanout_account_id(caller_account_id, "caller")?;
                return Ok(torii_dataspace_read_visibility(app, Some(&caller)));
            }
            Ok(routing::DataspaceReadVisibility::new(
                torii_target_account_routes(app, &account_id)?
                    .into_iter()
                    .map(|route| route.dataspace_id)
                    .collect(),
                false,
            ))
        }
        ToriiFanoutRouteScopeV1::VisibleAccount { caller_account_id } => {
            let caller = match caller_account_id {
                Some(account_id) => Some(parse_internal_fanout_account_id(account_id, "caller")?),
                None => None,
            };
            Ok(torii_dataspace_read_visibility(app, caller.as_ref()))
        }
    }
}
fn torii_public_dataspace_ids(app: &AppState) -> BTreeSet<DataSpaceId> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let mut dataspaces = BTreeSet::new();
    for lane in nexus.lane_catalog.lanes() {
        if lane.visibility == iroha_data_model::nexus::LaneVisibility::Public
            && torii_lane_active_for_routing(app, lane.id)
        {
            dataspaces.insert(lane.dataspace_id);
        }
    }
    dataspaces
}
#[cfg(test)]
#[cfg(feature = "app_api")]
fn torii_partition_routes_by_visibility(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    visibility: &ToriiAccountReadVisibility,
) -> (Vec<RoutingDecision>, usize) {
    let visible_dataspaces = torii_visible_account_read_routes(app.as_ref(), visibility.caller())
        .into_iter()
        .map(|route| route.dataspace_id)
        .collect::<BTreeSet<_>>();
    let mut allowed_routes = Vec::new();
    let mut denied_routes = 0usize;
    for route in routes {
        if visible_dataspaces.contains(&route.dataspace_id) {
            allowed_routes.push(route);
        } else {
            denied_routes = denied_routes.saturating_add(1);
        }
    }
    (allowed_routes, denied_routes)
}
#[cfg(feature = "app_api")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ToriiAliasLookupRouteAccess {
    route: RoutingDecision,
    filter_by_permission: bool,
}
fn torii_permission_target<T: iroha_executor_data_model::permission::Permission>(
    token: T,
) -> Result<Permission, Error> {
    // The checked writer also visits nested account identities fallibly. The
    // ordinary value conversion uses their infallible display serializer.
    let encoded = norito::json::to_json_bounded(&token, iroha_primitives::json::MAX_JSON_BYTES)
        .map_err(|error| match error {
            norito::json::BoundedJsonError::DecodeResource(_)
            | norito::json::BoundedJsonError::ScopedDecodeResource(_)
            | norito::json::BoundedJsonError::AllocationFailed => {
                Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                    iroha_data_model::query::error::QueryExecutionFail::GasBudgetExceeded,
                ))
            }
            error => Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "permission encoding failed: {error}"
            ))),
        })?;
    let value = norito::json::parse_value(&encoded).map_err(|error| match error {
        norito::json::Error::DecodeResourceLimit
        | norito::json::Error::DecodeResource(_)
        | norito::json::Error::AllocationFailed => {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::GasBudgetExceeded,
            ))
        }
        error => Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
            "permission encoding failed: {error}"
        ))),
    })?;
    let payload = iroha_primitives::json::Json::from_norito_value_ref(&value).map_err(|error| {
        if norito::core::decode_error_matches_active_limits(&error) {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::GasBudgetExceeded,
            ))
        } else {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "permission retention failed: {error}"
            )))
        }
    })?;
    Ok(Permission::new(T::name(), payload))
}
fn torii_account_has_permission(
    world: &impl WorldReadOnly,
    authority: &AccountId,
    target: &Permission,
) -> bool {
    match world.account_permissions_iter(authority) {
        Ok(permissions) => {
            if permissions
                .into_iter()
                .any(|permission| permission == target)
            {
                return true;
            }
        }
        Err(error) => {
            iroha_logger::warn!(
                authority = %authority,
                target_name = %target.name(),
                target_payload = %target.payload().get(),
                ?error,
                "Torii alias lookup permission check could not load authority permissions"
            );
        }
    }
    world.account_roles_iter(authority).any(|role_id| {
        world
            .roles()
            .get(role_id)
            .is_some_and(|role| role.permissions().any(|permission| permission == target))
    })
}
fn torii_global_signed_query_read_routes(
    app: &AppState,
    authority: &AccountId,
) -> Vec<RoutingDecision> {
    let public_dataspaces = torii_public_dataspace_ids(app);
    let state_view = app.state.view();
    let world = state_view.world();
    torii_all_dataspace_routes(app)
        .into_iter()
        .filter(|route| {
            public_dataspaces.contains(&route.dataspace_id)
                || torii_account_has_permission(
                    world,
                    authority,
                    &CanReadRestrictedDataspace {
                        dataspace: route.dataspace_id,
                    }
                    .into(),
                )
        })
        .collect()
}
fn torii_same_account_read_identity(
    app: &AppState,
    authority: &AccountId,
    target: &AccountId,
) -> bool {
    if authority == target {
        return true;
    }
    let state_view = app.state.view();
    let world = state_view.world();
    let authority_uaid = world
        .account(authority)
        .ok()
        .and_then(|account| account.value().uaid().copied());
    let target_uaid = world
        .account(target)
        .ok()
        .and_then(|account| account.value().uaid().copied());
    authority_uaid.is_some() && authority_uaid == target_uaid
}
fn torii_authority_can_resolve_account_alias(
    world: &impl WorldReadOnly,
    authority: &AccountId,
    alias: &AccountAlias,
) -> Result<bool, Error> {
    iroha_core::alias::authority_can_resolve_account_alias(world, authority, alias)
        .map_err(live_dataspace_resolution_error)
}
fn torii_authority_can_resolve_resolved_account_alias(
    world: &impl WorldReadOnly,
    authority: &AccountId,
    alias: &iroha_data_model::alias_setup::ResolvedAccountAliasV1,
) -> Result<bool, Error> {
    iroha_core::alias::authority_can_resolve_resolved_account_alias(world, authority, alias)
        .map_err(live_dataspace_resolution_error)
}
#[cfg(feature = "app_api")]
fn torii_alias_lookup_permission_probe_alias(
    app: &AppState,
    dataspace_id: DataSpaceId,
    request: &routing::AliasLookupByAccountRequestDto,
) -> Result<Option<iroha_data_model::alias_setup::ResolvedAccountAliasV1>, Error> {
    let state_view = app.state.view();
    let dataspace = match iroha_core::sns::resolve_active_dataspace_alias_by_id(
        state_view.world(),
        &state_view.nexus().dataspace_catalog,
        dataspace_id,
        routing::asset_alias_observation_time_ms(&app.state),
    ) {
        Ok(value) => value,
        Err(iroha_core::sns::SnsError::NotFound(_)) => return Ok(None),
        Err(error) => return Err(live_dataspace_resolution_error(error)),
    };
    let domain = match request
        .domain
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::parse::<Name>)
        .transpose()
    {
        Ok(value) => value,
        Err(_) => return Ok(None),
    };
    let Ok(canonical_name) = iroha_data_model::alias_setup::AccountAliasName::try_new(
        "lookup",
        domain.as_ref().map(|name| name.as_ref()),
        dataspace,
    ) else {
        return Ok(None);
    };
    Ok(Some(
        iroha_data_model::alias_setup::ResolvedAccountAliasV1::new(canonical_name, dataspace_id),
    ))
}
#[cfg(feature = "app_api")]
fn torii_exact_alias_permission_matches_route(
    permission: &Permission,
    dataspace_id: DataSpaceId,
    request: &routing::AliasLookupByAccountRequestDto,
) -> Result<bool, Error> {
    // Inspect only this typed grant; malformed or unrelated grants never authorize a route.
    if permission.name() != "CanResolveAccountAlias" {
        return Ok(false);
    }
    let permission =
        match norito::json::from_str::<CanResolveAccountAlias>(permission.payload().as_ref()) {
            Ok(value) => value,
            Err(
                norito::json::Error::DecodeResourceLimit
                | norito::json::Error::DecodeResource(_)
                | norito::json::Error::AllocationFailed,
            ) => {
                return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                    iroha_data_model::query::error::QueryExecutionFail::GasBudgetExceeded,
                )));
            }
            Err(_) => return Ok(false),
        };
    let AccountAliasPermissionScope::Alias(alias) = permission.scope else {
        return Ok(false);
    };
    Ok(alias.dataspace_id == dataspace_id
        && request.domain.as_deref().is_none_or(|domain| {
            alias
                .canonical_name
                .domain
                .as_ref()
                .is_some_and(|candidate| candidate.as_ref() == domain)
        }))
}
#[cfg(feature = "app_api")]
fn torii_alias_lookup_dataspace_allowed_by_permission(
    app: &AppState,
    dataspace_id: DataSpaceId,
    caller: Option<&AccountId>,
    request: &routing::AliasLookupByAccountRequestDto,
) -> Result<bool, Error> {
    let Some(caller) = caller else {
        return Ok(false);
    };
    let world_view = app.state.view();
    let world = world_view.world();
    if let Ok(permissions) = world.account_permissions_iter(caller) {
        for permission in permissions {
            if torii_exact_alias_permission_matches_route(permission, dataspace_id, request)? {
                return Ok(true);
            }
        }
    }
    for role_id in world.account_roles_iter(caller) {
        if let Some(role) = world.roles().get(role_id) {
            for permission in role.permissions() {
                if torii_exact_alias_permission_matches_route(permission, dataspace_id, request)? {
                    return Ok(true);
                }
            }
        }
    }
    // Drop the original view before the independent probe acquires its own immutable view.
    drop(world_view);
    let Some(alias) = torii_alias_lookup_permission_probe_alias(app, dataspace_id, request)? else {
        return Ok(false);
    };
    torii_authority_can_resolve_resolved_account_alias(app.state.view().world(), caller, &alias)
}
#[cfg(feature = "app_api")]
fn torii_partition_alias_lookup_routes(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    visibility: &ToriiAccountReadVisibility,
    request: &routing::AliasLookupByAccountRequestDto,
) -> Result<(Vec<ToriiAliasLookupRouteAccess>, usize), Error> {
    let public_dataspaces = torii_public_dataspace_ids(app.as_ref());
    let mut allowed_routes = Vec::new();
    let mut denied_routes = 0usize;
    for route in routes {
        if public_dataspaces.contains(&route.dataspace_id) {
            allowed_routes.push(ToriiAliasLookupRouteAccess {
                route,
                filter_by_permission: false,
            });
        } else if torii_alias_lookup_dataspace_allowed_by_permission(
            app.as_ref(),
            route.dataspace_id,
            visibility.caller(),
            request,
        )? {
            allowed_routes.push(ToriiAliasLookupRouteAccess {
                route,
                // A dataspace grant only opens the route. Each returned domain-qualified alias
                // still needs its exact domain grant before it may be disclosed.
                filter_by_permission: true,
            });
        } else if visibility.is_signed() {
            denied_routes = denied_routes.saturating_add(1);
        }
    }
    Ok((allowed_routes, denied_routes))
}
#[cfg(feature = "app_api")]
fn torii_partition_alias_index_routes_by_permission(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    caller: Option<&AccountId>,
    index: u64,
) -> Result<(Vec<RoutingDecision>, usize), Error> {
    let public_dataspaces = torii_public_dataspace_ids(app.as_ref());
    let mut allowed_routes = Vec::new();
    let mut denied_routes = 0usize;
    for route in routes {
        if public_dataspaces.contains(&route.dataspace_id) {
            allowed_routes.push(route);
            continue;
        }
        let Some(caller) = caller else {
            continue;
        };
        let allowed = match resolve_alias_index_on_route(app, route, index) {
            Ok(Some((alias_literal, _))) => {
                let alias = parse_exact_account_alias_label_with_live_state(app, &alias_literal)?;
                torii_authority_can_resolve_resolved_account_alias(
                    app.state.view().world(),
                    caller,
                    &alias.resolved,
                )?
            }
            Ok(None) => {
                let dataspace = {
                    let state_view = app.state.view();
                    iroha_core::sns::resolve_active_dataspace_alias_by_id(
                        state_view.world(),
                        &state_view.nexus().dataspace_catalog,
                        route.dataspace_id,
                        routing::asset_alias_observation_time_ms(&app.state),
                    )
                }
                .map_err(live_dataspace_resolution_error)?;
                let canonical_name = iroha_data_model::alias_setup::AccountAliasName::try_new(
                    "lookup",
                    Option::<&str>::None,
                    dataspace,
                )
                .expect("resolved dataspace produces a canonical probe alias");
                let resolved = iroha_data_model::alias_setup::ResolvedAccountAliasV1::new(
                    canonical_name,
                    route.dataspace_id,
                );
                torii_authority_can_resolve_resolved_account_alias(
                    app.state.view().world(),
                    caller,
                    &resolved,
                )?
            }
            Err(error) => return Err(error),
        };
        if allowed {
            allowed_routes.push(route);
        } else {
            denied_routes = denied_routes.saturating_add(1);
        }
    }
    Ok((allowed_routes, denied_routes))
}
#[cfg(feature = "app_api")]
fn torii_account_read_routes(
    app: &AppState,
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> Result<Vec<RoutingDecision>, Response> {
    if use_target_account_routes {
        torii_target_account_routes(app, target_account)
    } else {
        Ok(torii_visible_account_read_routes(app, caller))
    }
}
#[cfg(feature = "app_api")]
fn torii_should_use_target_account_routes(
    app: &AppState,
    target_account: &AccountId,
    caller: Option<&AccountId>,
) -> bool {
    caller.is_some_and(|caller| torii_same_account_read_identity(app, caller, target_account))
}
#[cfg(feature = "app_api")]
fn torii_account_assets_read_routes(
    app: &AppState,
    target_account: &AccountId,
    caller: Option<&AccountId>,
) -> Result<Vec<RoutingDecision>, Response> {
    let Some(caller) = caller else {
        return Ok(torii_visible_account_read_routes(app, None));
    };
    let target_routes = torii_target_account_routes(app, target_account)?;
    let exact_permission: Permission =
        iroha_executor_data_model::permission::query::CanReadAccountData {
            account: target_account.clone(),
        }
        .into();
    if caller == target_account
        || torii_account_has_permission(app.state.view().world(), caller, &exact_permission)
    {
        return Ok(target_routes);
    }
    let (_, denied) = torii_intersect_signed_query_routes(
        target_routes.clone(),
        torii_visible_account_read_routes(app, Some(caller)),
    );
    if denied != 0 {
        return Err(torii_signed_query_permission_denied_response(
            caller, denied,
        ));
    }
    Ok(target_routes)
}

#[cfg(feature = "app_api")]
fn torii_account_assets_route_visibility(
    app: &AppState,
    scope: &ToriiFanoutRouteScopeV1,
    path_account: &str,
    route: RoutingDecision,
) -> Result<routing::DataspaceReadVisibility, Response> {
    let path_account = parse_internal_fanout_account_id(path_account, "path target")?;
    match scope {
        ToriiFanoutRouteScopeV1::TargetAccount {
            account_id,
            caller_account_id: Some(caller_account_id),
        } => {
            let scoped_account = parse_internal_fanout_account_id(account_id, "scope target")?;
            if scoped_account != path_account {
                return Err(torii_proxy_error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_proxy_request",
                    "account-assets path and route scope must name the same exact account",
                ));
            }
            let caller = parse_internal_fanout_account_id(caller_account_id, "caller")?;
            let routes = torii_account_assets_read_routes(app, &path_account, Some(&caller))?;
            if !routes.contains(&route) {
                return Err(torii_signed_query_permission_denied_response(&caller, 1));
            }
            // One execution answers for every authorized route of the account.
            Ok(routing::DataspaceReadVisibility::exact_account(
                routes.iter().map(|route| route.dataspace_id).collect(),
                path_account,
            ))
        }
        ToriiFanoutRouteScopeV1::VisibleAccount {
            caller_account_id: None,
        } => {
            if !torii_visible_account_read_routes(app, None).contains(&route) {
                return Err(torii_proxy_error_response(
                    StatusCode::FORBIDDEN,
                    "permission_denied",
                    "account-assets route is not publicly visible",
                ));
            }
            Ok(torii_dataspace_read_visibility(app, None))
        }
        _ => Err(torii_proxy_error_response(
            StatusCode::FORBIDDEN,
            "permission_denied",
            "account-assets route requires a signed exact-target scope or public visibility",
        )),
    }
}
#[cfg(feature = "app_api")]
fn torii_account_permissions_read_routes(
    app: &AppState,
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> Result<Vec<RoutingDecision>, Response> {
    torii_account_read_routes(app, target_account, caller, use_target_account_routes)
}
#[cfg(feature = "app_api")]
fn torii_account_permissions_route_scope(
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> ToriiFanoutRouteScopeV1 {
    torii_account_read_route_scope(target_account, caller, use_target_account_routes)
}
fn torii_nexus_route(app: &AppState) -> Result<RoutingDecision, Response> {
    resolve_torii_route_for_dataspace_id(app, DataSpaceId::UNIVERSAL).map_err(|error| {
        torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!("failed to resolve Nexus fanout route: {error}"),
        )
    })
}
fn parse_internal_fanout_account_id(
    account_id: &str,
    context: &'static str,
) -> Result<AccountId, Response> {
    if account_id.trim() != account_id {
        return Err(torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            format!("invalid {context} account id: surrounding whitespace is not allowed"),
        ));
    }
    AccountId::parse_encoded(account_id).map_err(|error| {
        torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            format!("invalid {context} account id `{account_id}`: {error}"),
        )
    })
}
#[cfg(feature = "app_api")]
fn torii_fanout_scope_routes(
    app: &AppState,
    scope: &ToriiFanoutRouteScopeV1,
) -> Result<Vec<RoutingDecision>, Response> {
    match scope {
        ToriiFanoutRouteScopeV1::AllDataspaces => Ok(torii_all_dataspace_routes(app)),
        ToriiFanoutRouteScopeV1::TargetAccount { account_id, .. } => {
            let account_id = parse_internal_fanout_account_id(account_id, "target")?;
            torii_target_account_routes(app, &account_id)
        }
        ToriiFanoutRouteScopeV1::VisibleAccount { caller_account_id } => {
            let caller = match caller_account_id {
                Some(account_id) => Some(parse_internal_fanout_account_id(account_id, "caller")?),
                None => None,
            };
            Ok(torii_visible_account_read_routes(app, caller.as_ref()))
        }
    }
}
#[cfg(feature = "app_api")]
fn torii_account_read_route_scope(
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> ToriiFanoutRouteScopeV1 {
    if use_target_account_routes {
        ToriiFanoutRouteScopeV1::TargetAccount {
            account_id: target_account.to_string(),
            caller_account_id: caller.map(ToString::to_string),
        }
    } else {
        ToriiFanoutRouteScopeV1::VisibleAccount {
            caller_account_id: caller.map(ToString::to_string),
        }
    }
}
fn torii_all_dataspace_routes(app: &AppState) -> Vec<RoutingDecision> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let mut routes = BTreeMap::<
        iroha_model_base::topology::DataSpaceId,
        iroha_model_base::topology::LaneId,
    >::new();
    for lane in nexus.lane_catalog.lanes() {
        if !torii_lane_active_for_routing(app, lane.id) {
            continue;
        }
        routes
            .entry(lane.dataspace_id)
            .and_modify(|current| {
                if lane.id < *current {
                    *current = lane.id;
                }
            })
            .or_insert(lane.id);
    }
    routes
        .into_iter()
        .map(|(dataspace_id, lane_id)| RoutingDecision::new(lane_id, dataspace_id))
        .collect()
}
#[cfg(any(feature = "app_api", feature = "connect"))]
