#[cfg(feature = "app_api")]
fn asset_definition_home_dataspace_id(
    app: &AppState,
    definition_id: &AssetDefinitionId,
) -> Result<Option<DataSpaceId>, Error> {
    let (dataspace_alias, is_global) = {
        let state_view = app.state.view();
        let world = state_view.world();
        if let Some(dataspace) = routing::asset_definition_dataspace_for_read(world, definition_id)?
        {
            return Ok(Some(dataspace));
        }
        if let Some(domain) = world.asset_definition_domains().get(definition_id) {
            (Some(domain.dataspace().as_ref().to_owned()), false)
        } else {
            let Ok(definition) = world.asset_definition(definition_id) else {
                return Ok(None);
            };
            (
                definition
                    .alias()
                    .as_ref()
                    .map(|alias| alias.dataspace_segment().to_owned()),
                definition.balance_scope_policy() == AssetBalancePolicy::Global,
            )
        }
    };
    dataspace_alias
        .as_deref()
        .map(|alias| dataspace_id_for_alias_segment(app, alias))
        .transpose()
        .map(|resolved| {
            resolved
                .flatten()
                .or_else(|| is_global.then_some(DataSpaceId::UNIVERSAL))
        })
}
#[cfg(feature = "app_api")]
fn contract_alias_dataspace_id(
    app: &AppState,
    alias: &ContractAlias,
) -> Result<Option<DataSpaceId>, Error> {
    dataspace_id_for_alias_segment(app, alias.dataspace_segment())
}
#[cfg(feature = "app_api")]
fn torii_contract_target_read_route(
    app: &AppState,
    address: Option<&ContractAddress>,
    alias: Option<&ContractAlias>,
) -> Result<Option<RoutingDecision>, Error> {
    let dataspace_id = match address.and_then(|address| address.dataspace_id().ok()) {
        Some(id) => Some(id),
        None => alias
            .map(|alias| contract_alias_dataspace_id(app, alias))
            .transpose()?
            .flatten(),
    };
    dataspace_id
        .map(|id| {
            resolve_torii_route_for_dataspace_id(app, id).map_err(|error| {
                Error::AppServiceUnavailable {
                    code: "route_unavailable",
                    message: format!("failed to resolve target-contract route: {error}"),
                }
            })
        })
        .transpose()
}
