#[cfg(feature = "connect")]
struct AdmittedToriiProxySnapshot {
    snapshot: ToriiProxyHttpResponseV1,
    fanout_reservation: Option<QueryFanoutMemoryReservation>,
    ordinary_query_memory: Option<OrdinaryQueryResponseMemory>,
}
#[cfg(feature = "connect")]
fn bounded_torii_proxy_snapshot_diagnostic_body(
    diagnostic: &str,
    max_body_bytes: usize,
) -> Vec<u8> {
    let mut end = diagnostic.len().min(max_body_bytes);
    while !diagnostic.is_char_boundary(end) {
        end = end.saturating_sub(1);
    }
    let bytes = &diagnostic.as_bytes()[..end];
    let mut body = Vec::new();
    if body.try_reserve_exact(bytes.len()).is_ok() {
        body.extend_from_slice(bytes);
    }
    body
}
#[cfg(feature = "connect")]
async fn response_to_admitted_torii_proxy_snapshot(
    mut response: Response,
    max_body_bytes: usize,
) -> AdmittedToriiProxySnapshot {
    let fanout_reservation = take_query_fanout_memory_reservation(&mut response);
    let ordinary_query_memory = take_ordinary_query_memory_reservation(&mut response);
    let (parts, body) = response.into_parts();
    let headers = match bounded_torii_proxy_headers(&parts.headers) {
        Ok(headers) => headers,
        Err(error) => {
            return AdmittedToriiProxySnapshot {
                snapshot: ToriiProxyHttpResponseV1 {
                    status_code: StatusCode::BAD_GATEWAY.as_u16(),
                    headers: Vec::new(),
                    body: bounded_torii_proxy_snapshot_diagnostic_body(&error, max_body_bytes),
                },
                fanout_reservation,
                ordinary_query_memory,
            };
        }
    };
    let body = match axum::body::to_bytes(body, max_body_bytes).await {
        Ok(body) => body.to_vec(),
        Err(_error) => {
            const DIAGNOSTIC: &str =
                "proxied response body could not be collected within configured bounds";
            return AdmittedToriiProxySnapshot {
                snapshot: ToriiProxyHttpResponseV1 {
                    status_code: StatusCode::BAD_GATEWAY.as_u16(),
                    headers: Vec::new(),
                    body: bounded_torii_proxy_snapshot_diagnostic_body(DIAGNOSTIC, max_body_bytes),
                },
                fanout_reservation,
                ordinary_query_memory,
            };
        }
    };
    AdmittedToriiProxySnapshot {
        snapshot: ToriiProxyHttpResponseV1 {
            status_code: parts.status.as_u16(),
            headers,
            body,
        },
        fanout_reservation,
        ordinary_query_memory,
    }
}
#[cfg(all(test, feature = "connect"))]
async fn response_to_torii_proxy_snapshot(
    response: Response,
    max_body_bytes: usize,
) -> ToriiProxyHttpResponseV1 {
    response_to_admitted_torii_proxy_snapshot(response, max_body_bytes)
        .await
        .snapshot
}
#[cfg(feature = "connect")]
fn torii_proxy_snapshot_to_response(snapshot: ToriiProxyHttpResponseV1) -> Response {
    let status = StatusCode::from_u16(snapshot.status_code).unwrap_or(StatusCode::BAD_GATEWAY);
    let mut response = Response::builder()
        .status(status)
        .body(Body::from(snapshot.body))
        .unwrap_or_else(|_| {
            Response::builder()
                .status(StatusCode::BAD_GATEWAY)
                .body(Body::from("failed to build proxied response"))
                .expect("build fallback proxied response")
        });
    for header in snapshot.headers {
        let Ok(name) = HeaderName::from_bytes(header.name.as_bytes()) else {
            continue;
        };
        let Ok(value) = HeaderValue::from_bytes(&header.value) else {
            continue;
        };
        response.headers_mut().append(name, value);
    }
    response
}
#[cfg(all(test, feature = "connect"))]
fn admitted_torii_proxy_snapshot_to_response(admitted: AdmittedToriiProxySnapshot) -> Response {
    let mut response = torii_proxy_snapshot_to_response(admitted.snapshot);
    if let Some(reservation) = admitted.fanout_reservation {
        response = hold_query_fanout_memory_reservation_in_response_body(response, reservation);
    }
    if let Some(reservation) = admitted.ordinary_query_memory {
        response = hold_ordinary_query_memory_in_response_body(response, reservation);
    }
    response
}
fn header_map_to_torii_proxy_headers(
    headers: &HeaderMap,
) -> Vec<iroha_core::torii_proxy::ToriiProxyHeaderV1> {
    headers
        .iter()
        .map(
            |(name, value)| iroha_core::torii_proxy::ToriiProxyHeaderV1 {
                name: name.as_str().to_owned(),
                value: value.as_bytes().to_vec(),
            },
        )
        .collect()
}
#[cfg(feature = "app_api")]
fn soracloud_public_runtime_headers_to_torii_proxy_headers(
    headers: &HeaderMap,
) -> Result<Vec<iroha_core::torii_proxy::ToriiProxyHeaderV1>, SoracloudRuntimeExecutionError> {
    let headers = sanitize_soracloud_public_runtime_headers(headers)?;
    Ok(header_map_to_torii_proxy_headers(&headers))
}
fn torii_proxy_headers_to_header_map(
    headers: &[iroha_core::torii_proxy::ToriiProxyHeaderV1],
) -> HeaderMap {
    let mut header_map = HeaderMap::new();
    for header in headers {
        let Ok(name) = HeaderName::from_bytes(header.name.as_bytes()) else {
            continue;
        };
        let Ok(value) = HeaderValue::from_bytes(&header.value) else {
            continue;
        };
        header_map.append(name, value);
    }
    header_map
}
#[cfg(feature = "connect")]
fn should_retry_torii_proxy_status(status: StatusCode) -> bool {
    matches!(
        status,
        StatusCode::SERVICE_UNAVAILABLE | StatusCode::BAD_GATEWAY | StatusCode::GATEWAY_TIMEOUT
    )
}
#[cfg(feature = "connect")]
fn should_retry_generic_torii_proxy_snapshot(snapshot: &ToriiProxyHttpResponseV1) -> bool {
    let status = StatusCode::from_u16(snapshot.status_code).unwrap_or(StatusCode::BAD_GATEWAY);
    if should_retry_torii_proxy_status(status) {
        return true;
    }
    torii_proxy_has_exact_capacity_rejection(snapshot)
}
/// Exact candidate-local memory pressure, shared by ordinary and strict admission retries.
#[cfg(feature = "connect")]
fn torii_proxy_has_exact_capacity_rejection(snapshot: &ToriiProxyHttpResponseV1) -> bool {
    if snapshot.status_code != StatusCode::TOO_MANY_REQUESTS.as_u16() {
        return false;
    }

    // An authority can be temporarily unable to allocate the single bounded
    // proxy-response slot even though another route authority is healthy. Only
    // that exact structured rejection is safe to treat as candidate-local;
    // ordinary 429 responses remain definitive client-visible rate limits.
    let mut reject_codes = snapshot
        .headers
        .iter()
        .filter(|header| header.name.eq_ignore_ascii_case("x-iroha-reject-code"));
    let Some(reject_code) = reject_codes.next() else {
        return false;
    };
    reject_codes.next().is_none() && reject_code.value.as_slice() == b"proxy_capacity_exceeded"
}
#[cfg(feature = "connect")]
#[derive(Clone, Debug, PartialEq, Eq)]
enum ToriiProxyAttemptError {
    /// The request failed before any bytes could have reached the authority.
    DefinitelyNotDispatched(String),
    /// Dispatch began, but no complete authenticated response was recovered.
    DispatchedWithoutResponse(String),
}
#[cfg(feature = "connect")]
impl ToriiProxyAttemptError {
    fn before_dispatch(reason: impl Into<String>) -> Self {
        Self::DefinitelyNotDispatched(reason.into())
    }
    fn after_dispatch(reason: impl Into<String>) -> Self {
        Self::DispatchedWithoutResponse(reason.into())
    }
    fn may_have_reached_authority(&self) -> bool {
        matches!(self, Self::DispatchedWithoutResponse(_))
    }
}
#[cfg(feature = "connect")]
impl std::fmt::Display for ToriiProxyAttemptError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::DefinitelyNotDispatched(reason) => {
                write!(formatter, "request was not dispatched: {reason}")
            }
            Self::DispatchedWithoutResponse(reason) => {
                write!(formatter, "request dispatch outcome is unknown: {reason}")
            }
        }
    }
}
#[cfg(feature = "connect")]
fn torii_proxy_request_kind_name(request: &ToriiProxyRequestKindV1) -> &'static str {
    match request {
        ToriiProxyRequestKindV1::SubmitTransaction { .. } => "submit_transaction",
        ToriiProxyRequestKindV1::SignedQuery { .. } => "signed_query",
        ToriiProxyRequestKindV1::SignedQueryRouteScan { .. } => "signed_query_route_scan",
        ToriiProxyRequestKindV1::SignedQueryFanout { .. } => "signed_query_fanout",
        ToriiProxyRequestKindV1::Read(_) => "read",
        ToriiProxyRequestKindV1::ReadFanout(_) => "read_fanout",
        ToriiProxyRequestKindV1::HostedHttp(_) => "hosted_http",
    }
}
#[cfg(feature = "connect")]
fn torii_proxy_request_carries_one_shot_signed_query(request: &ToriiProxyRequestKindV1) -> bool {
    matches!(
        request,
        ToriiProxyRequestKindV1::SignedQuery { .. }
            | ToriiProxyRequestKindV1::SignedQueryRouteScan { .. }
            | ToriiProxyRequestKindV1::SignedQueryFanout { .. }
    )
}
#[cfg(feature = "connect")]
fn torii_proxy_attempt_timeout(request: &ToriiProxyRequestKindV1) -> Duration {
    match request {
        ToriiProxyRequestKindV1::SubmitTransaction { .. } => DEFAULT_ROUTE_TIMEOUT,
        ToriiProxyRequestKindV1::SignedQuery { .. }
        | ToriiProxyRequestKindV1::SignedQueryRouteScan { .. }
        | ToriiProxyRequestKindV1::Read(_)
        | ToriiProxyRequestKindV1::HostedHttp(_) => DEFAULT_ROUTE_TIMEOUT,
        ToriiProxyRequestKindV1::SignedQueryFanout { .. }
        | ToriiProxyRequestKindV1::ReadFanout(_) => DEFAULT_ROUTE_TIMEOUT + Duration::from_secs(5),
    }
}
#[cfg(feature = "connect")]
fn torii_proxy_p2p_response_body_limit(
    app: &AppState,
    network: &iroha_core::IrohaNetwork,
    request: &ToriiProxyRequestKindV1,
) -> usize {
    // Control's configured plaintext cap is authoritative. Keep generated
    // responses below that exact source boundary; larger application envelopes
    // are available only through local or configured HTTP-bridge transport.
    let application_limit = torii_proxy_response_body_limit(app, request);
    let carrier_overhead = TORII_PROXY_NETWORK_MESSAGE_OVERHEAD_BYTES_V1
        .checked_add(TORII_PROXY_REQUEST_RELAY_OVERHEAD_BYTES_V1)
        .expect("fixed Torii proxy carrier overhead fits usize");
    let transport_limit = network
        .topic_plaintext_frame_cap(iroha_p2p::network::message::Topic::Control)
        .saturating_sub(carrier_overhead)
        .max(1);
    application_limit.min(transport_limit).max(1)
}
#[cfg(feature = "connect")]
async fn post_torii_proxy_control_until_deadline(
    network: &iroha_core::IrohaNetwork,
    mut post: iroha_p2p::Post<iroha_core::NetworkMessage>,
    deadline_unix_ms: u64,
    local_deadline: tokio::time::Instant,
) -> Result<(), String> {
    const RETRY_INTERVAL: Duration = Duration::from_millis(5);
    loop {
        let absolute_remaining =
            validate_torii_proxy_deadline(deadline_unix_ms).map_err(str::to_owned)?;
        let local_remaining = local_deadline.saturating_duration_since(tokio::time::Instant::now());
        let remaining = absolute_remaining.min(local_remaining);
        if remaining.is_zero() {
            return Err("Torii proxy local admission deadline has expired".to_owned());
        }
        match network.post_best_effort_recoverable(post) {
            Ok(()) => return Ok(()),
            Err(iroha_p2p::network::NetworkPostAdmissionError::Backpressured { message }) => {
                post = message;
                tokio::time::sleep(RETRY_INTERVAL.min(remaining)).await;
            }
            Err(iroha_p2p::network::NetworkPostAdmissionError::Closed { message: _ }) => {
                return Err("Torii proxy P2P actor is closed".to_owned());
            }
            Err(iroha_p2p::network::NetworkPostAdmissionError::Rejected { message: _, reason }) => {
                return Err(format!(
                    "Torii proxy P2P actor rejected exact control admission: {reason:?}"
                ));
            }
        }
    }
}
#[cfg(feature = "connect")]
fn torii_proxy_bridge_request_url(torii_url: &str) -> Result<reqwest::Url, String> {
    let base = reqwest::Url::parse(torii_url)
        .map_err(|error| format!("invalid authoritative Torii URL `{torii_url}`: {error}"))?;
    base.join(TORII_INTERNAL_PROXY_HTTP_PATH)
        .map_err(|error| {
            format!(
                "failed to resolve internal proxy path for authoritative Torii URL `{torii_url}`: {error}"
            )
        })
}
#[cfg(feature = "connect")]
async fn reqwest_response_to_torii_proxy_snapshot(
    mut response: reqwest::Response,
    max_body_bytes: usize,
) -> Result<ToriiProxyHttpResponseV1, String> {
    let headers = bounded_torii_proxy_headers(response.headers())?;
    let status_code = response.status().as_u16();
    let body = read_reqwest_response_body_bounded(
        &mut response,
        max_body_bytes,
        "authoritative HTTP bridge",
    )
    .await
    .map_err(|error| error.to_string())?;
    Ok(ToriiProxyHttpResponseV1 {
        status_code,
        headers,
        body,
    })
}
#[cfg(feature = "connect")]
async fn execute_torii_proxy_request_via_peer(
    app: &SharedAppState,
    target_peer_id: PeerId,
    request: Arc<ToriiProxyRequestV1>,
) -> Result<ToriiProxyHttpResponseV1, ToriiProxyAttemptError> {
    let Some(network) = app.p2p.as_ref() else {
        return Err(ToriiProxyAttemptError::before_dispatch(
            "Torii ingress routing requires an attached P2P network",
        ));
    };
    let remaining_budget = validate_torii_proxy_deadline(request.deadline_unix_ms)
        .map_err(ToriiProxyAttemptError::before_dispatch)?;
    let request_id = request.request_id.clone();
    let pending_key = (request_id, target_peer_id.clone());
    let request_kind_name = torii_proxy_request_kind_name(&request.request);
    let attempt_timeout_cap = torii_proxy_attempt_timeout(&request.request)
        .min(remaining_budget)
        .min(TORII_PROXY_EXECUTION_BUDGET);
    let attempt_deadline = tokio::time::Instant::now() + attempt_timeout_cap;
    let max_body_bytes =
        torii_proxy_p2p_response_body_limit(app.as_ref(), network, &request.request);

    let (tx, rx) = tokio::sync::oneshot::channel();
    prune_completed_torii_proxy_requests(app).await;
    let _waiter = register_torii_proxy_pending_waiter(app, pending_key.clone(), tx, max_body_bytes);
    iroha_logger::debug!(
        request_id = %pending_key.0,
        peer_id = %target_peer_id,
        hop_count = request.hop_count,
        max_hops = request.max_hops,
        visited_peer_count = request.visited_peer_ids.len(),
        request_kind = request_kind_name,
        attempt_timeout_cap_ms = attempt_timeout_cap.as_millis() as u64,
        "sending Torii proxy request to peer"
    );
    let deadline_unix_ms = request.deadline_unix_ms;
    // Exact actor admission below applies the live Control-source cap. An
    // oversized request is returned as pre-dispatch failure so the candidate
    // pipeline can use an HTTP bridge; it is never silently actor-dropped.
    let admission = post_torii_proxy_control_until_deadline(
        network,
        iroha_p2p::Post {
            peer_id: target_peer_id.clone(),
            priority: iroha_p2p::Priority::High,
            data: iroha_core::NetworkMessage::ToriiProxyRequest(request),
        },
        deadline_unix_ms,
        attempt_deadline,
    )
    .await;
    if let Err(error) = admission {
        return Err(ToriiProxyAttemptError::before_dispatch(format!(
            "Torii proxy request `{}` to peer `{target_peer_id}` was not admitted by P2P: {error}",
            pending_key.0
        )));
    }
    let remaining_budget = match validate_torii_proxy_deadline(deadline_unix_ms) {
        Ok(remaining) => remaining,
        Err(error) => {
            return Err(ToriiProxyAttemptError::after_dispatch(format!(
                "Torii proxy request `{}` to peer `{target_peer_id}` was admitted but exhausted its deadline before response wait: {error}",
                pending_key.0
            )));
        }
    };
    let local_remaining = attempt_deadline.saturating_duration_since(tokio::time::Instant::now());
    let attempt_timeout = remaining_budget.min(local_remaining);
    if attempt_timeout.is_zero() {
        return Err(ToriiProxyAttemptError::after_dispatch(format!(
            "Torii proxy request `{}` to peer `{target_peer_id}` was admitted at its local attempt deadline",
            pending_key.0
        )));
    }
    match tokio::time::timeout(attempt_timeout, rx).await {
        Ok(Ok(response)) => {
            validate_torii_proxy_snapshot_bounds(&response, max_body_bytes).map_err(|error| {
                ToriiProxyAttemptError::after_dispatch(format!(
                    "Torii proxy response for request `{}` from peer `{target_peer_id}` violates response bounds: {error}",
                    pending_key.0
                ))
            })?;
            Ok(response)
        }
        Ok(Err(_)) => Err(ToriiProxyAttemptError::after_dispatch(format!(
            "Torii proxy request `{}` to peer `{target_peer_id}` closed before returning a response",
            pending_key.0
        ))),
        Err(_) => {
            iroha_logger::warn!(
                request_id = %pending_key.0,
                peer_id = %target_peer_id,
                request_kind = request_kind_name,
                attempt_timeout_ms = attempt_timeout.as_millis() as u64,
                "Torii proxy request timed out before any authoritative response"
            );
            Err(ToriiProxyAttemptError::after_dispatch(format!(
                "Torii proxy request `{}` to peer `{target_peer_id}` timed out after {:?} kind={request_kind_name}",
                pending_key.0, attempt_timeout,
            )))
        }
    }
}

#[cfg(feature = "connect")]
async fn execute_torii_proxy_request_via_http_bridge_shared(
    app: &SharedAppState,
    target_peer_id: PeerId,
    torii_url: String,
    request: SharedToriiProxyAttemptRequest,
) -> Result<ToriiProxyHttpResponseV1, ToriiProxyAttemptError> {
    let remaining_budget = validate_torii_proxy_deadline(request.deadline_unix_ms)
        .map_err(ToriiProxyAttemptError::before_dispatch)?;
    let request_kind_name = torii_proxy_request_kind_name(&request.request);
    let attempt_timeout_cap = torii_proxy_attempt_timeout(&request.request)
        .min(remaining_budget)
        .min(TORII_PROXY_EXECUTION_BUDGET);
    let attempt_deadline = tokio::time::Instant::now() + attempt_timeout_cap;
    let response_body_limit = torii_proxy_response_body_limit(app.as_ref(), &request.request);
    let body = request.encoded.clone();
    let uri = TORII_INTERNAL_PROXY_HTTP_PATH
        .parse::<crate::Uri>()
        .expect("internal Torii proxy path must be a valid URI");
    let mut headers = operator_signatures::signed_torii_proxy_request_headers(
        &app.torii_proxy_bridge_signer,
        app.state.network_id_ref(),
        &target_peer_id,
        &crate::Method::POST,
        &uri,
        &body,
    )
    .map_err(|error| {
        ToriiProxyAttemptError::before_dispatch(format!(
            "failed to sign Torii proxy request `{}` for authoritative HTTP bridge to peer `{target_peer_id}`: {error}",
            request.request_id
        ))
    })?;
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/x-norito"),
    );
    headers.insert(
        axum::http::header::ACCEPT,
        HeaderValue::from_static("application/x-norito"),
    );
    headers.insert(
        axum::http::header::ACCEPT_ENCODING,
        HeaderValue::from_static("identity"),
    );
    let request_url = torii_proxy_bridge_request_url(&torii_url)
        .map_err(ToriiProxyAttemptError::before_dispatch)?;
    iroha_logger::debug!(
        request_id = %request.request_id,
        peer_id = %target_peer_id,
        torii_url = %request_url,
        hop_count = request.hop_count,
        max_hops = request.max_hops,
        visited_peer_count = request.visited_peer_ids.len(),
        request_kind = request_kind_name,
        attempt_timeout_cap_ms = attempt_timeout_cap.as_millis() as u64,
        "sending Torii proxy request over authoritative HTTP bridge"
    );

    let client = reqwest::Client::builder()
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| {
            ToriiProxyAttemptError::before_dispatch(format!(
                "failed to build Torii proxy HTTP client for request `{}` to peer `{target_peer_id}`: {error}",
                request.request_id
            ))
        })?;
    let absolute_remaining = validate_torii_proxy_deadline(request.deadline_unix_ms)
        .map_err(ToriiProxyAttemptError::before_dispatch)?;
    let local_remaining = attempt_deadline.saturating_duration_since(tokio::time::Instant::now());
    let attempt_timeout = absolute_remaining.min(local_remaining);
    if attempt_timeout.is_zero() {
        return Err(ToriiProxyAttemptError::before_dispatch(format!(
            "Torii proxy request `{}` exhausted its local HTTP attempt deadline before dispatch",
            request.request_id
        )));
    }
    let response = client
        .post(request_url.clone())
        .headers(headers)
        .body(body)
        .timeout(attempt_timeout)
        .send()
        .await
        .map_err(|error| {
            let definitely_not_dispatched = error.is_connect();
            let reason = format!(
                "Torii proxy request `{}` to peer `{target_peer_id}` via authoritative HTTP bridge `{request_url}` failed: {error}",
                request.request_id
            );
            if definitely_not_dispatched {
                ToriiProxyAttemptError::before_dispatch(reason)
            } else {
                ToriiProxyAttemptError::after_dispatch(reason)
            }
        })?;
    let absolute_remaining = validate_torii_proxy_deadline(request.deadline_unix_ms)
        .map_err(ToriiProxyAttemptError::after_dispatch)?;
    let local_remaining = attempt_deadline.saturating_duration_since(tokio::time::Instant::now());
    let response_timeout = absolute_remaining.min(local_remaining);
    if response_timeout.is_zero() {
        return Err(ToriiProxyAttemptError::after_dispatch(format!(
            "Torii proxy request `{}` exhausted its local HTTP response deadline",
            request.request_id
        )));
    }
    tokio::time::timeout(
        response_timeout,
        reqwest_response_to_torii_proxy_snapshot(response, response_body_limit),
    )
    .await
    .map_err(|_| {
        ToriiProxyAttemptError::after_dispatch(format!(
            "Torii proxy request `{}` timed out while reading its HTTP response body",
            request.request_id
        ))
    })?
    .map_err(ToriiProxyAttemptError::after_dispatch)
}
#[cfg(test)]
#[cfg(feature = "connect")]
async fn execute_torii_proxy_request_locally(
    app: &SharedAppState,
    local_peer_id: PeerId,
    request: ToriiProxyRequestV1,
) -> Result<AdmittedToriiProxySnapshot, ToriiProxyAttemptError> {
    execute_torii_proxy_request_locally_with_proxy_memory(app, local_peer_id, request, None).await
}
#[cfg(all(test, feature = "connect"))]
async fn execute_torii_proxy_request_locally_with_proxy_memory(
    app: &SharedAppState,
    local_peer_id: PeerId,
    request: ToriiProxyRequestV1,
    proxy_memory: Option<ToriiProxyMemoryReservation>,
) -> Result<AdmittedToriiProxySnapshot, ToriiProxyAttemptError> {
    let max_body_bytes = torii_proxy_response_body_limit(app.as_ref(), &request.request);

    // Local delivery may execute a Nexus fanout whose remote legs re-enter the
    // ordinary proxy candidate pipeline. Hop history and candidate filtering
    // bound that recursion at runtime; erase this one recursive future edge so
    // the compiler does not need to construct an infinitely sized future.
    let response = Box::pin(execute_incoming_torii_proxy_request_with_proxy_memory(
        app,
        request,
        Some(local_peer_id.clone()),
        proxy_memory,
    ))
    .await;
    let snapshot = response_to_admitted_torii_proxy_snapshot(response, max_body_bytes).await;
    Ok(snapshot)
}
#[cfg(feature = "connect")]
async fn execute_torii_proxy_request_with_fallback(
    app: &SharedAppState,
    routing_decision: RoutingDecision,
    request: ToriiProxyRequestKindV1,
) -> Response {
    execute_torii_proxy_request_with_fallback_admitted(app, routing_decision, request, None).await
}
#[cfg(feature = "connect")]
async fn execute_torii_proxy_request_with_fallback_admitted(
    app: &SharedAppState,
    routing_decision: RoutingDecision,
    request: ToriiProxyRequestKindV1,
    pre_admitted_proxy_memory: Option<ToriiProxyMemoryReservation>,
) -> Response {
    let request_started = Instant::now();
    let request = match new_torii_proxy_request(app.as_ref(), request) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let local_peer_id = app
        .local_peer_id
        .as_ref()
        .expect("new_torii_proxy_request validated local peer id");
    let candidates = torii_proxy_candidate_peer_ids(
        app,
        local_peer_id,
        routing_decision,
        None,
        &request.visited_peer_ids,
    );
    iroha_logger::debug!(
        request_id = %request.request_id,
        hop_count = request.hop_count,
        max_hops = request.max_hops,
        lane = routing_decision.lane_id.as_u32(),
        dataspace = routing_decision.dataspace_id.as_u64(),
        proxy_candidate_count = candidates.peers.len(),
        authoritative_candidate_count = candidates.authoritative_count,
        authoritative_total_count = candidates.authoritative_total_count,
        offline_authoritative_count = candidates.offline_authoritative_count,
        bridge_authoritative_count = candidates.bridge_authoritative_count,
        loop_prevention_drops = candidates.loop_prevention_drops,
        "Torii ingress proxy prepared candidate peers"
    );
    if candidates.peers.is_empty() {
        let reason = candidates
            .unavailable_reason
            .unwrap_or(ToriiProxyUnavailableReason::MissingAuthoritativeBinding);
        return torii_route_unavailable_response(
            routing_decision,
            reason,
            reason.ingress_message(routing_decision),
            candidates.authoritative_total_count,
            candidates.offline_authoritative_count,
            candidates.loop_prevention_drops,
        );
    }
    let proxy_memory = match pre_admitted_proxy_memory {
        Some(reservation) => reservation,
        None => match acquire_torii_proxy_memory(app) {
            Ok(reservation) => reservation,
            Err(response) => return response,
        },
    };
    let response = execute_torii_proxy_request_across_candidates(
        tokio::time::Instant::from_std(request_started),
        candidates.peers,
        routing_decision,
        request,
        app.torii_proxy_http_ingress_envelope
            .forwarding_transient_bytes,
        |candidate, request| async move {
            match candidate {
                ToriiProxyCandidate::P2p(peer_id) => {
                    execute_torii_proxy_request_via_peer(app, peer_id, request.into_arc()).await
                }
                ToriiProxyCandidate::HttpBridge { peer_id, torii_url } => {
                    execute_torii_proxy_request_via_http_bridge_shared(
                        app, peer_id, torii_url, request,
                    )
                    .await
                }
            }
        },
        |request_id| async move {
            mark_torii_proxy_request_completed(app, request_id).await;
        },
    )
    .await;
    proxy_response_finalization::complete(response, proxy_memory, |response| {
        std::future::ready(response)
    })
    .await
}

#[cfg(all(feature = "app_api", not(feature = "connect")))]
async fn execute_torii_proxy_request_with_fallback(
    _app: &SharedAppState,
    routing_decision: RoutingDecision,
    _request: ToriiProxyRequestKindV1,
) -> Response {
    torii_proxy_error_response(
        StatusCode::SERVICE_UNAVAILABLE,
        "route_unavailable",
        format!(
            "Torii ingress routing for lane {} dataspace {} requires P2P support",
            routing_decision.lane_id.as_u32(),
            routing_decision.dataspace_id.as_u64(),
        ),
    )
}
#[cfg(feature = "connect")]
async fn forward_incoming_torii_proxy_request(
    app: &SharedAppState,
    immediate_sender_peer_id: &PeerId,
    routing_decision: RoutingDecision,
    request: ToriiProxyRequestV1,
) -> Response {
    let request_started = tokio::time::Instant::now();
    if request.hop_count >= request.max_hops {
        iroha_logger::warn!(
            request_id = %request.request_id,
            hop_count = request.hop_count,
            max_hops = request.max_hops,
            lane = routing_decision.lane_id.as_u32(),
            dataspace = routing_decision.dataspace_id.as_u64(),
            "Torii proxy request exhausted hop budget before reaching an authoritative peer"
        );
        return torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!(
                "Torii proxy exhausted {} hops for lane {} dataspace {}",
                request.max_hops,
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
        );
    }
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            "Torii ingress routing requires a configured local peer id",
        );
    };
    if request
        .visited_peer_ids
        .iter()
        .any(|visited_peer_id| visited_peer_id == local_peer_id)
    {
        return torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            "Torii proxy request attempted to revisit a peer in its authenticated hop history",
        );
    }
    let forwarded_request = forwarded_torii_proxy_request_owned(request, local_peer_id);
    let candidates = torii_proxy_candidate_peer_ids(
        app,
        local_peer_id,
        routing_decision,
        Some(immediate_sender_peer_id),
        &forwarded_request.visited_peer_ids,
    );
    iroha_logger::debug!(
        request_id = %forwarded_request.request_id,
        hop_count = forwarded_request.hop_count,
        max_hops = forwarded_request.max_hops,
        lane = routing_decision.lane_id.as_u32(),
        dataspace = routing_decision.dataspace_id.as_u64(),
        proxy_candidate_count = candidates.peers.len(),
        authoritative_candidate_count = candidates.authoritative_count,
        authoritative_total_count = candidates.authoritative_total_count,
        offline_authoritative_count = candidates.offline_authoritative_count,
        bridge_authoritative_count = candidates.bridge_authoritative_count,
        loop_prevention_drops = candidates.loop_prevention_drops,
        "Torii proxy receiver prepared re-forward candidates"
    );
    if candidates.peers.is_empty() {
        let reason = candidates
            .unavailable_reason
            .unwrap_or(ToriiProxyUnavailableReason::MissingAuthoritativeBinding);
        let message = reason.forwarded_message(routing_decision, forwarded_request.hop_count);
        iroha_logger::warn!(
            request_id = %forwarded_request.request_id,
            hop_count = forwarded_request.hop_count,
            max_hops = forwarded_request.max_hops,
            lane = routing_decision.lane_id.as_u32(),
            dataspace = routing_decision.dataspace_id.as_u64(),
            authoritative_total_count = candidates.authoritative_total_count,
            offline_authoritative_count = candidates.offline_authoritative_count,
            loop_prevention_drops = candidates.loop_prevention_drops,
            "Torii proxy receiver ran out of re-forward candidates"
        );
        return torii_route_unavailable_response(
            routing_decision,
            reason,
            message,
            candidates.authoritative_total_count,
            candidates.offline_authoritative_count,
            candidates.loop_prevention_drops,
        );
    }
    execute_torii_proxy_request_across_candidates(
        request_started,
        candidates.peers,
        routing_decision,
        forwarded_request,
        app.torii_proxy_http_ingress_envelope
            .forwarding_transient_bytes,
        |candidate, request| async move {
            match candidate {
                ToriiProxyCandidate::P2p(peer_id) => {
                    execute_torii_proxy_request_via_peer(app, peer_id, request.into_arc()).await
                }
                ToriiProxyCandidate::HttpBridge { peer_id, torii_url } => {
                    execute_torii_proxy_request_via_http_bridge_shared(
                        app, peer_id, torii_url, request,
                    )
                    .await
                }
            }
        },
        |request_id| async move {
            mark_torii_proxy_request_completed(app, request_id).await;
        },
    )
    .await
}

#[cfg(feature = "connect")]
#[derive(Clone)]
struct SharedToriiProxyAttemptRequest {
    inner: Arc<ToriiProxyRequestV1>,
    encoded: Bytes,
}
#[cfg(feature = "connect")]
impl SharedToriiProxyAttemptRequest {
    fn new(request: ToriiProxyRequestV1, max_encoded_bytes: usize) -> Result<Self, String> {
        validate_torii_proxy_deadline(request.deadline_unix_ms).map_err(str::to_owned)?;
        let encoded = norito::core::to_bytes_bounded(&request, max_encoded_bytes)
            .map(Bytes::from)
            .map_err(|error| format!("failed to encode bounded Torii proxy attempt: {error}"))?;
        Ok(Self {
            inner: Arc::new(request),
            encoded,
        })
    }
    fn into_arc(self) -> Arc<ToriiProxyRequestV1> {
        self.inner
    }
}
#[cfg(feature = "connect")]
impl core::ops::Deref for SharedToriiProxyAttemptRequest {
    type Target = ToriiProxyRequestV1;
    fn deref(&self) -> &Self::Target {
        self.inner.as_ref()
    }
}
#[cfg(feature = "connect")]
async fn execute_torii_proxy_request_across_candidates<F, Fut, C, CFut>(
    execution_started: tokio::time::Instant,
    candidate_peers: Vec<ToriiProxyCandidate>,
    routing_decision: RoutingDecision,
    request: ToriiProxyRequestV1,
    max_encoded_request_bytes: usize,
    mut execute: F,
    complete_request: C,
) -> Response
where
    F: FnMut(ToriiProxyCandidate, SharedToriiProxyAttemptRequest) -> Fut,
    Fut: core::future::Future<Output = Result<ToriiProxyHttpResponseV1, ToriiProxyAttemptError>>,
    C: Fn(Hash) -> CFut,
    CFut: core::future::Future<Output = ()>,
{
    let request_id = request.request_id.clone();
    if let Err(error) = validate_torii_proxy_deadline(request.deadline_unix_ms) {
        return torii_proxy_error_response(
            StatusCode::REQUEST_TIMEOUT,
            "proxy_deadline_exceeded",
            error,
        );
    }
    let execution_deadline = execution_started + TORII_PROXY_EXECUTION_BUDGET;
    let request = match SharedToriiProxyAttemptRequest::new(request, max_encoded_request_bytes) {
        Ok(request) => request,
        Err(error) => {
            return torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "proxy_capacity_exceeded",
                error,
            );
        }
    };
    if torii_proxy_request_carries_one_shot_signed_query(&request.request) {
        let mut last_pre_dispatch_error = None;
        for candidate in candidate_peers {
            if tokio::time::Instant::now() >= execution_deadline {
                break;
            }
            let peer_id = candidate.peer_id().clone();
            let transport = candidate.transport_label();
            match execute(candidate, request.clone()).await {
                Ok(snapshot) => {
                    // A complete response, including an explicit rejection, proves that this
                    // exact nonce-bearing request reached an authority. Return it verbatim:
                    // retrying the body would violate one-shot admission semantics.
                    let mut response = torii_proxy_snapshot_to_response(snapshot);
                    insert_route_transport_header(&mut response, transport);
                    complete_request(request_id).await;
                    return response;
                }
                Err(ToriiProxyAttemptError::DefinitelyNotDispatched(reason)) => {
                    iroha_logger::warn!(
                        peer_id = %peer_id,
                        transport,
                        reason,
                        "signed-query proxy attempt failed before dispatch; trying the next authority"
                    );
                    last_pre_dispatch_error = Some(reason);
                }
                Err(ToriiProxyAttemptError::DispatchedWithoutResponse(reason)) => {
                    iroha_logger::warn!(
                        peer_id = %peer_id,
                        transport,
                        reason,
                        "signed-query proxy dispatch outcome is unknown; refusing to resend the exact request"
                    );
                    let mut response = torii_proxy_error_response(
                        StatusCode::SERVICE_UNAVAILABLE,
                        "signed_query_outcome_unknown",
                        format!(
                            "signed query may have reached authority `{peer_id}` via {transport}; \
                             the exact nonce-bearing request was not retried: {reason}"
                        ),
                    );
                    insert_route_transport_header(&mut response, transport);
                    complete_request(request_id).await;
                    return response;
                }
            }
        }
        complete_request(request_id).await;
        return torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            last_pre_dispatch_error.map_or_else(
                || {
                    format!(
                        "no authoritative peers are available for one-shot signed query lane {} dataspace {}",
                        routing_decision.lane_id.as_u32(),
                        routing_decision.dataspace_id.as_u64()
                    )
                },
                |reason| {
                    format!(
                        "every signed-query authority failed before dispatch for lane {} dataspace {}: {reason}",
                        routing_decision.lane_id.as_u32(),
                        routing_decision.dataspace_id.as_u64()
                    )
                },
            ),
        );
    }
    let mut last_retryable = None;
    for candidate in candidate_peers {
        if tokio::time::Instant::now() >= execution_deadline {
            break;
        }
        let peer_id = candidate.peer_id().clone();
        let transport = candidate.transport_label();
        match execute(candidate, request.clone()).await {
            Ok(snapshot) => {
                if let ToriiProxyRequestKindV1::SubmitTransaction { transaction, .. } =
                    &request.request
                {
                    if snapshot.status_code == StatusCode::ACCEPTED.as_u16() {
                        if let Err(error) =
                            validate_native_transaction_submission_identity(&snapshot, transaction)
                        {
                            complete_request(request_id).await;
                            return transaction_dispatch_outcome_unknown_response(
                                transaction.hash(),
                                signed_transaction_hash_for_entrypoint(transaction),
                                error,
                            );
                        }
                    }
                }
                let retryable = should_retry_generic_torii_proxy_snapshot(&snapshot);
                let snapshot = if retryable {
                    bound_retained_retryable_torii_proxy_snapshot(snapshot)
                } else {
                    snapshot
                };
                let mut response = torii_proxy_snapshot_to_response(snapshot);
                insert_route_transport_header(&mut response, transport);
                if retryable {
                    last_retryable = Some(response);
                    continue;
                }
                complete_request(request_id.clone()).await;
                return response;
            }
            Err(error) => {
                if error.may_have_reached_authority() {
                    if let ToriiProxyRequestKindV1::SubmitTransaction { transaction, .. } =
                        &request.request
                    {
                        complete_request(request_id).await;
                        return transaction_dispatch_outcome_unknown_response(
                            transaction.hash(),
                            signed_transaction_hash_for_entrypoint(transaction),
                            error.to_string(),
                        );
                    }
                }
                iroha_logger::warn!(
                    peer_id = %peer_id,
                    transport,
                    %error,
                    "Torii ingress proxy attempt failed"
                );
            }
        }
    }
    complete_request(request_id).await;
    return last_retryable.unwrap_or_else(|| {
        torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!(
                "no authoritative peers responded for lane {} dataspace {}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
        )
    });
}

#[cfg(feature = "connect")]
fn normalize_proxied_transaction_submission_response(
    app: &AppState,
    proxy_response: Response,
    entrypoint_hash: HashOf<TransactionEntrypoint>,
    signed_transaction_hash: Option<HashOf<SignedTransaction>>,
    routing_decision: RoutingDecision,
    minimal_response: bool,
    format: ResponseFormat,
) -> Response {
    if proxy_response.status() != StatusCode::ACCEPTED {
        return proxy_response;
    }
    let route_transport = proxy_response
        .headers()
        .get("x-iroha-route-transport")
        .cloned();
    let mut response = transaction_submission_response(
        app,
        entrypoint_hash.clone(),
        signed_transaction_hash.clone(),
        routing_decision,
        "proxy",
        minimal_response,
        format,
    );
    if response.status() != StatusCode::ACCEPTED {
        iroha_logger::error!(
            status = %response.status(),
            entrypoint_hash = %entrypoint_hash,
            "failed to produce the public submission receipt after authenticated queue admission; preserving known Accepted outcome"
        );
        response = Response::new(Body::empty());
        *response.status_mut() = StatusCode::ACCEPTED;
        if minimal_response {
            response.headers_mut().insert(
                HeaderName::from_static("preference-applied"),
                HeaderValue::from_static(PREFER_RETURN_MINIMAL),
            );
        }
        insert_transaction_submission_identity_headers(
            &mut response,
            &entrypoint_hash,
            signed_transaction_hash.as_ref(),
        );
        insert_routing_headers(&mut response, routing_decision, "proxy");
    }
    if let Some(route_transport) = route_transport {
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-route-transport"),
            route_transport,
        );
    }
    response
}
mod ordinary_transaction_ingress;

#[cfg(feature = "connect")]
async fn execute_torii_transaction_via_proxy(
    app: &SharedAppState,
    accepted_transaction: iroha_core::tx::AcceptedTransaction<'static>,
    routing_plan: RoutingPlan,
    minimal_response: bool,
    format: ResponseFormat,
) -> Response {
    let route = routing_plan.coordinator_route();
    if should_execute_route_locally(app, route) {
        return ordinary_transaction_ingress::submit(
            app.clone(),
            accepted_transaction,
            routing_plan,
            minimal_response,
            format,
        )
        .await;
    }
    let transaction = accepted_transaction.entrypoint().clone();
    let hash = transaction.hash();
    let signed_hash = signed_transaction_hash_for_entrypoint(&transaction);
    let response = execute_torii_proxy_request_with_fallback(
        app,
        route,
        ToriiProxyRequestKindV1::SubmitTransaction {
            transaction,
            expected_plan: routing_plan.into(),
        },
    )
    .await;
    normalize_proxied_transaction_submission_response(
        app,
        response,
        hash,
        signed_hash,
        route,
        minimal_response,
        format,
    )
}
#[cfg(feature = "connect")]
async fn execute_torii_query_via_proxy(
    app: &SharedAppState,
    query_bytes: Vec<u8>,
    routing_decision: RoutingDecision,
    format: ResponseFormat,
) -> Response {
    execute_torii_proxy_request_with_fallback(
        app,
        routing_decision,
        ToriiProxyRequestKindV1::SignedQuery {
            query_bytes,
            expected_route: ToriiRouteHintV1::from(routing_decision),
            response_format: torii_proxy_response_format(format),
        },
    )
    .await
}
