#[cfg(feature = "app_api")]
async fn execute_torii_read_via_public_dataspace_upstream(
    upstream_url: String,
    routing_decision: RoutingDecision,
    request: ToriiReadProxyRequestV1,
    max_response_bytes: usize,
) -> Response {
    let path = match torii_external_read_path(&request) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let mut url = format!(
        "{}/{}",
        upstream_url.trim_end_matches('/'),
        path.trim_start_matches('/')
    );
    if let Some(query_string) = request
        .query_string
        .as_deref()
        .filter(|query| !query.is_empty())
    {
        url.push('?');
        url.push_str(query_string);
    }
    let method = torii_read_http_method(request.endpoint);
    let client = match reqwest::Client::builder()
        .redirect(reqwest::redirect::Policy::none())
        .build()
    {
        Ok(client) => client,
        Err(error) => {
            return torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "route_unavailable",
                format!("failed to initialize public dataspace HTTP client: {error}"),
            );
        }
    };
    let mut builder = client
        .request(method.clone(), url.clone())
        .header(
            axum::http::header::ACCEPT.as_str(),
            torii_proxy_accept_header(request.response_format)
                .to_str()
                .unwrap_or("application/json"),
        )
        .timeout(DEFAULT_ROUTE_TIMEOUT);
    if method == reqwest::Method::POST {
        builder = builder
            .header(
                axum::http::header::CONTENT_TYPE.as_str(),
                "application/json",
            )
            .body(request.body);
    }
    let mut response = match builder.send().await {
        Ok(response) => response,
        Err(error) => {
            return torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "route_unavailable",
                format!(
                    "public dataspace upstream `{url}` for dataspace {} is unavailable: {error}",
                    routing_decision.dataspace_id
                ),
            );
        }
    };
    let status =
        StatusCode::from_u16(response.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    let content_type = response
        .headers()
        .get(axum::http::header::CONTENT_TYPE.as_str())
        .cloned();
    let mut reject_codes = response.headers().get_all("x-iroha-reject-code").iter();
    let reject_code = reject_codes
        .next()
        .filter(|_| reject_codes.next().is_none())
        .filter(|_| status.is_client_error() || status.is_server_error())
        .filter(|value| value.to_str().is_ok_and(crate::utils::is_valid_reject_code))
        .cloned();
    let max_response_bytes =
        public_dataspace_upstream_response_body_limit(request.endpoint, max_response_bytes);
    let body = match read_reqwest_response_body_bounded(
        &mut response,
        max_response_bytes,
        "public dataspace upstream",
    )
    .await
    {
        Ok(body) => Bytes::from(body),
        Err(error) => {
            let code = if error.is_limit() {
                "upstream_response_too_large"
            } else {
                "route_unavailable"
            };
            let mut response = torii_proxy_error_response(
                StatusCode::BAD_GATEWAY,
                code,
                format!("failed to read public dataspace upstream response from `{url}`: {error}"),
            );
            insert_routing_headers(&mut response, routing_decision, "external");
            return response;
        }
    };
    let mut response = Response::new(Body::from(body));
    *response.status_mut() = status;
    if let Some(content_type) = content_type {
        response
            .headers_mut()
            .insert(axum::http::header::CONTENT_TYPE, content_type);
    }
    if let Some(reject_code) = reject_code {
        response
            .headers_mut()
            .insert(HeaderName::from_static("x-iroha-reject-code"), reject_code);
    }
    insert_routing_headers(&mut response, routing_decision, "external");
    response
}
#[cfg(feature = "app_api")]
fn torii_proxy_accept_header(format: ToriiProxyResponseFormatV1) -> HeaderValue {
    match format {
        ToriiProxyResponseFormatV1::Norito => {
            HeaderValue::from_static(crate::utils::NORITO_MIME_TYPE)
        }
        ToriiProxyResponseFormatV1::Json => HeaderValue::from_static("application/json"),
    }
}
#[cfg(feature = "app_api")]
fn torii_proxy_path_arg(
    request: &ToriiReadProxyRequestV1,
    index: usize,
    label: &str,
) -> Result<String, Response> {
    request.path_args.get(index).cloned().ok_or_else(|| {
        torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            format!("missing proxied path argument `{label}`"),
        )
    })
}
#[cfg(feature = "app_api")]
fn trusted_internal_read_error_response(
    status: StatusCode,
    code: &'static str,
    message: impl Into<String>,
    format: ResponseFormat,
) -> Response {
    let mut response = crate::utils::respond_with_status_and_format(
        status,
        ErrorEnvelope::new(code, message.into()),
        format,
    );
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-reject-code"),
        HeaderValue::from_static(code),
    );
    response
}
#[cfg(feature = "app_api")]
fn execute_trusted_internal_account_local_read(
    app: &SharedAppState,
    account_literal: &str,
    format: ResponseFormat,
) -> Response {
    execute_torii_internal_account_local_source_read(app, account_literal, format)
}
#[cfg(feature = "app_api")]
fn execute_trusted_internal_account_transaction_local_read(
    app: &SharedAppState,
    account_literal: &str,
    entrypoint_hash_literal: &str,
    format: ResponseFormat,
) -> Response {
    // Known limitation: this history read still uses the bounded committed-transaction
    // snapshot rather than a routed-budget-aware Kura projection. Cold block/finality
    // materialization can exceed the App fanout decode budget, so this route retains
    // non-source-bounded semantics until that projection exists.
    let (account_id, _) = match parse_exact_account_id_literal(account_literal) {
        Ok(parsed) => parsed,
        Err(error) => return error_response_with_format(error, format),
    };
    let entrypoint_hash = match parse_exact_entrypoint_hash_literal(entrypoint_hash_literal) {
        Ok(hash) => hash,
        Err(error) => return error_response_with_format(error, format),
    };
    let transactions = match routing::committed_transactions_snapshot(app.state.as_ref()) {
        Ok(transactions) => transactions,
        Err(error) => return error_response_with_format(error, format),
    };
    let transaction = transactions.into_iter().find(|transaction| {
        transaction.entrypoint_hash() == &entrypoint_hash
            && routing::tx_references_account_id(transaction, &account_id)
    });
    match transaction {
        Some(transaction) => crate::utils::respond_with_format(transaction, format),
        None => trusted_internal_read_error_response(
            StatusCode::NOT_FOUND,
            "not_found",
            "no committed transaction with the exact hash references the exact account",
            format,
        ),
    }
}
