#[cfg(feature = "app_api")]
fn soracloud_local_read_response(
    response: iroha_core::soracloud_runtime::SoracloudLocalReadResponse,
) -> Response {
    let mut builder = Response::builder().status(StatusCode::OK);
    if let Some(content_type) = response.content_type.as_deref() {
        builder = builder.header(axum::http::header::CONTENT_TYPE, content_type);
    }
    if let Some(content_encoding) = response.content_encoding.as_deref() {
        builder = builder.header(axum::http::header::CONTENT_ENCODING, content_encoding);
    }
    if let Some(cache_control) = response.cache_control.as_deref() {
        builder = builder.header(axum::http::header::CACHE_CONTROL, cache_control);
    }
    builder = builder
        .header(
            "x-iroha-soracloud-certified-by",
            match response.certified_by {
                iroha_data_model::soracloud::SoraCertifiedResponsePolicyV1::None => "none",
                iroha_data_model::soracloud::SoraCertifiedResponsePolicyV1::StateCommitment => {
                    "state_commitment"
                }
                iroha_data_model::soracloud::SoraCertifiedResponsePolicyV1::AuditReceipt => {
                    "audit_receipt"
                }
            },
        )
        .header(
            "x-iroha-soracloud-result-commitment",
            response.result_commitment.to_string(),
        );
    if let Ok(bindings_json) = norito::json::to_json(&response.bindings) {
        let encoded = base64::engine::general_purpose::STANDARD.encode(bindings_json);
        builder = builder.header("x-iroha-soracloud-bindings", encoded);
    }
    if let Some(receipt) = response.runtime_receipt.as_ref() {
        builder = builder.header(
            "x-iroha-soracloud-receipt-id",
            receipt.receipt_id.to_string(),
        );
        if let Ok(receipt_json) = norito::json::to_json(receipt) {
            let encoded = base64::engine::general_purpose::STANDARD.encode(receipt_json);
            builder = builder.header("x-iroha-soracloud-receipt", encoded);
        }
    }
    builder
        .body(Body::from(response.response_bytes))
        .unwrap_or_else(|error| {
            iroha_logger::error!(?error, "failed to build Soracloud local-read response");
            Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::from("failed to build Soracloud local-read response"))
                .expect("static response build succeeds")
        })
}
#[cfg(feature = "app_api")]
fn soracloud_ordered_mailbox_response(
    response: iroha_core::soracloud_runtime::SoracloudOrderedMailboxExecutionResult,
) -> Response {
    let mut builder = Response::builder().status(StatusCode::OK);
    if let Some(content_type) = response.content_type.as_deref() {
        builder = builder.header(axum::http::header::CONTENT_TYPE, content_type);
    }
    builder = builder
        .header(axum::http::header::CACHE_CONTROL, "no-store")
        .header("x-iroha-soracloud-certified-by", "none")
        .header(
            "x-iroha-soracloud-result-commitment",
            response.runtime_receipt.result_commitment.to_string(),
        )
        .header(
            "x-iroha-soracloud-receipt-id",
            response.runtime_receipt.receipt_id.to_string(),
        );
    if let Ok(receipt_json) = norito::json::to_json(&response.runtime_receipt) {
        let encoded = base64::engine::general_purpose::STANDARD.encode(receipt_json);
        builder = builder.header("x-iroha-soracloud-receipt", encoded);
    }
    builder
        .body(Body::from(response.response_bytes))
        .unwrap_or_else(|error| {
            iroha_logger::error!(?error, "failed to build Soracloud ordered-mailbox response");
            Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::from(
                    "failed to build Soracloud ordered-mailbox response",
                ))
                .expect("static response build succeeds")
        })
}
#[cfg(feature = "app_api")]
fn soracloud_local_read_error_response(
    error: iroha_core::soracloud_runtime::SoracloudRuntimeExecutionError,
) -> Response {
    let status = match error.kind {
        SoracloudRuntimeExecutionErrorKind::Unavailable => StatusCode::SERVICE_UNAVAILABLE,
        SoracloudRuntimeExecutionErrorKind::Conflict => StatusCode::CONFLICT,
        SoracloudRuntimeExecutionErrorKind::InvalidRequest => StatusCode::BAD_REQUEST,
        SoracloudRuntimeExecutionErrorKind::Internal => StatusCode::INTERNAL_SERVER_ERROR,
    };
    Response::builder()
        .status(status)
        .body(Body::from(error.message))
        .unwrap_or_else(|build_error| {
            iroha_logger::error!(
                ?build_error,
                "failed to build Soracloud local-read error response"
            );
            StatusCode::INTERNAL_SERVER_ERROR.into_response()
        })
}
#[cfg(all(test, feature = "app_api"))]
#[test]
fn soracloud_local_read_conflict_maps_to_http_conflict() {
    let response = soracloud_local_read_error_response(
        iroha_core::soracloud_runtime::SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Conflict,
            "terminal Soracloud local-read fixture",
        ),
    );
    assert_eq!(response.status(), StatusCode::CONFLICT);
}
#[cfg(feature = "app_api")]
fn hosted_http_request_hash(
    scope: &str,
    service_name: &str,
    service_version: Option<&str>,
    remote_ip: Option<IpAddr>,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
) -> [u8; 32] {
    let payload = norito::to_bytes(&(
        scope,
        service_name,
        service_version,
        remote_ip.map(|ip| ip.to_string()),
        method.as_str(),
        uri.path(),
        uri.query(),
    ))
    .expect("hosted-http request hash payload should encode");
    *blake3_hash(&payload).as_bytes()
}
#[cfg(feature = "app_api")]
fn hosted_http_placement_has_active_peer_binding(
    state_view: &iroha_core::state::StateView<'_>,
    placement: &iroha_data_model::soracloud::SoraInrouReplicaPlacementV1,
    current_height: u64,
) -> bool {
    iroha_core::soracloud_runtime::soracloud_validator_has_active_peer_binding(
        state_view.world(),
        &placement.validator_account_id,
        &placement.peer_id,
        current_height,
        |lane_id| state_view.is_lane_active_for_authority(lane_id),
    )
}
#[cfg(feature = "app_api")]
fn hosted_http_runtime_state_matches_placement(
    runtime_state: &iroha_data_model::soracloud::SoraInrouReplicaRuntimeStateV1,
    service_name: &str,
    service_version: &str,
    placement: &iroha_data_model::soracloud::SoraInrouReplicaPlacementV1,
    admitted_bundle_hash: &iroha_crypto::Hash,
) -> bool {
    runtime_state.service_name.as_ref() == service_name
        && runtime_state.service_version == service_version
        && runtime_state.replica_slot == placement.replica_slot
        && runtime_state.placement_incarnation == placement.placement_incarnation
        && runtime_state.validator_account_id == placement.validator_account_id
        && runtime_state.peer_id == placement.peer_id
        && runtime_state.selected_guest_isa == placement.selected_guest_isa
        && runtime_state.materialized_bundle_hash == *admitted_bundle_hash
}
#[cfg(feature = "app_api")]
fn select_authoritative_hosted_http_replica(
    state_view: &iroha_core::state::StateView<'_>,
    service_name: &str,
    service_version: &str,
    admitted_bundle_hash: &iroha_crypto::Hash,
    placements: &[iroha_data_model::soracloud::SoraInrouReplicaPlacementV1],
    remote_ip: Option<IpAddr>,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
) -> Option<(
    iroha_data_model::soracloud::SoraInrouReplicaPlacementV1,
    iroha_data_model::soracloud::SoraInrouReplicaRuntimeStateV1,
)> {
    let world = state_view.world();
    let current_height = u64::try_from(state_view.height()).unwrap_or(u64::MAX);
    let service_name_id = Name::from_str(service_name).ok()?;
    let lease_started_height = world
        .soracloud_service_deployments()
        .get(&service_name_id)
        .and_then(|deployment| deployment.service_lease.as_ref())?
        .lease_started_height;

    let healthy_replicas = placements
        .iter()
        .filter_map(|placement| {
            let runtime_state = world.soracloud_inrou_replica_runtime().get(&(
                service_name.to_owned(),
                service_version.to_owned(),
                placement.replica_slot.to_string(),
            ))?;
            (placement.host_availability.is_available()
                && placement.lease_started_height == lease_started_height
                && hosted_http_placement_has_active_peer_binding(
                    state_view,
                    placement,
                    current_height,
                )
                && hosted_http_runtime_state_matches_placement(
                    runtime_state,
                    service_name,
                    service_version,
                    placement,
                    admitted_bundle_hash,
                )
                && runtime_state.health_status
                    == iroha_data_model::soracloud::SoraServiceHealthStatusV1::Healthy)
                .then(|| (placement.clone(), runtime_state.clone()))
        })
        .collect::<Vec<_>>();
    if healthy_replicas.is_empty() {
        return None;
    }
    if healthy_replicas.len() == 1 {
        return healthy_replicas.into_iter().next();
    }
    let digest = hosted_http_request_hash(
        "soracloud:hosted-http-replica:v1",
        service_name,
        Some(service_version),
        remote_ip,
        method,
        uri,
    );
    let index = usize::from(u16::from_le_bytes([digest[0], digest[1]])) % healthy_replicas.len();
    healthy_replicas.into_iter().nth(index)
}
#[cfg(feature = "app_api")]
fn authoritative_hosted_http_revision(
    world: &impl WorldReadOnly,
    current_height: u64,
    service_name: &str,
) -> Result<(String, u64), SoracloudRuntimeExecutionError> {
    let deployment_name: Name = service_name.parse().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hosted Soracloud service name `{service_name}` is invalid in authoritative state: {error}"
            ),
        )
    })?;

    let Some(deployment) = world.soracloud_service_deployments().get(&deployment_name) else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!("hosted Soracloud deployment for service `{service_name}` is unavailable"),
        ));
    };
    deployment.validate().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hosted Soracloud deployment for service `{service_name}` is malformed: {error}"
            ),
        )
    })?;
    let lease_status = deployment
        .hosted_service_lease_status_at(current_height)
        .map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Internal,
                format!(
                    "hosted Soracloud lease status for service `{service_name}` could not be calculated: {error}"
                ),
            )
        })?
        .ok_or_else(|| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!("hosted Soracloud lease for service `{service_name}` is unavailable"),
            )
        })?;
    if lease_status != iroha_data_model::soracloud::SoraServiceLeaseStatusV1::Active {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "hosted Soracloud lease for service `{service_name}` is not active ({lease_status:?})"
            ),
        ));
    }
    if deployment.process_generation == 0 {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "hosted Soracloud deployment for service `{service_name}` has no positive process generation"
            ),
        ));
    }
    if deployment.active_rollout.is_some() {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "service `{service_name}` carries an unsupported active Inrou canary; first-release host-local lease disks require one active revision"
            ),
        ));
    }
    Ok((
        deployment.current_service_version.clone(),
        deployment.process_generation,
    ))
}
