#[cfg(feature = "app_api")]
async fn handler_get_vk_by_backend_name(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    axum::extract::Path((backend, name)): axum::extract::Path<(String, String)>,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    if limits::is_allowed_by_cidr(&headers, Some(remote_ip), &app.api_rate_limit_bypass_nets) {
        return crate::routing::handle_get_vk(
            app.state.clone(),
            axum::extract::Path((backend, name)),
        )
        .await
        .map(axum::response::IntoResponse::into_response);
    }
    validate_api_token(app.as_ref(), &headers)?;
    let key = rate_limit_key(
        &headers,
        Some(remote_ip),
        "v1/zk/vk/{backend}/{name}",
        app.authenticated_api_token_principal(&headers),
    );
    if !app.rate_limiter.allow(&key).await {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
        )));
    }
    match crate::routing::handle_get_vk(app.state.clone(), axum::extract::Path((backend, name)))
        .await
    {
        Ok(resp) => Ok(resp.into_response()),
        Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        ))) => Ok(axum::http::StatusCode::NOT_FOUND.into_response()),
        Err(e) => Err(e),
    }
}
#[cfg(feature = "app_api")]
async fn handler_get_proof_by_backend_hash(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    axum::extract::Path((backend, hash)): axum::extract::Path<(String, String)>,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    let enforce =
        !limits::is_allowed_by_cidr(&headers, Some(remote_ip), &app.api_rate_limit_bypass_nets);
    check_proof_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/zk/proof/{backend}/{hash}",
        1,
        enforce,
    )
    .await?;
    match crate::routing::handle_get_proof(
        app.state.clone(),
        app.proof_limits,
        &app.telemetry,
        Some(&headers),
        axum::extract::Path((backend, hash)),
    )
    .await
    {
        Ok(resp) => {
            enforce_proof_egress(
                &app,
                &headers,
                Some(remote_ip),
                "v1/zk/proof",
                resp.bytes,
                enforce,
            )
            .await?;
            Ok(resp.into_response())
        }
        Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        ))) => Ok(axum::http::StatusCode::NOT_FOUND.into_response()),
        Err(e) => Err(e),
    }
}
