#[cfg(feature = "app_api")]
async fn handler_post_contract_call_simulate(
    State(app): State<SharedAppState>,
    Extension(verified): Extension<crate::app_auth::VerifiedCanonicalRequest>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    request: NoritoJson<crate::routing::ContractCallSimulateDto>,
) -> Result<AxResponse, Error> {
    require_runtime_governance_account(
        &request.0.authority,
        &verified.account,
        "contract simulation",
    )?;
    check_public_contract_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/contracts/call/simulate",
        "call_simulate",
    )
    .await?;
    let retry_after_secs = app.proof_limits.retry_after.as_secs().max(1);
    let tooling_permit = app
        .ivm_tooling_inflight
        .clone()
        .try_acquire_owned()
        .map_err(|_| Error::ProofRateLimited {
            endpoint: "v1/contracts/call/simulate",
            retry_after_secs,
        })?;
    let state = app.state.clone();
    let simulation_task = crate::panic_recovery::spawn_blocking_recoverable(move || {
        // Retain capacity until physical VM completion even if the awaiting
        // request future times out or is cancelled.
        let _tooling_permit = tooling_permit;
        crate::routing::handle_post_contract_call_simulate(state, request)
    });
    match tokio::time::timeout(
        app.ivm_tooling_timeout,
        crate::panic_recovery::join_recoverable(simulation_task),
    )
    .await
    {
        Ok(Ok(Ok(body))) => {
            proof_cached_json_response_with_egress(
                &app,
                &headers,
                Some(remote.ip()),
                "v1/contracts/call/simulate",
                Bytes::from(body),
                true,
            )
            .await
        }
        Ok(Ok(Err(err))) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("call_simulate"));
            Err(err)
        }
        Ok(Err(err)) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("call_simulate"));
            Err(Error::Query(
                iroha_data_model::ValidationFail::InternalError(format!(
                    "contract simulation worker panicked: {err}"
                )),
            ))
        }
        Err(_) => Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "contract simulation timed out; capacity remains reserved until the worker exits"
                    .to_owned(),
            ),
        ))),
    }
}
#[cfg(feature = "app_api")]
async fn handler_post_contract_view(
    State(app): State<SharedAppState>,
    Extension(verified): Extension<crate::app_auth::VerifiedCanonicalRequest>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    request: NoritoJson<crate::routing::ContractViewDto>,
) -> Result<AxResponse, Error> {
    require_runtime_governance_account(&request.0.authority, &verified.account, "contract view")?;
    check_public_contract_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/contracts/view",
        "view",
    )
    .await?;
    if let Some(route) = torii_contract_target_read_route(
        app.as_ref(),
        request.0.contract_address.as_ref(),
        request.0.contract_alias.as_ref(),
    )? {
        let body = norito::json::to_vec(&request.0).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "failed to encode routed contract view request: {error}"
            )))
        })?;
        return Ok(execute_torii_single_route_read_with_format(
            &app,
            route,
            ToriiReadEndpointV1::ContractViewPost,
            Vec::new(),
            None,
            body,
            ToriiProxyResponseFormatV1::Json,
            Some(&verified.account),
        )
        .await
        .into_response());
    }
    match execute_bounded_contract_view_work(
        &app,
        "v1/contracts/view",
        BoundedContractViewWork::Single(request.0),
    )
    .await
    {
        Ok(BoundedContractViewOutput::Single {
            status,
            body,
            memory,
        }) => {
            let mut response = proof_cached_json_response_with_egress(
                &app,
                &headers,
                Some(remote.ip()),
                "v1/contracts/view",
                Bytes::from(body),
                true,
            )
            .await?;
            *response.status_mut() = status;
            Ok(hold_query_fanout_memory_in_response_body(response, memory))
        }
        Ok(BoundedContractViewOutput::Batch { .. }) => Err(Error::Query(
            iroha_data_model::ValidationFail::InternalError(
                "contract view worker returned a batch response".to_owned(),
            ),
        )),
        Err(err) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("view"));
            Err(err)
        }
    }
}
#[cfg(feature = "app_api")]
async fn handler_post_contract_view_batch(
    State(app): State<SharedAppState>,
    Extension(verified): Extension<crate::app_auth::VerifiedCanonicalRequest>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    request: NoritoJson<crate::routing::ContractViewBatchDto>,
) -> Result<AxResponse, Error> {
    require_runtime_governance_account(
        &request.0.authority,
        &verified.account,
        "contract view batch",
    )?;
    check_public_contract_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/contracts/view/batch",
        "view_batch",
    )
    .await?;
    crate::routing::validate_contract_view_batch_request(&request.0)?;
    let mut batch_route = None;
    let mut batch_route_conflict = false;
    let mut all_items_routed = !request.0.items.is_empty();
    for item in &request.0.items {
        let item_route = torii_contract_target_read_route(
            app.as_ref(),
            item.contract_address.as_ref(),
            item.contract_alias.as_ref(),
        )?;
        match item_route {
            Some(item_route) => match batch_route {
                Some(existing) if existing != item_route => {
                    batch_route_conflict = true;
                    break;
                }
                Some(_) => {}
                None => batch_route = Some(item_route),
            },
            None => {
                all_items_routed = false;
                break;
            }
        }
    }
    if let Some(route) = batch_route
        && all_items_routed
        && !batch_route_conflict
    {
        let body = norito::json::to_vec(&request.0).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "failed to encode routed contract view batch request: {error}"
            )))
        })?;
        return Ok(execute_torii_single_route_read_with_format(
            &app,
            route,
            ToriiReadEndpointV1::ContractViewBatchPost,
            Vec::new(),
            None,
            body,
            ToriiProxyResponseFormatV1::Json,
            Some(&verified.account),
        )
        .await
        .into_response());
    }
    match execute_bounded_contract_view_work(
        &app,
        "v1/contracts/view/batch",
        BoundedContractViewWork::Batch(request.0),
    )
    .await
    {
        Ok(BoundedContractViewOutput::Batch { body, memory }) => {
            let response = proof_cached_json_response_with_egress(
                &app,
                &headers,
                Some(remote.ip()),
                "v1/contracts/view/batch",
                Bytes::from(body),
                true,
            )
            .await?;
            Ok(hold_query_fanout_memory_in_response_body(response, memory))
        }
        Ok(BoundedContractViewOutput::Single { .. }) => Err(Error::Query(
            iroha_data_model::ValidationFail::InternalError(
                "contract view batch worker returned a single response".to_owned(),
            ),
        )),
        Err(err) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("view_batch"));
            Err(err)
        }
    }
}
