macro_rules! iso_payment_submission_handlers {
    (
        $(($handler:ident, $message_type:literal, $access_context:literal,
            $payload_builder:ident)),+ $(,)?
    ) => {
        $(
            async fn $handler(
                State(app): State<SharedAppState>,
                Extension(authenticated_operator): Extension<operator_signatures::AuthenticatedOperatorPublicKey>,
                headers: axum::http::HeaderMap,
                Query(query): Query<HashMap<String, String>>,
                axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
                body: axum::body::Bytes,
            ) -> Result<(StatusCode, JsonBody<norito::json::native::Value>), Error> {
                let remote_ip = remote.ip();
                check_access(&app, &headers, Some(remote_ip), $access_context).await?;
                let runtime = match &app.iso_bridge {
                    Some(rt) => rt.clone(),
                    None => {
                        return Err(Error::Query(
                            iroha_data_model::ValidationFail::NotPermitted("iso20022 bridge disabled".into()),
                        ));
                    }
                };
                if body.is_empty() {
                    return Err(Error::Query(
                        iroha_data_model::ValidationFail::NotPermitted("empty ISO 20022 payload".into()),
                    ));
                }
                let parsed = parse_xml_message($message_type, &body)
                    .map_err(|err| Error::Query(map_iso_error(err)))?;
                let profile = iso_profile_from_request(&runtime, &headers, &query)?;
                let parties = runtime
                    .authorize_initial_submission(&authenticated_operator.0, profile, &parsed)
                    .map_err(map_iso_admission_error)?;
                let metadata = runtime
                    .validate_profile_submission(profile, $message_type, &parsed, &body)
                    .map_err(|err| Error::Query(map_iso_error(err)))?;
                let msg_id = Iso20022BridgeRuntime::payment_message_id($message_type, &parsed)
                    .map_err(|err| Error::Query(map_iso_error(err)))?;
                runtime
                    .admit_authenticated_inbound(&msg_id, metadata, parties)
                    .map_err(map_iso_admission_error)?;
                let now_ms = routing::asset_alias_observation_time_ms(app.state.as_ref());
                let (mut transaction_payload, context) = {
                    let world = app.state.world_view();
                    match runtime.$payload_builder(
                        &parsed,
                        &world,
                        now_ms,
                        Arc::as_ref(&app.chain_id),
                        app.state.network_id_ref(),
                        &app.telemetry,
                    ) {
                        Ok(result) => result,
                        Err(err) => {
                            runtime.mark_rejected(&msg_id, Some(err.to_string()), None);
                            return Err(Error::Query(map_iso_error(err)));
                        }
                    }
                };
                transaction_payload.fee_payment = match quote_internal_fee_payment(&app, &transaction_payload) {
                    Ok(intent) => intent,
                    Err(err) => {
                        runtime.mark_rejected(&msg_id, Some(err.to_string()), None);
                        return Err(err);
                    }
                };
                let transaction = match runtime.sign_transaction_payload(transaction_payload) {
                    Ok(transaction) => transaction,
                    Err(err) => {
                        runtime.mark_rejected(&msg_id, Some(err.to_string()), None);
                        return Err(Error::Query(map_iso_error(err)));
                    }
                };
                if !runtime.update_message_context(&msg_id, context.clone()) {
                    runtime.mark_rejected(
                        &msg_id,
                        Some("failed to retain admitted ISO message context".to_owned()),
                        Some("PRTRY:DURABILITY_FAILURE"),
                    );
                    return Err(Error::Query(
                        iroha_data_model::ValidationFail::NotPermitted(
                            "failed to retain the admitted ISO message context before queue admission"
                                .into(),
                        ),
                    ));
                }
                let tx_hash = transaction.hash();
                let tx_hash_str = format!("{}", tx_hash);
                if !runtime.bind_transaction_hash(&msg_id, &tx_hash_str) {
                    runtime.mark_rejected(
                        &msg_id,
                        Some("failed to reserve signed ISO transaction identity".to_owned()),
                        Some("PRTRY:DURABILITY_FAILURE"),
                    );
                    return Err(Error::Query(
                        iroha_data_model::ValidationFail::NotPermitted(
                            "failed to reserve the signed ISO transaction identity before queue admission"
                                .into(),
                        ),
                    ));
                }
                if let Err(err) =
                    routing::handle_transaction(app.queue.clone(), app.state.clone(), transaction).await
                {
                    let (detail, reason_code) = match &err {
                        Error::PushIntoQueue { source, .. } => {
                            let (code, detail) = queue_rejection_metadata(source.as_ref());
                            (detail, Some(code))
                        }
                        _ => (err.to_string(), None),
                    };
                    runtime.mark_rejected(&msg_id, Some(detail), reason_code);
                    return Err(err);
                }
                runtime.mark_queued(&msg_id);
                let status_snapshot = runtime.mark_accepted(&msg_id, &tx_hash_str);
                let mut payload = norito::json::native::Map::new();
                payload.insert(
                    "message_id".into(),
                    norito::json::native::Value::from(msg_id),
                );
                payload.insert(
                    "transaction_hash".into(),
                    norito::json::native::Value::from(tx_hash_str),
                );
                payload.insert(
                    "status".into(),
                    norito::json::native::Value::from(status_snapshot.status_label().to_string()),
                );
                payload.insert(
                    "pacs002_code".into(),
                    norito::json::native::Value::from(status_snapshot.pacs002_code().to_string()),
                );
                payload.insert(
                    "hold_reason_code".into(),
                    json_string_or_null(status_snapshot.hold_reason_code().map(ToString::to_string)),
                );
                let change_codes = status_snapshot
                    .change_reason_codes()
                    .iter()
                    .cloned()
                    .map(norito::json::native::Value::from)
                    .collect::<Vec<_>>();
                payload.insert(
                    "change_reason_codes".into(),
                    norito::json::native::Value::Array(change_codes),
                );
                payload.insert(
                    "rejection_reason_code".into(),
                    json_string_or_null(
                        status_snapshot
                            .rejection_reason_code()
                            .map(ToString::to_string),
                    ),
                );
                payload.insert(
                    "ledger_id".into(),
                    json_string_or_null(context.ledger_id().map(ToString::to_string)),
                );
                payload.insert(
                    "source_account_id".into(),
                    json_string_or_null(context.source_account_id().map(ToString::to_string)),
                );
                payload.insert(
                    "source_account_address".into(),
                    json_string_or_null(context.source_account_address().map(ToString::to_string)),
                );
                payload.insert(
                    "target_account_id".into(),
                    json_string_or_null(context.target_account_id().map(ToString::to_string)),
                );
                payload.insert(
                    "target_account_address".into(),
                    json_string_or_null(context.target_account_address().map(ToString::to_string)),
                );
                payload.insert(
                    "asset_definition_id".into(),
                    json_string_or_null(context.asset_definition_id().map(ToString::to_string)),
                );
                payload.insert(
                    "asset_id".into(),
                    json_string_or_null(context.asset_id().map(ToString::to_string)),
                );
                payload.insert(
                    "settlement_amount".into(),
                    json_string_or_null(context.settlement_amount().map(ToString::to_string)),
                );
                payload.insert(
                    "settlement_currency".into(),
                    json_string_or_null(context.settlement_currency().map(ToString::to_string)),
                );
                insert_iso_metadata_fields(&mut payload, &status_snapshot);
                Ok((
                    StatusCode::ACCEPTED,
                    JsonBody(norito::json::native::Value::Object(payload)),
                ))
            }
        )+
    };
}
iso_payment_submission_handlers!(
    (
        handler_iso_pacs008,
        "pacs.008",
        "v1/iso20022/pacs008",
        build_pacs008_payload
    ),
    (
        handler_iso_pacs009,
        "pacs.009",
        "v1/iso20022/pacs009",
        build_pacs009_payload
    ),
);
async fn handler_iso_lifecycle_submit(
    app: SharedAppState,
    authenticated_operator: operator_signatures::AuthenticatedOperatorPublicKey,
    headers: axum::http::HeaderMap,
    query: HashMap<String, String>,
    remote: std::net::SocketAddr,
    body: axum::body::Bytes,
    message_type: &'static str,
    access_context: &'static str,
) -> Result<(StatusCode, JsonBody<norito::json::native::Value>), Error> {
    let remote_ip = remote.ip();
    check_access(&app, &headers, Some(remote_ip), access_context).await?;
    let runtime = match &app.iso_bridge {
        Some(rt) => rt.clone(),
        None => {
            return Err(Error::Query(
                iroha_data_model::ValidationFail::NotPermitted("iso20022 bridge disabled".into()),
            ));
        }
    };
    if body.is_empty() {
        return Err(Error::Query(
            iroha_data_model::ValidationFail::NotPermitted("empty ISO 20022 payload".into()),
        ));
    }
    let parsed =
        parse_xml_message(message_type, &body).map_err(|err| Error::Query(map_iso_error(err)))?;
    let profile = iso_profile_from_request(&runtime, &headers, &query)?;
    let lifecycle_authorization = runtime
        .authorize_lifecycle_submission(&authenticated_operator.0, profile, message_type, &parsed)
        .map_err(map_iso_admission_error)?;
    let metadata = runtime
        .validate_profile_submission(profile, message_type, &parsed, &body)
        .map_err(|err| Error::Query(map_iso_error(err)))?;
    let msg_id = Iso20022BridgeRuntime::lifecycle_message_id(message_type, &parsed)
        .map_err(|err| Error::Query(map_iso_error(err)))?;
    runtime
        .admit_authenticated_inbound(&msg_id, metadata, lifecycle_authorization.parties().clone())
        .map_err(map_iso_admission_error)?;
    let committed_transaction_hash = lifecycle_authorization
        .settlement_transaction_hash(message_type, &parsed)
        .map_err(|err| Error::Query(map_iso_error(err)))?
        .filter(|hash| {
            hash.parse::<HashOf<SignedTransaction>>()
                .ok()
                .is_some_and(|hash| app.state.has_committed_entrypoint(entrypoint_hash(hash)))
        })
        .map(ToOwned::to_owned);
    let (outcome, status_snapshot) = match runtime.apply_inbound_lifecycle_message_with_evidence(
        &msg_id,
        message_type,
        &parsed,
        &lifecycle_authorization,
        committed_transaction_hash.as_deref(),
    ) {
        Ok(result) => result,
        Err(error) => return Err(map_iso_lifecycle_apply_error(&runtime, &msg_id, error)),
    };
    let mut payload = norito::json::native::Map::new();
    payload.insert(
        "message_id".into(),
        norito::json::native::Value::from(msg_id),
    );
    payload.insert(
        "status".into(),
        norito::json::native::Value::from(status_snapshot.status_label().to_string()),
    );
    payload.insert(
        "pacs002_code".into(),
        norito::json::native::Value::from(status_snapshot.pacs002_code().to_string()),
    );
    payload.insert(
        "lifecycle_message_type".into(),
        norito::json::native::Value::from(message_type),
    );
    payload.insert(
        "referenced_message_id".into(),
        json_string_or_null(outcome.referenced_message_id().map(str::to_string)),
    );
    payload.insert(
        "referenced_message_known".into(),
        norito::json::native::Value::from(outcome.referenced_message_known()),
    );
    payload.insert(
        "lifecycle_status_code".into(),
        json_string_or_null(outcome.lifecycle_status_code().map(str::to_string)),
    );
    payload.insert(
        "lifecycle_reason_code".into(),
        json_string_or_null(outcome.lifecycle_reason_code().map(str::to_string)),
    );
    payload.insert(
        "lifecycle_action".into(),
        norito::json::native::Value::from(outcome.action()),
    );
    payload.insert(
        "detail".into(),
        json_string_or_null(status_snapshot.detail().map(str::to_string)),
    );
    insert_iso_metadata_fields(&mut payload, &status_snapshot);
    Ok((
        StatusCode::ACCEPTED,
        JsonBody(norito::json::native::Value::Object(payload)),
    ))
}
fn map_iso_lifecycle_apply_error(
    runtime: &Iso20022BridgeRuntime,
    message_id: &str,
    error: IsoLifecycleApplyError,
) -> Error {
    match error {
        IsoLifecycleApplyError::Validation(error) => {
            runtime.mark_rejected(message_id, Some(error.to_string()), None);
            Error::Query(map_iso_error(error))
        }
        IsoLifecycleApplyError::PersistenceUnavailable => Error::AppServiceUnavailable {
            code: "iso_lifecycle_persistence_unavailable",
            message: "ISO lifecycle persistence is temporarily unavailable; retry later".to_owned(),
        },
    }
}
macro_rules! iso_lifecycle_submission_handlers {
    ($(($handler:ident, $message_type:literal, $access_context:literal)),+ $(,)?) => {
        $(
            async fn $handler(
                State(app): State<SharedAppState>,
                Extension(authenticated_operator): Extension<operator_signatures::AuthenticatedOperatorPublicKey>,
                headers: axum::http::HeaderMap,
                Query(query): Query<HashMap<String, String>>,
                axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
                body: axum::body::Bytes,
            ) -> Result<(StatusCode, JsonBody<norito::json::native::Value>), Error> {
                handler_iso_lifecycle_submit(
                    app,
                    authenticated_operator,
                    headers,
                    query,
                    remote,
                    body,
                    $message_type,
                    $access_context,
                )
                .await
            }
        )+
    };
}
