fn iso_sese025_xml(status: &IsoMessageStatus) -> Result<String, Error> {
    if status.derived_status() != Pacs002Status::Acsc {
        return Err(iso_outbox_validation_error(
            "sese.025 confirmation requires a settled ISO 20022 message record",
        ));
    }
    let amount =
        require_iso_outbox_field(status.settlement_amount(), "settlement_amount", "sese.025")?;
    let currency = require_iso_outbox_field(
        status.settlement_currency(),
        "settlement_currency",
        "sese.025",
    )?;
    let quantity = require_iso_outbox_field(
        status.settlement_quantity(),
        "settlement_quantity",
        "sese.025",
    )?;
    let movement_type = require_iso_outbox_field(
        status.settlement_movement_type(),
        "settlement_movement_type",
        "sese.025",
    )?;
    let payment_type = require_iso_outbox_field(
        status.settlement_payment_type(),
        "settlement_payment_type",
        "sese.025",
    )?;
    let execution_order = require_iso_outbox_field(
        status.plan_execution_order(),
        "plan_execution_order",
        "sese.025",
    )?;
    let atomicity =
        require_iso_outbox_field(status.plan_atomicity(), "plan_atomicity", "sese.025")?;
    let tx_id = xml_escape(&iso_securities_transaction_id(status));
    let settlement_date = xml_escape(&iso_settlement_date(status));
    let amount = xml_escape(amount);
    let currency = xml_escape(currency);
    let quantity = xml_escape(quantity);
    let movement_type = xml_escape(movement_type);
    let payment_type = xml_escape(payment_type);
    let execution_order = xml_escape(execution_order);
    let atomicity = xml_escape(atomicity);
    let security_leg = iso_security_leg_xml(status);
    let status_reason = iso_settlement_confirmation_reason_xml("    ", status);
    Ok(format!(
        concat!(
            r#"<?xml version="1.0" encoding="UTF-8"?>"#,
            "\n",
            r#"<Document xmlns="urn:iso:std:iso:20022:tech:xsd:sese.025.001.08">"#,
            "\n  <SctiesSttlmTxConf>",
            "\n    <TxId>{tx_id}</TxId>",
            "\n    <SttlmDt>{settlement_date}</SttlmDt>",
            "\n    <SttlmTpAndAddtlParams>",
            "\n      <SctiesMvmntTp>{movement_type}</SctiesMvmntTp>",
            "\n      <Pmt>{payment_type}</Pmt>",
            "\n    </SttlmTpAndAddtlParams>",
            "\n    <TxSts>",
            "\n      <ConfSts>ACCP</ConfSts>",
            "\n    </TxSts>",
            "\n    <SttlmQty><Qty><Unit>{quantity}</Unit></Qty></SttlmQty>",
            "\n    <SttlmAmt Ccy=\"{currency}\">{amount}</SttlmAmt>",
            "{security_leg}",
            "\n    <SplmtryData>",
            "\n      <Plan>",
            "\n        <ExecutionOrder>{execution_order}</ExecutionOrder>",
            "\n        <Atomicity>{atomicity}</Atomicity>",
            "\n      </Plan>",
            "\n    </SplmtryData>",
            "{status_reason}",
            "\n  </SctiesSttlmTxConf>",
            "\n</Document>\n"
        ),
        tx_id = tx_id,
        settlement_date = settlement_date,
        movement_type = movement_type,
        payment_type = payment_type,
        quantity = quantity,
        currency = currency,
        amount = amount,
        security_leg = security_leg,
        execution_order = execution_order,
        atomicity = atomicity,
        status_reason = status_reason,
    ))
}
fn iso_status_reason_xml(indent: &str, status: &IsoMessageStatus) -> String {
    let reason = status
        .rejection_reason_code()
        .or_else(|| status.hold_reason_code())
        .or_else(|| status.change_reason_codes().first().map(String::as_str));
    let detail = status.detail();
    if reason.is_none() && detail.is_none() {
        return String::new();
    }
    let mut xml = String::new();
    xml.push('\n');
    xml.push_str(indent);
    xml.push_str("<StsRsnInf>");
    if let Some(reason) = reason {
        xml.push('\n');
        xml.push_str(indent);
        xml.push_str("  <Rsn>");
        xml.push_str(&iso_reason_xml(reason));
        xml.push_str("</Rsn>");
    }
    if let Some(detail) = detail {
        xml.push('\n');
        xml.push_str(indent);
        xml.push_str("  <AddtlInf>");
        xml.push_str(&xml_escape(detail));
        xml.push_str("</AddtlInf>");
    }
    xml.push('\n');
    xml.push_str(indent);
    xml.push_str("</StsRsnInf>");
    xml
}
fn iso_return_reason_xml(indent: &str, status: &IsoMessageStatus) -> String {
    iso_wrapped_reason_xml("RtrRsnInf", indent, status)
}
fn iso_cancellation_reason_xml(indent: &str, status: &IsoMessageStatus) -> String {
    iso_wrapped_reason_xml("CxlStsRsnInf", indent, status)
}
fn iso_settlement_status_reason_xml(indent: &str, status: &IsoMessageStatus) -> String {
    let reason = status
        .rejection_reason_code()
        .or_else(|| status.hold_reason_code())
        .or_else(|| status.change_reason_codes().first().map(String::as_str));
    let detail = status.detail();
    if reason.is_none() && detail.is_none() {
        return String::new();
    }
    let mut xml = String::new();
    if let Some(reason) = reason {
        xml.push('\n');
        xml.push_str(indent);
        xml.push_str("<Rsn>");
        xml.push_str(&iso_reason_xml(reason));
        xml.push_str("</Rsn>");
    }
    if let Some(detail) = detail {
        xml.push('\n');
        xml.push_str(indent);
        xml.push_str("<AddtlInf>");
        xml.push_str(&xml_escape(detail));
        xml.push_str("</AddtlInf>");
    }
    xml
}
fn iso_settlement_confirmation_reason_xml(indent: &str, status: &IsoMessageStatus) -> String {
    let Some(detail) = status.detail() else {
        return String::new();
    };
    let mut xml = String::new();
    xml.push('\n');
    xml.push_str(indent);
    xml.push_str("<AddtlInf>");
    xml.push_str(&xml_escape(detail));
    xml.push_str("</AddtlInf>");
    xml
}
fn iso_wrapped_reason_xml(wrapper: &str, indent: &str, status: &IsoMessageStatus) -> String {
    let reason = status
        .rejection_reason_code()
        .or_else(|| status.hold_reason_code())
        .or_else(|| status.change_reason_codes().first().map(String::as_str));
    let detail = status.detail();
    if reason.is_none() && detail.is_none() {
        return String::new();
    }
    let mut xml = String::new();
    xml.push('\n');
    xml.push_str(indent);
    xml.push('<');
    xml.push_str(wrapper);
    xml.push('>');
    if let Some(reason) = reason {
        xml.push('\n');
        xml.push_str(indent);
        xml.push_str("  <Rsn>");
        xml.push_str(&iso_reason_xml(reason));
        xml.push_str("</Rsn>");
    }
    if let Some(detail) = detail {
        xml.push('\n');
        xml.push_str(indent);
        xml.push_str("  <AddtlInf>");
        xml.push_str(&xml_escape(detail));
        xml.push_str("</AddtlInf>");
    }
    xml.push('\n');
    xml.push_str(indent);
    xml.push_str("</");
    xml.push_str(wrapper);
    xml.push('>');
    xml
}
fn iso_reason_xml(reason: &str) -> String {
    let trimmed = reason.trim();
    if let Some(proprietary) = trimmed.strip_prefix("PRTRY:") {
        return format!("<Prtry>{}</Prtry>", xml_escape(proprietary));
    }
    format!("<Cd>{}</Cd>", xml_escape(trimmed))
}
fn iso_original_message_name(status: &IsoMessageStatus) -> &str {
    status
        .metadata()
        .message_type()
        .unwrap_or("unknown.iso20022.message")
}
fn iso_original_transaction_id(status: &IsoMessageStatus) -> std::borrow::Cow<'_, str> {
    if let Some(hash) = status.transaction_hash() {
        std::borrow::Cow::Borrowed(hash)
    } else if let Some(business_message_id) = status.metadata().business_message_id() {
        std::borrow::Cow::Borrowed(business_message_id)
    } else {
        std::borrow::Cow::Borrowed(status.message_id())
    }
}
fn iso_securities_transaction_id(status: &IsoMessageStatus) -> std::borrow::Cow<'_, str> {
    for prefix in ["sese.023:", "sese.024:", "sese.025:"] {
        if let Some(stripped) = status.message_id().strip_prefix(prefix) {
            return std::borrow::Cow::Borrowed(stripped);
        }
    }
    iso_original_transaction_id(status)
}
fn iso_camt029_status(status: &IsoMessageStatus) -> &'static str {
    match status.derived_status() {
        Pacs002Status::Rjct => "CNCL",
        Pacs002Status::Acsc => "RJCR",
        Pacs002Status::Actc | Pacs002Status::Acsp | Pacs002Status::Acwc | Pacs002Status::Pdng => {
            "PDCR"
        }
    }
}
fn iso_sese024_status(status: &IsoMessageStatus) -> &'static str {
    match status.derived_status() {
        Pacs002Status::Acsc => "SETT",
        Pacs002Status::Rjct => "RJCT",
        Pacs002Status::Pdng => "PEND",
        Pacs002Status::Acwc => {
            if status
                .change_reason_codes()
                .iter()
                .any(|code| code == "PARTIAL_SETTLEMENT")
            {
                "PART"
            } else {
                "PEND"
            }
        }
        Pacs002Status::Actc | Pacs002Status::Acsp => "ACCP",
    }
}
fn iso_settlement_date(status: &IsoMessageStatus) -> String {
    status
        .settlement_date()
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| xml_date(status.settled_at().unwrap_or_else(|| status.updated_at())))
}
fn iso_security_leg_xml(status: &IsoMessageStatus) -> String {
    let Some(instrument_id) = status.security_instrument_id() else {
        return String::new();
    };
    let instrument_id = xml_escape(instrument_id);
    format!(
        "\n    <SctiesMvmntDtls>\n      <SctiesId><OthrId><Id>{instrument_id}</Id></OthrId></SctiesId>\n    </SctiesMvmntDtls>"
    )
}
fn require_iso_outbox_field<'a>(
    value: Option<&'a str>,
    field: &str,
    message_type: &str,
) -> Result<&'a str, Error> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            iso_outbox_validation_error(format!(
                "{message_type} outbox XML requires durable ISO context field `{field}`"
            ))
        })
}
fn iso_outbox_validation_error(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(message.into()),
    ))
}
fn xml_timestamp(time: SystemTime) -> String {
    OffsetDateTime::from(time)
        .format(&Rfc3339)
        .unwrap_or_else(|_| "1970-01-01T00:00:00Z".to_owned())
}
fn xml_date(time: SystemTime) -> String {
    xml_timestamp(time)
        .split_once('T')
        .map(|(date, _)| date.to_owned())
        .unwrap_or_else(|| "1970-01-01".to_owned())
}
fn xml_escape(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '&' => escaped.push_str("&amp;"),
            '<' => escaped.push_str("&lt;"),
            '>' => escaped.push_str("&gt;"),
            '"' => escaped.push_str("&quot;"),
            '\'' => escaped.push_str("&apos;"),
            _ => escaped.push(ch),
        }
    }
    escaped
}
fn insert_iso_metadata_fields(
    payload: &mut norito::json::native::Map,
    status: &crate::iso20022_bridge::IsoMessageStatus,
) {
    let metadata = status.metadata();
    payload.insert(
        "profile_id".into(),
        json_string_or_null(metadata.profile_id().map(str::to_string)),
    );
    payload.insert(
        "message_type".into(),
        json_string_or_null(metadata.message_type().map(str::to_string)),
    );
    payload.insert(
        "business_service".into(),
        json_string_or_null(metadata.business_service().map(str::to_string)),
    );
    payload.insert(
        "business_message_id".into(),
        json_string_or_null(metadata.business_message_id().map(str::to_string)),
    );
    payload.insert(
        "uetr".into(),
        json_string_or_null(metadata.uetr().map(str::to_string)),
    );
    payload.insert(
        "payload_hash".into(),
        json_string_or_null(metadata.payload_hash().map(str::to_string)),
    );
    payload.insert(
        "reference_snapshot_id".into(),
        json_string_or_null(metadata.reference_snapshot_id().map(str::to_string)),
    );
    payload.insert(
        "embedded_signature_detected".into(),
        norito::json::native::Value::from(metadata.embedded_signature_detected()),
    );
    payload.insert(
        "originator_participant_id".into(),
        norito::json::native::Value::from(status.originator_participant_id().to_owned()),
    );
    payload.insert(
        "counterparty_participant_id".into(),
        norito::json::native::Value::from(status.counterparty_participant_id().to_owned()),
    );
    payload.insert(
        "admitting_participant_id".into(),
        norito::json::native::Value::from(status.admitting_participant_id().to_owned()),
    );
    payload.insert(
        "admitting_operator_key".into(),
        norito::json::native::Value::from(status.admitting_operator_key().to_owned()),
    );
    payload.insert(
        "pinned_profile_id".into(),
        norito::json::native::Value::from(status.pinned_profile_id().to_owned()),
    );
    payload.insert(
        "pinned_signature_policy".into(),
        norito::json::native::Value::from(status.pinned_signature_policy().to_owned()),
    );
    let status_history = status
        .status_history()
        .iter()
        .map(|entry| {
            let mut item = norito::json::native::Map::new();
            item.insert(
                "status".into(),
                norito::json::native::Value::from(entry.status_label().to_string()),
            );
            item.insert(
                "pacs002_code".into(),
                norito::json::native::Value::from(entry.pacs002_code().to_string()),
            );
            let updated_at_ms = entry
                .updated_at()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis().min(u128::from(u64::MAX)) as u64)
                .unwrap_or(0);
            item.insert(
                "updated_at_ms".into(),
                norito::json::native::Value::from(updated_at_ms),
            );
            item.insert(
                "detail".into(),
                json_string_or_null(entry.detail().map(str::to_string)),
            );
            item.insert(
                "reason_code".into(),
                json_string_or_null(entry.reason_code().map(str::to_string)),
            );
            norito::json::native::Value::Object(item)
        })
        .collect::<Vec<_>>();
    payload.insert(
        "status_history".into(),
        norito::json::native::Value::Array(status_history),
    );
}
fn map_iso_error(err: MsgError) -> iroha_data_model::ValidationFail {
    use iroha_data_model::ValidationFail;
    match err {
        MsgError::ValidationFailed => {
            ValidationFail::NotPermitted("ISO 20022 validation failed".into())
        }
        MsgError::MissingField(field) => {
            ValidationFail::NotPermitted(format!("missing ISO 20022 field `{field}`"))
        }
        MsgError::TooManyOccurrences { field, max, actual } => ValidationFail::NotPermitted(
            format!("field `{field}` exceeds max occurrences ({actual} > {max})"),
        ),
        MsgError::InvalidIdentifier { field, kind } => {
            ValidationFail::NotPermitted(format!("invalid {kind} value for field `{field}`"))
        }
        MsgError::InvalidInstrument { field } => ValidationFail::NotPermitted(format!(
            "field `{field}` must contain a valid ISIN or CUSIP identifier"
        )),
        MsgError::InvalidValue { field, kind } => {
            ValidationFail::NotPermitted(format!("invalid {kind} value for field `{field}`"))
        }
        MsgError::InvalidFormat => {
            ValidationFail::NotPermitted("ISO 20022 message format is invalid".into())
        }
        MsgError::UnknownMessageType => {
            ValidationFail::NotPermitted("unsupported ISO 20022 message type".into())
        }
        MsgError::NoActiveMessage => {
            ValidationFail::InternalError("ISO 20022 parser stack underflow".into())
        }
    }
}
fn map_iso_admission_error(error: crate::iso20022_bridge::IsoAdmissionError) -> Error {
    use crate::iso20022_bridge::IsoAdmissionError;
    match error {
        IsoAdmissionError::Duplicate => Error::Query(
            iroha_data_model::ValidationFail::NotPermitted(
                "duplicate ISO 20022 replay identity".into(),
            ),
        ),
        IsoAdmissionError::NotAuthorized => Error::Query(
            iroha_data_model::ValidationFail::NotPermitted(
                "ISO 20022 participant authorization failed".into(),
            ),
        ),
        IsoAdmissionError::ProtectedCapacity => Error::AppServiceUnavailable {
            code: "iso_replay_capacity_protected",
            message: "ISO replay capacity contains only unexpired protected identities; retry after the deduplication TTL"
                .to_owned(),
        },
        IsoAdmissionError::PersistenceUnavailable => Error::AppServiceUnavailable {
            code: "iso_admission_persistence_unavailable",
            message: "ISO admission could not be persisted before processing".to_owned(),
        },
    }
}
#[cfg(feature = "app_api")]
async fn handler_post_vk_register(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    request: NoritoJson<crate::routing::ZkVkRegisterDto>,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    if limits::is_allowed_by_cidr(&headers, Some(remote_ip), &app.api_rate_limit_bypass_nets) {
        return crate::routing::handle_post_vk_register(
            app.queue.clone(),
            app.state.clone(),
            request,
        )
        .await
        .map(IntoResponse::into_response);
    }
    validate_api_token(app.as_ref(), &headers)?;
    let key = rate_limit_key(
        &headers,
        Some(remote_ip),
        "v1/zk/vk/register",
        app.authenticated_api_token_principal(&headers),
    );
    let enforce =
        app.fee_policy.is_enabled() || app.queue.active_len() >= app.high_load_tx_threshold;
    if !limits::allow_conditionally(&app.rate_limiter, &key, enforce).await {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
        )));
    }
    crate::routing::handle_post_vk_register(app.queue.clone(), app.state.clone(), request)
        .await
        .map(IntoResponse::into_response)
}
