#[cfg(feature = "connect")]
async fn enforce_connect_session_create_admission(
    State(app): State<SharedAppState>,
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Response {
    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }
    let remote_ip = match connect_remote_ip_from_headers(req.headers()) {
        Ok(ip) => ip,
        Err(message) => return (StatusCode::BAD_REQUEST, message).into_response(),
    };
    if let Err((status, message)) = app.connect_bus.pre_session_create(remote_ip).await {
        return connect_session_rejection_response(status, "connect_session_rate_limited", message);
    }
    req.extensions_mut().insert(ConnectSessionCreateAdmitted);
    next.run(req).await
}
#[cfg(feature = "connect")]
async fn enforce_connect_ws_admission(
    State(app): State<SharedAppState>,
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Response {
    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }
    let remote_ip = match connect_remote_ip_from_headers(req.headers()) {
        Ok(ip) => ip,
        Err(message) => return (StatusCode::BAD_REQUEST, message).into_response(),
    };
    let permit = match app.connect_bus.pre_ws_handshake(remote_ip).await {
        Ok(permit) => permit,
        Err((status, message)) => return (status, message).into_response(),
    };
    req.extensions_mut()
        .insert(ConnectWsPermitHandoff::new(permit));
    next.run(req).await
}
#[cfg(feature = "connect")]
async fn handle_connect_ws_logic(
    app: SharedAppState,
    headers: axum::http::HeaderMap,
    q: routing::ConnectWsQuery,
    ws: WebSocketUpgrade,
    preauth_guard: Option<Extension<PreAuthGuardHandoff>>,
    mut permit: crate::connect::WsPermit,
) -> axum::response::Response {
    let bus = app.connect_bus.clone();
    let send_timeout = app.ws_message_timeout;
    let sid = match crate::connect::decode_sid(&q.sid) {
        Ok(sid) => sid,
        Err(_) => {
            permit.release().await;
            return (StatusCode::BAD_REQUEST, "connect: bad sid").into_response();
        }
    };
    let role = match q.role.as_str() {
        "app" => iroha_torii_shared::connect::Role::App,
        "wallet" => iroha_torii_shared::connect::Role::Wallet,
        other => {
            permit.release().await;
            return (
                StatusCode::BAD_REQUEST,
                format!("connect: bad role {other}"),
            )
                .into_response();
        }
    };
    let token = match resolve_connect_ws_token(&headers) {
        Ok(token) => token,
        Err(response) => {
            permit.release().await;
            return response;
        }
    };
    let reservation = match bus.reserve_token(sid, role, &token.token).await {
        Ok(reservation) => reservation,
        Err((code, msg)) => {
            permit.release().await;
            return (code, msg).into_response();
        }
    };
    let ws = bus.configure_websocket(ws);
    let ws = if let Some(protocol) = token.protocol {
        ws.protocols([protocol])
    } else {
        ws
    };
    let preauth_guard = take_preauth_upgrade_guard(preauth_guard);
    let shutdown = app.shutdown_signal.clone();
    ws.on_upgrade(move |ws| async move {
        let _ = crate::panic_recovery::catch_async_recoverable(async move {
            let _preauth_guard = preauth_guard;
            let result = tokio::select! {
                () = shutdown.receive() => Ok(()),
                result = connect::handle_ws(bus, reservation, ws, send_timeout) => result,
            };
            permit.release().await;
            if let Err(e) = result {
                iroha_logger::warn!(%e, "connect ws session ended with error");
            }
        })
        .await;
    })
}
#[cfg(feature = "connect")]
#[allow(dead_code)]
fn _assert_websocket_send() {
    fn assert_send<T: Send>() {}
    fn assert_sync<T: Sync>() {}
    assert_send::<WebSocketUpgrade>();
    assert_sync::<WebSocketUpgrade>();
}
#[cfg(feature = "connect")]
fn require_connect_enabled(app: &SharedAppState) -> Result<(), Error> {
    if app.connect_enabled {
        Ok(())
    } else {
        Err(Error::AppServiceUnavailable {
            code: "connect_disabled",
            message: "Iroha Connect is disabled by node configuration".to_owned(),
        })
    }
}
#[cfg(feature = "connect")]
async fn handler_connect_ws(
    State(app): State<SharedAppState>,
    preauth_guard: Option<Extension<PreAuthGuardHandoff>>,
    Extension(permit_handoff): Extension<ConnectWsPermitHandoff>,
    headers: axum::http::HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    ws: WebSocketUpgrade,
) -> axum::response::Response {
    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }
    let query = match parse_connect_ws_query(raw_query.as_deref()) {
        Ok(q) => q,
        Err(response) => return response,
    };
    let Some(permit) = permit_handoff.take() else {
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            "connect: websocket admission permit unavailable",
        )
            .into_response();
    };
    handle_connect_ws_logic(app, headers, query, ws, preauth_guard, permit).await
}
#[cfg(feature = "connect")]
fn connect_session_rejection_response(
    status: StatusCode,
    code: &'static str,
    message: impl Into<String>,
) -> Response {
    let retry_after_seconds = (status == StatusCode::TOO_MANY_REQUESTS).then_some(1);
    let payload = ErrorEnvelope::new(code, message.into()).with_details(ErrorDetails {
        retry_after_seconds,
        ..Default::default()
    });
    let mut response =
        utils::respond_with_status_and_format(status, payload, utils::current_response_format());
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-reject-code"),
        HeaderValue::from_static(code),
    );
    if retry_after_seconds.is_some() {
        response.headers_mut().insert(
            axum::http::header::RETRY_AFTER,
            HeaderValue::from_static("1"),
        );
    }
    response
}
#[cfg(feature = "connect")]
async fn handler_connect_session(
    State(app): State<SharedAppState>,
    Extension(_admitted): Extension<ConnectSessionCreateAdmitted>,
    NoritoJson(req): NoritoJson<routing::ConnectSessionRequest>,
) -> Result<Response> {
    use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD as B64};
    require_connect_enabled(&app)?;
    let network_id = *app.state.network_id_ref();
    let JsonBody(response) = routing::handle_connect_session(network_id, NoritoJson(req)).await?;
    let malformed = |msg: String| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(msg),
        ))
    };
    let sid_bytes = B64
        .decode(response.sid.as_bytes())
        .map_err(|err| malformed(format!("connect session sid decode failed: {err}")))?;
    let sid: crate::connect::Sid = sid_bytes
        .try_into()
        .map_err(|_| malformed("connect session sid had wrong length".into()))?;
    let app_pk: [u8; 32] = B64
        .decode(response.app_pk.as_bytes())
        .map_err(|err| malformed(format!("connect session app key decode failed: {err}")))?
        .try_into()
        .map_err(|_| malformed("connect session app key had wrong length".into()))?;
    let nonce: [u8; 16] = B64
        .decode(response.nonce.as_bytes())
        .map_err(|err| malformed(format!("connect session nonce decode failed: {err}")))?
        .try_into()
        .map_err(|_| malformed("connect session nonce had wrong length".into()))?;
    if let Err(error) = app
        .connect_bus
        .clone()
        .register_tokens(
            sid,
            app_pk,
            nonce,
            response.token_app.clone(),
            response.token_wallet.clone(),
            response.token_management.clone(),
            response.token_relay.clone(),
        )
        .await
    {
        let response = match error {
            crate::connect::RegisterSessionError::Exists => connect_session_rejection_response(
                StatusCode::CONFLICT,
                "connect_session_exists",
                "connect session already exists for provided sid",
            ),
            crate::connect::RegisterSessionError::Capacity => connect_session_rejection_response(
                StatusCode::TOO_MANY_REQUESTS,
                "connect_session_capacity",
                "connect session capacity reached; try again later",
            ),
            crate::connect::RegisterSessionError::InvalidIdentity => {
                connect_session_rejection_response(
                    StatusCode::BAD_REQUEST,
                    "connect_session_identity_invalid",
                    "connect session identity was not canonically bound",
                )
            }
        };
        return Ok(response);
    }
    Ok(JsonBody(response).into_response())
}
#[cfg(feature = "connect")]
async fn handler_connect_session_delete(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::Path(sid_str): axum::extract::Path<String>,
) -> axum::response::Response {
    use axum::http::StatusCode;
    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }
    match crate::connect::decode_sid(&sid_str) {
        Ok(sid) => {
            let token = match parse_authorization_token(&headers) {
                Ok(Some(token)) => token,
                Ok(None) => {
                    return (
                        StatusCode::UNAUTHORIZED,
                        "connect: missing management token",
                    )
                        .into_response();
                }
                Err(response) => return response,
            };
            let removed = app
                .connect_bus
                .clone()
                .terminate_session_authorized(sid, &token, crate::connect::CLOSE_REASON_PURGED)
                .await;
            if removed {
                StatusCode::NO_CONTENT.into_response()
            } else {
                StatusCode::NOT_FOUND.into_response()
            }
        }
        Err(_) => (StatusCode::BAD_REQUEST, "connect: bad sid").into_response(),
    }
}
#[cfg(feature = "connect")]
#[allow(clippy::result_large_err)]
fn parse_connect_ws_query(
    raw: Option<&str>,
) -> Result<routing::ConnectWsQuery, axum::response::Response> {
    use axum::http::StatusCode;
    let mut sid = None;
    let mut role = None;
    let Some(qs) = raw.filter(|query| !query.is_empty()) else {
        return Err((StatusCode::BAD_REQUEST, "connect query missing sid/role").into_response());
    };
    for pair in qs.split('&') {
        let Some((key, value)) = pair.split_once('=') else {
            return Err(
                (StatusCode::BAD_REQUEST, "connect query must use key=value").into_response(),
            );
        };
        if key.is_empty()
            || value.is_empty()
            || key.contains('%')
            || key.contains('+')
            || value.contains('%')
            || value.contains('+')
        {
            return Err((StatusCode::BAD_REQUEST, "connect query is not canonical").into_response());
        }
        let slot = match key {
            "sid" => &mut sid,
            "role" => &mut role,
            "token" => {
                return Err((
                    StatusCode::BAD_REQUEST,
                    "connect query must not include token; use Authorization or Sec-WebSocket-Protocol",
                )
                    .into_response());
            }
            _ => {
                return Err(
                    (StatusCode::BAD_REQUEST, "connect query has unknown key").into_response()
                );
            }
        };
        if slot.replace(value.to_owned()).is_some() {
            return Err(
                (StatusCode::BAD_REQUEST, "connect query has duplicate key").into_response()
            );
        }
    }
    let (Some(sid), Some(role)) = (sid, role) else {
        return Err((StatusCode::BAD_REQUEST, "connect query missing sid/role").into_response());
    };
    if role != "app" && role != "wallet" {
        return Err((StatusCode::BAD_REQUEST, "connect query has invalid role").into_response());
    }
    Ok(routing::ConnectWsQuery { sid, role })
}
#[cfg(feature = "connect")]
const CONNECT_PROTOCOL_TOKEN_PREFIX: &str = "iroha-connect.token.v1.";
#[cfg(feature = "connect")]
#[derive(Debug)]
struct ConnectWsToken {
    token: String,
    protocol: Option<String>,
}
#[cfg(feature = "connect")]
#[derive(Debug)]
struct ProtocolToken {
    token: String,
    protocol: String,
}
#[cfg(feature = "connect")]
#[allow(clippy::result_large_err)]
fn resolve_connect_ws_token(
    headers: &axum::http::HeaderMap,
) -> Result<ConnectWsToken, axum::response::Response> {
    use axum::http::StatusCode;
    let auth_token = parse_authorization_token(headers)?;
    let protocol_token = parse_protocol_token(headers)?;
    if let Some(auth) = auth_token {
        if let Some(proto) = protocol_token.as_ref() {
            if proto.token != auth {
                return Err((
                    StatusCode::BAD_REQUEST,
                    "connect: conflicting tokens in Authorization and Sec-WebSocket-Protocol headers",
                )
                    .into_response());
            }
            return Ok(ConnectWsToken {
                token: auth,
                protocol: Some(proto.protocol.clone()),
            });
        }
        return Ok(ConnectWsToken {
            token: auth,
            protocol: None,
        });
    }
    if let Some(proto) = protocol_token {
        return Ok(ConnectWsToken {
            token: proto.token,
            protocol: Some(proto.protocol),
        });
    }
    Err((
        StatusCode::BAD_REQUEST,
        "connect: missing token; send Authorization: Bearer <token> or Sec-WebSocket-Protocol: iroha-connect.token.v1.<base64url>",
    )
        .into_response())
}
#[cfg(feature = "connect")]
#[allow(clippy::result_large_err)]
fn parse_authorization_token(
    headers: &axum::http::HeaderMap,
) -> Result<Option<String>, axum::response::Response> {
    use axum::http::{StatusCode, header};
    let mut values = headers.get_all(header::AUTHORIZATION).iter();
    let Some(value) = values.next() else {
        return Ok(None);
    };
    if values.next().is_some() {
        return Err((
            StatusCode::BAD_REQUEST,
            "connect: authorization header must appear exactly once",
        )
            .into_response());
    }
    let value_str = value
        .to_str()
        .map_err(|_| {
            (
                StatusCode::BAD_REQUEST,
                "connect: invalid authorization header",
            )
                .into_response()
        })?
        .trim();
    let mut parts = value_str.split_whitespace();
    let scheme = parts.next().unwrap_or_default();
    let token = parts.next().unwrap_or("");
    if parts.next().is_some() {
        return Err((
            StatusCode::BAD_REQUEST,
            "connect: malformed authorization header",
        )
            .into_response());
    }
    if !scheme.eq_ignore_ascii_case("bearer") {
        return Err((
            StatusCode::BAD_REQUEST,
            "connect: authorization header must use Bearer scheme",
        )
            .into_response());
    }
    let token = token.trim();
    if token.is_empty() {
        return Err((StatusCode::BAD_REQUEST, "connect: bearer token is empty").into_response());
    }
    Ok(Some(token.to_owned()))
}
#[cfg(feature = "connect")]
#[allow(clippy::result_large_err)]
fn parse_protocol_token(
    headers: &axum::http::HeaderMap,
) -> Result<Option<ProtocolToken>, axum::response::Response> {
    use axum::http::{StatusCode, header};
    let mut values_iter = headers.get_all(header::SEC_WEBSOCKET_PROTOCOL).iter();
    let Some(first_value) = values_iter.next() else {
        return Ok(None);
    };
    for value in std::iter::once(first_value).chain(values_iter) {
        let value_str = value
            .to_str()
            .map_err(|_| {
                (
                    StatusCode::BAD_REQUEST,
                    "connect: invalid Sec-WebSocket-Protocol header",
                )
                    .into_response()
            })?
            .trim();
        for entry in value_str.split(',') {
            let candidate = entry.trim();
            if let Some(encoded) = candidate.strip_prefix(CONNECT_PROTOCOL_TOKEN_PREFIX) {
                let token = decode_protocol_token(encoded)?;
                return Ok(Some(ProtocolToken {
                    token,
                    protocol: candidate.to_string(),
                }));
            }
        }
    }
    Ok(None)
}
#[cfg(feature = "connect")]
#[allow(clippy::result_large_err)]
fn decode_protocol_token(encoded: &str) -> Result<String, axum::response::Response> {
    use axum::http::StatusCode;
    use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD as B64};
    let bytes = B64.decode(encoded).map_err(|_| {
        (
            StatusCode::BAD_REQUEST,
            "connect: invalid protocol token encoding",
        )
            .into_response()
    })?;
    if bytes.is_empty() {
        return Err((StatusCode::BAD_REQUEST, "connect: protocol token is empty").into_response());
    }
    String::from_utf8(bytes).map_err(|_| {
        (
            StatusCode::BAD_REQUEST,
            "connect: protocol token must be valid utf-8",
        )
            .into_response()
    })
}
#[cfg(feature = "connect")]
async fn handler_connect_session_status(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> axum::response::Response {
    use axum::http::StatusCode;
    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }
    let sid_query = match connect_status::parse_session_status_sid(raw_query.as_deref()) {
        Ok(sid) => sid,
        Err(message) => return (StatusCode::BAD_REQUEST, message).into_response(),
    };
    let sid = match crate::connect::decode_sid(&sid_query) {
        Ok(sid) => sid,
        Err(_) => return (StatusCode::BAD_REQUEST, "connect: bad sid").into_response(),
    };
    let token = match parse_authorization_token(&headers) {
        Ok(Some(token)) => token,
        Ok(None) => {
            return (
                StatusCode::UNAUTHORIZED,
                "connect: missing management token",
            )
                .into_response();
        }
        Err(response) => return response,
    };
    match app.connect_bus.session_status(sid, &token).await {
        Some(status) => JsonBody(status).into_response(),
        None => StatusCode::NOT_FOUND.into_response(),
    }
}
#[cfg(feature = "connect")]
async fn handler_connect_status(State(app): State<SharedAppState>) -> axum::response::Response {
    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }
    let status = app.connect_bus.status().await;
    #[cfg(feature = "telemetry")]
    {
        if app.telemetry.allows_metrics() {
            let metrics = app.telemetry.metrics().await;
            metrics
                .torii_connect_sessions_total
                .set(status.sessions_total as u64);
            metrics
                .torii_connect_sessions_active
                .set(status.sessions_active as u64);
            metrics
                .torii_connect_buffered_sessions
                .set(status.buffered_sessions as u64);
            metrics
                .torii_connect_total_buffer_bytes
                .set(status.total_buffer_bytes as u64);
            metrics
                .torii_connect_dedupe_size
                .set(status.dedupe_size as u64);
            for entry in &status.per_ip_sessions {
                metrics
                    .torii_connect_per_ip_sessions
                    .with_label_values(&[entry.ip.as_str()])
                    .set(entry.sessions as u64);
            }
        }
    }
    let mut redacted_status = status;
    redacted_status.per_ip_sessions.clear();
    JsonBody(redacted_status).into_response()
}
#[cfg(feature = "app_api")]
fn require_signed_alias_request(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
) -> Result<AccountId, Error> {
    require_signed_account_request(
        app,
        headers,
        method,
        uri,
        body,
        "alias_auth_required",
        "signed account headers are required",
    )
}
#[cfg(feature = "app_api")]
#[allow(clippy::too_many_arguments)]
fn require_signed_account_request(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
    error_code: &'static str,
    error_message: &'static str,
) -> Result<AccountId, Error> {
    let authentication_owner =
        match crate::history_producer::HistoryProducerOwner::authentication_read(&app) {
            Ok(owner) => owner,
            Err(error) => {
                return Err(error);
            }
        };

    match crate::app_auth::verify_canonical_network_request(
        &app.state,
        app.state.network_id_ref(),
        headers,
        method,
        uri,
        body,
        None,
        authentication_owner.allocation_context(),
    )? {
        Some(verified) => Ok(verified.account),
        None => Err(Error::AppUnauthorized {
            code: error_code,
            message: error_message.to_owned(),
        }),
    }
}
#[cfg(feature = "app_api")]
fn multisig_alias_resolve_authority(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
    _selector: &routing::MultisigAccountSelectorDto,
) -> Result<Option<AccountId>, Error> {
    // Multisig authority specs and proposals are sensitive authorization state. Require the
    // canonical account signature for both alias and concrete-account selectors so switching
    // selector shape can never downgrade an authenticated read to an anonymous one.
    require_signed_account_request(
        app,
        headers,
        method,
        uri,
        body,
        "multisig_read_auth_required",
        "signed account headers are required to read multisig authority state",
    )
    .map(Some)
}
#[cfg(feature = "app_api")]
fn alias_setup_plan_report_response(
    status_code: StatusCode,
    status: iroha_data_model::alias_setup::AliasSetupStatusV1,
    code: impl Into<String>,
    resource: Option<String>,
    expected: Option<String>,
    actual: Option<String>,
    remediation: impl Into<String>,
) -> AxResponse {
    use iroha_data_model::alias_setup::{
        AliasSetupDiagnosticV1, AliasSetupReportV1, AliasSetupSeverityV1,
        AliasSetupValidationPhaseV1,
    };
    let report = AliasSetupReportV1::new(
        status,
        vec![AliasSetupDiagnosticV1 {
            phase: AliasSetupValidationPhaseV1::Planning,
            code: code.into(),
            severity: if status == iroha_data_model::alias_setup::AliasSetupStatusV1::Pending {
                AliasSetupSeverityV1::Warning
            } else {
                AliasSetupSeverityV1::Error
            },
            resource,
            config_path: None,
            expected,
            actual,
            remediation: remediation.into(),
        }],
    );
    alias_setup_report_error_response(status_code, report)
}
#[cfg(feature = "app_api")]
fn alias_setup_report_error_response(
    status_code: StatusCode,
    report: iroha_data_model::alias_setup::AliasSetupReportV1,
) -> AxResponse {
    use iroha_torii_shared::aliases::{ALIAS_SETUP_PENDING_CODE, ALIAS_SETUP_REJECTED_CODE};
    let (code, message) =
        if report.status == iroha_data_model::alias_setup::AliasSetupStatusV1::Pending {
            (
                ALIAS_SETUP_PENDING_CODE,
                "Alias planning is awaiting committed ledger state.",
            )
        } else {
            (
                ALIAS_SETUP_REJECTED_CODE,
                "Alias planning was rejected; inspect the typed diagnostics.",
            )
        };
    let envelope = ErrorEnvelope::new(code, message).with_details(ErrorDetails {
        alias_setup_report: Some(report),
        ..Default::default()
    });
    (status_code, JsonBody(envelope)).into_response()
}
#[cfg(feature = "app_api")]
fn alias_setup_dependency_rank(intent: &iroha_data_model::alias_setup::AliasIntentV1) -> u8 {
    use iroha_data_model::alias_setup::AliasIntentV1;
    match intent {
        AliasIntentV1::Dataspace(_) => 0,
        AliasIntentV1::Domain(_) => 1,
        AliasIntentV1::AccountAlias(_) => 2,
    }
}
#[cfg(feature = "app_api")]
fn alias_setup_parent_target(
    target: &iroha_data_model::alias_setup::AliasTargetV1,
) -> Option<iroha_data_model::alias_setup::AliasTargetV1> {
    use iroha_data_model::alias_setup::{AliasTargetV1, ResolvedDataSpaceV1};
    match target {
        AliasTargetV1::Dataspace(_) => None,
        AliasTargetV1::Domain(domain) => Some(AliasTargetV1::Dataspace(domain.parent_dataspace())),
        AliasTargetV1::AccountAlias(alias) => alias
            .parent_domain()
            .map(AliasTargetV1::Domain)
            .or_else(|| {
                Some(AliasTargetV1::Dataspace(ResolvedDataSpaceV1::new(
                    alias.canonical_name.dataspace.clone(),
                    alias.dataspace_id,
                )))
            }),
    }
}
#[cfg(feature = "app_api")]
fn alias_setup_parent_expiry_warning(
    child: &iroha_data_model::alias_setup::AliasTargetV1,
    parent: &iroha_data_model::alias_setup::AliasTargetV1,
    child_expiry_ms: u64,
    parent_expiry_ms: u64,
) -> Option<iroha_data_model::alias_setup::AliasSetupDiagnosticV1> {
    use iroha_data_model::alias_setup::{
        AliasSetupDiagnosticV1, AliasSetupSeverityV1, AliasSetupValidationPhaseV1,
    };
    (parent_expiry_ms < child_expiry_ms).then(|| AliasSetupDiagnosticV1 {
        phase: AliasSetupValidationPhaseV1::Planning,
        code: "alias.plan.parent_lease_expires_first".to_owned(),
        severity: AliasSetupSeverityV1::Warning,
        resource: Some(child.to_string()),
        config_path: None,
        expected: Some(format!(
            "parent `{parent}` expiry at or after {child_expiry_ms}"
        )),
        actual: Some(format!("parent expiry {parent_expiry_ms}")),
        remediation:
            "renew the parent lease explicitly if the child must remain routable for its full term"
                .to_owned(),
    })
}
#[cfg(feature = "app_api")]
fn alias_setup_transaction_size_blocker(
    canonical_unsigned_payload_bytes: usize,
    maximum_transaction_bytes: usize,
) -> Option<iroha_data_model::alias_setup::AliasSetupDiagnosticV1> {
    use iroha_data_model::alias_setup::{
        AliasSetupDiagnosticV1, AliasSetupSeverityV1, AliasSetupValidationPhaseV1,
    };
    (canonical_unsigned_payload_bytes > maximum_transaction_bytes).then(|| {
        AliasSetupDiagnosticV1 {
            phase: AliasSetupValidationPhaseV1::Planning,
            code: "alias.plan.transaction_oversized".to_owned(),
            severity: AliasSetupSeverityV1::Error,
            resource: None,
            config_path: None,
            expected: Some(format!(
                "canonical unsigned transaction payload no larger than {maximum_transaction_bytes} bytes"
            )),
            actual: Some(format!(
                "canonical unsigned transaction payload is {canonical_unsigned_payload_bytes} bytes"
            )),
            remediation:
                "reduce the declarative setup intent; the planner will never split it into multiple transactions"
                    .to_owned(),
        }
    })
}
#[cfg(feature = "app_api")]
const ALIAS_PLAN_TTL_MS: u64 = 60_000;
#[cfg(feature = "app_api")]
fn alias_plan_deadline(
    request_time: SystemTime,
    guarded_deadline_ms: Option<u64>,
) -> Result<u64, Error> {
    // This is a client-observed request expiry, not consensus lease time. An idle chain's
    // latest block remains the exact plan anchor but must not expire a newly requested plan.
    let request_time_ms = request_time
        .duration_since(UNIX_EPOCH)
        .ok()
        .and_then(|duration| u64::try_from(duration.as_millis()).ok())
        .ok_or_else(|| Error::AppServiceUnavailable {
            code: "alias.plan.clock_unavailable",
            message: "alias planner wall clock is outside the supported Unix time range".to_owned(),
        })?;
    let planner_deadline_ms = request_time_ms.saturating_add(ALIAS_PLAN_TTL_MS);
    Ok(
        guarded_deadline_ms.map_or(planner_deadline_ms, |guarded_deadline_ms| {
            planner_deadline_ms.min(guarded_deadline_ms)
        }),
    )
}
#[cfg(feature = "app_api")]
async fn handler_alias_setup_plan(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    use iroha_core::alias_setup::classify_alias_intent_with_planned_parents_and_endorsement_policy;
    use iroha_data_model::{
        alias_setup::{
            AliasAssetTotalV1, AliasFramedInstructionV1, AliasLeaseQuoteV1, AliasPlanAnchorV1,
            AliasPlanResourceV1, AliasSetupPlanRequestV1, AliasSetupStatusV1,
            AliasTransactionPlanBodyV1, AliasTransactionPlanV1,
        },
        isi::{InstructionBox, alias_setup::EnsureAlias},
    };
    check_public_contract_read_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/aliases/setup/plan",
        "alias_setup_plan",
        None,
    )
    .await?;
    let authority = require_signed_alias_request(&app, &headers, &method, &uri, body.as_ref())?;
    let mut request: AliasSetupPlanRequestV1 =
        norito::json::from_slice(body.as_ref()).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(error.to_string()),
            ))
        })?;
    if request.schema_version != AliasSetupPlanRequestV1::VERSION {
        return Ok(alias_setup_plan_report_response(
            StatusCode::BAD_REQUEST,
            AliasSetupStatusV1::Blocked,
            "alias.plan.version_unsupported",
            None,
            Some(AliasSetupPlanRequestV1::VERSION.to_string()),
            Some(request.schema_version.to_string()),
            "encode the request using the supported AliasSetupPlanRequestV1 layout",
        ));
    }
    if request.intents.is_empty() {
        return Ok(alias_setup_plan_report_response(
            StatusCode::BAD_REQUEST,
            AliasSetupStatusV1::Blocked,
            "alias.plan.empty",
            None,
            Some("at least one EnsureAlias intent".to_owned()),
            Some("zero intents".to_owned()),
            "add the dataspace, domain, or account-alias resource to the setup request",
        ));
    }
    request.intents.sort_by(|left, right| {
        alias_setup_dependency_rank(&left.intent)
            .cmp(&alias_setup_dependency_rank(&right.intent))
            .then_with(|| left.intent.target().cmp(&right.intent.target()))
    });
    let mut targets = BTreeSet::new();
    for ensure in &request.intents {
        let target = ensure.intent.target();
        if !targets.insert(target.clone()) {
            return Ok(alias_setup_plan_report_response(
                StatusCode::CONFLICT,
                AliasSetupStatusV1::Blocked,
                "alias.plan.duplicate_resource",
                Some(target.to_string()),
                Some("one exact intent per resource".to_owned()),
                Some("duplicate resource".to_owned()),
                "remove the duplicate intent and request a new plan",
            ));
        }
    }
    let state_view = app.state.view();
    let Some(latest_block) = state_view
        .latest_block()
        .map_err(crate::canonical_history::canonical_attempt_error)?
    else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            None,
            Some("a committed block anchor".to_owned()),
            Some("no committed block".to_owned()),
            "wait for bootstrap or block synchronization, then request a new plan",
        ));
    };
    let Some(latest_block_hash) = state_view.latest_block_hash() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            None,
            Some("a canonical committed block hash".to_owned()),
            Some("block hash unavailable".to_owned()),
            "wait for block synchronization, then request a new plan",
        ));
    };
    let now_ms =
        u64::try_from(latest_block.header().creation_time().as_millis()).unwrap_or(u64::MAX);
    let world = state_view.world();
    let nexus = state_view.nexus();
    let catalog = &nexus.dataspace_catalog;
    let default_domain_endorsement_required = nexus.endorsement.quorum > 0;
    let mut resources = Vec::with_capacity(request.intents.len());
    let mut instructions = Vec::with_capacity(request.intents.len());
    let mut transaction_instructions = Vec::with_capacity(request.intents.len());
    let mut totals = BTreeMap::<AssetDefinitionId, Quantity>::new();
    let mut planned_dataspaces = BTreeMap::new();
    let mut planned_domains = BTreeSet::new();
    let mut planned_authority_dataspaces = BTreeSet::new();
    let mut planned_authority_domains = BTreeSet::new();
    let mut planned_expiries = BTreeMap::new();
    let mut warnings = Vec::new();
    let mut valid_until_ms = alias_plan_deadline(SystemTime::now(), None)?;
    for (index, ensure) in request.intents.into_iter().enumerate() {
        let target = ensure.intent.target();
        let disposition = match classify_alias_intent_with_planned_parents_and_endorsement_policy(
            world,
            catalog,
            &planned_dataspaces,
            &planned_domains,
            &ensure.intent,
            now_ms,
            default_domain_endorsement_required,
        ) {
            Ok(disposition) => disposition,
            Err(error) => {
                return Ok(alias_setup_plan_report_response(
                    StatusCode::CONFLICT,
                    AliasSetupStatusV1::Blocked,
                    error.code(),
                    Some(target.to_string()),
                    None,
                    Some(error.message().to_owned()),
                    "resolve the reported drift explicitly, then request a new plan",
                ));
            }
        };
        let authorized_by_planned_parent = match &ensure.intent {
            iroha_data_model::alias_setup::AliasIntentV1::AccountAlias(intent) => {
                intent.alias.canonical_name.domain_id().map_or_else(
                    || planned_authority_dataspaces.contains(&intent.alias.dataspace_id),
                    |domain| planned_authority_domains.contains(&domain),
                )
            }
            _ => false,
        };
        if matches!(
            disposition,
            iroha_data_model::alias_setup::AliasPlanDispositionV1::Repair
                | iroha_data_model::alias_setup::AliasPlanDispositionV1::Create
        ) && !authorized_by_planned_parent
            && let Err(error) = iroha_core::alias_setup::validate_alias_intent_authority(
                world,
                &authority,
                &ensure.intent,
            )
        {
            return Ok(alias_setup_plan_report_response(
                StatusCode::FORBIDDEN,
                AliasSetupStatusV1::Blocked,
                error.code(),
                Some(target.to_string()),
                Some("the resource owner or exact applicable management scope".to_owned()),
                Some(authority.to_string()),
                "use the resource owner as transaction authority or grant the exact management scope, then request a new plan",
            ));
        }
        if iroha_core::alias_setup::alias_intent_owner(&ensure.intent) == &authority {
            match &ensure.intent {
                iroha_data_model::alias_setup::AliasIntentV1::Dataspace(intent) => {
                    planned_authority_dataspaces.insert(intent.dataspace.dataspace_id);
                }
                iroha_data_model::alias_setup::AliasIntentV1::Domain(intent) => {
                    planned_authority_domains.insert(intent.domain.canonical_name.clone());
                }
                iroha_data_model::alias_setup::AliasIntentV1::AccountAlias(_) => {}
            }
        }
        if let iroha_data_model::alias_setup::AliasIntentV1::Dataspace(intent) = &ensure.intent {
            planned_dataspaces.insert(
                intent.dataspace.canonical_name.clone(),
                intent.dataspace.dataspace_id,
            );
        }
        if let iroha_data_model::alias_setup::AliasIntentV1::Domain(intent) = &ensure.intent {
            planned_domains.insert(intent.domain.canonical_name.clone());
        }
        let quote = if disposition == iroha_data_model::alias_setup::AliasPlanDispositionV1::Create
        {
            if let Err(error) = iroha_core::alias_setup::validate_configured_alias_payment_asset(
                world,
                &target,
                &state_view.nexus().fees.fee_asset_id,
            ) {
                return Ok(alias_setup_plan_report_response(
                    StatusCode::CONFLICT,
                    AliasSetupStatusV1::Blocked,
                    error.code(),
                    Some(target.to_string()),
                    None,
                    Some(error.message().to_owned()),
                    "align the SNS policy and pricing tiers with the configured fee asset, then request a new plan",
                ));
            }
            let selector = iroha_core::alias_setup::selector_for_resolved_alias_target(&target)
                .map_err(|error| Error::AppConflict {
                    code: error.code(),
                    message: error.message().to_owned(),
                })?;
            let owner = iroha_core::alias_setup::alias_intent_owner(&ensure.intent);
            let quote = match iroha_core::sns::quote_resolved_name_registration(
                world,
                selector,
                owner,
                ensure.acquisition.term_years,
                ensure.acquisition.pricing_class_hint,
                now_ms,
            ) {
                Ok(quote) => quote,
                Err(error) => {
                    return Ok(alias_setup_plan_report_response(
                        StatusCode::CONFLICT,
                        AliasSetupStatusV1::Blocked,
                        "alias.quote.unavailable",
                        Some(target.to_string()),
                        None,
                        Some(error.to_string()),
                        "adjust the lease request or live SNS policy, then request a new plan",
                    ));
                }
            };
            if let Err(error) = iroha_core::alias_setup::validate_alias_quote_guard(
                world,
                &quote,
                &ensure.quote_guard,
                now_ms,
            ) {
                return Ok(alias_setup_plan_report_response(
                    StatusCode::CONFLICT,
                    AliasSetupStatusV1::Blocked,
                    error.code(),
                    Some(target.to_string()),
                    None,
                    Some(error.message().to_owned()),
                    "refresh the guarded quote and request a new plan",
                ));
            }
            valid_until_ms = valid_until_ms.min(ensure.quote_guard.valid_until_ms);
            let current = totals
                .get(&quote.payment_asset_definition_id)
                .cloned()
                .unwrap_or_else(Quantity::zero);
            let total = current.try_add(&quote.charge_amount).map_err(|error| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                    "alias plan total overflow: {error}"
                )))
            })?;
            totals.insert(quote.payment_asset_definition_id.clone(), total);
            Some(AliasLeaseQuoteV1 {
                target: target.clone(),
                pricing_class: quote.pricing_class,
                exact_amount: quote.charge_amount,
                guard: ensure.quote_guard.clone(),
                expires_at_ms: quote.expires_at_ms,
                grace_expires_at_ms: quote.grace_expires_at_ms,
                redemption_expires_at_ms: quote.redemption_expires_at_ms,
            })
        } else {
            None
        };
        let instruction: InstructionBox = EnsureAlias::new(
            ensure.intent.clone(),
            ensure.acquisition,
            ensure.quote_guard.clone(),
        )
        .into();
        let (wire_id, framed_payload) =
            iroha_data_model::isi::framed_instruction_payload(&instruction).ok_or_else(|| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(
                    "EnsureAlias is missing from the instruction registry".to_owned(),
                ))
            })?;
        let instruction_index = u32::try_from(index).map_err(|_| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                "alias setup instruction index exceeds u32".to_owned(),
            ))
        })?;
        instructions.push(AliasFramedInstructionV1 {
            wire_id: wire_id.to_owned(),
            framed_payload,
        });
        transaction_instructions.push(instruction);
        let child_expiry_ms = quote.as_ref().map_or_else(
            || {
                iroha_core::alias_setup::selector_for_resolved_alias_target(&target)
                    .ok()
                    .and_then(|selector| {
                        iroha_core::sns::get_name_record_by_selector(world, &selector, now_ms).ok()
                    })
                    .map(|record| record.expires_at_ms)
            },
            |quote| Some(quote.expires_at_ms),
        );
        if let (Some(parent), Some(child_expiry_ms)) =
            (alias_setup_parent_target(&target), child_expiry_ms)
        {
            let parent_expiry_ms = planned_expiries.get(&parent).copied().or_else(|| {
                iroha_core::alias_setup::selector_for_resolved_alias_target(&parent)
                    .ok()
                    .and_then(|selector| {
                        iroha_core::sns::get_name_record_by_selector(world, &selector, now_ms).ok()
                    })
                    .map(|record| record.expires_at_ms)
            });
            if let Some(warning) = parent_expiry_ms.and_then(|parent_expiry_ms| {
                alias_setup_parent_expiry_warning(
                    &target,
                    &parent,
                    child_expiry_ms,
                    parent_expiry_ms,
                )
            }) {
                warnings.push(warning);
            }
        }
        if let Some(child_expiry_ms) = child_expiry_ms {
            planned_expiries.insert(target.clone(), child_expiry_ms);
        }
        resources.push(AliasPlanResourceV1 {
            intent: ensure.intent,
            disposition,
            quote,
            instruction_index: Some(instruction_index),
        });
    }
    let totals_by_asset = totals
        .into_iter()
        .map(|(payment_asset, amount)| AliasAssetTotalV1 {
            payment_asset,
            amount,
        })
        .collect();
    let canonical_unsigned_payload = TransactionPayload {
        domain: TransactionDomain::Network(*app.state.network_id_ref()),
        authority: authority.clone(),
        creation_time_ms: now_ms,
        instructions: transaction_instructions.into(),
        time_to_live_ms: None,
        nonce: None,
        fee_payment: iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),

        metadata: iroha_model_base::metadata::Metadata::default(),
        attachments: None,
    };
    let canonical_unsigned_payload_bytes =
        norito::codec::encode_adaptive(&canonical_unsigned_payload).len();
    let blockers = alias_setup_transaction_size_blocker(
        canonical_unsigned_payload_bytes,
        app.transaction_max_content_len,
    )
    .into_iter()
    .collect();
    let plan = AliasTransactionPlanV1::new(AliasTransactionPlanBodyV1 {
        version: AliasTransactionPlanBodyV1::VERSION,
        authority,
        network_id: *app.state.network_id_ref(),
        anchor: AliasPlanAnchorV1 {
            block_height: u64::try_from(state_view.height()).unwrap_or(u64::MAX),
            block_hash: Hash::from(latest_block_hash),
        },
        resources,
        instructions,
        totals_by_asset,
        warnings,
        blockers,
        valid_until_ms,
    });
    Ok(JsonBody(plan).into_response())
}
#[cfg(feature = "app_api")]
fn alias_lifecycle_instruction_frame(
    instruction: &iroha_data_model::isi::InstructionBox,
) -> Result<iroha_data_model::alias_setup::AliasFramedInstructionV1, Error> {
    let (wire_id, framed_payload) = iroha_data_model::isi::framed_instruction_payload(instruction)
        .ok_or_else(|| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                "alias lifecycle instruction is missing from the instruction registry".to_owned(),
            ))
        })?;
    Ok(iroha_data_model::alias_setup::AliasFramedInstructionV1 {
        wire_id: wire_id.to_owned(),
        framed_payload,
    })
}
#[cfg(feature = "app_api")]
async fn handler_alias_lease_renew_plan(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    use iroha_data_model::{
        alias_setup::{
            AliasAssetTotalV1, AliasLeaseQuoteV1, AliasLeaseRenewPlanRequestV1,
            AliasLifecycleOperationV1, AliasLifecyclePlanDispositionV1,
            AliasLifecycleTransactionPlanBodyV1, AliasLifecycleTransactionPlanV1,
            AliasPlanAnchorV1, AliasSetupStatusV1,
        },
        isi::InstructionBox,
    };
    check_public_contract_read_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/aliases/lease/renew/plan",
        "alias_lease_renew_plan",
        None,
    )
    .await?;
    let authority = require_signed_alias_request(&app, &headers, &method, &uri, body.as_ref())?;
    let request: AliasLeaseRenewPlanRequestV1 =
        norito::json::from_slice(body.as_ref()).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(error.to_string()),
            ))
        })?;
    if request.schema_version != AliasLeaseRenewPlanRequestV1::VERSION {
        return Ok(alias_setup_plan_report_response(
            StatusCode::BAD_REQUEST,
            AliasSetupStatusV1::Blocked,
            "alias.renew.plan.version_unsupported",
            Some(request.renewal.target.to_string()),
            Some(AliasLeaseRenewPlanRequestV1::VERSION.to_string()),
            Some(request.schema_version.to_string()),
            "encode the request using the supported AliasLeaseRenewPlanRequestV1 layout",
        ));
    }
    let state_view = app.state.view();
    let Some(latest_block) = state_view
        .latest_block()
        .map_err(crate::canonical_history::canonical_attempt_error)?
    else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            Some(request.renewal.target.to_string()),
            Some("a committed block anchor".to_owned()),
            Some("no committed block".to_owned()),
            "wait for bootstrap or block synchronization, then request a new plan",
        ));
    };
    let Some(latest_block_hash) = state_view.latest_block_hash() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            Some(request.renewal.target.to_string()),
            Some("a canonical committed block hash".to_owned()),
            Some("block hash unavailable".to_owned()),
            "wait for block synchronization, then request a new plan",
        ));
    };
    let now_ms =
        u64::try_from(latest_block.header().creation_time().as_millis()).unwrap_or(u64::MAX);
    let quote = match iroha_core::alias_setup::classify_alias_lease_renewal(
        state_view.world(),
        &state_view.nexus().dataspace_catalog,
        &authority,
        &request.renewal,
        now_ms,
    ) {
        Ok(quote) => quote,
        Err(error) => {
            return Ok(alias_setup_plan_report_response(
                StatusCode::CONFLICT,
                AliasSetupStatusV1::Blocked,
                error.code(),
                Some(request.renewal.target.to_string()),
                None,
                Some(error.message().to_owned()),
                "refresh the live lease and guarded quote, then request a new plan",
            ));
        }
    };
    if let Err(error) = iroha_core::alias_setup::validate_configured_alias_payment_asset(
        state_view.world(),
        &request.renewal.target,
        &state_view.nexus().fees.fee_asset_id,
    ) {
        return Ok(alias_setup_plan_report_response(
            StatusCode::CONFLICT,
            AliasSetupStatusV1::Blocked,
            error.code(),
            Some(request.renewal.target.to_string()),
            None,
            Some(error.message().to_owned()),
            "align the SNS policy and pricing tiers with the configured fee asset, then request a new plan",
        ));
    }
    let instruction: InstructionBox = request.renewal.clone().into();
    let frame = alias_lifecycle_instruction_frame(&instruction)?;
    let lease_quote = AliasLeaseQuoteV1 {
        target: request.renewal.target.clone(),
        pricing_class: quote.pricing_class,
        exact_amount: quote.charge_amount.clone(),
        guard: request.renewal.quote_guard.clone(),
        expires_at_ms: quote.expires_at_ms,
        grace_expires_at_ms: quote.grace_expires_at_ms,
        redemption_expires_at_ms: quote.redemption_expires_at_ms,
    };
    let valid_until_ms = request.renewal.quote_guard.valid_until_ms;
    let plan = AliasLifecycleTransactionPlanV1::new(AliasLifecycleTransactionPlanBodyV1 {
        version: AliasLifecycleTransactionPlanBodyV1::VERSION,
        authority,
        network_id: *app.state.network_id_ref(),
        anchor: AliasPlanAnchorV1 {
            block_height: u64::try_from(state_view.height()).unwrap_or(u64::MAX),
            block_hash: Hash::from(latest_block_hash),
        },
        operation: AliasLifecycleOperationV1::RenewLease(request.renewal),
        disposition: AliasLifecyclePlanDispositionV1::Apply,
        instruction: Some(frame),
        quote: Some(lease_quote),
        totals_by_asset: vec![AliasAssetTotalV1 {
            payment_asset: quote.payment_asset_definition_id,
            amount: quote.charge_amount,
        }],
        warnings: Vec::new(),
        blockers: Vec::new(),
        valid_until_ms,
    });
    Ok(JsonBody(plan).into_response())
}
#[cfg(feature = "app_api")]
async fn handler_alias_auto_renew_plan(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    use iroha_data_model::{
        alias_setup::{
            AliasAutoRenewPlanRequestV1, AliasLifecycleOperationV1,
            AliasLifecyclePlanDispositionV1, AliasLifecycleTransactionPlanBodyV1,
            AliasLifecycleTransactionPlanV1, AliasPlanAnchorV1, AliasSetupStatusV1,
        },
        isi::InstructionBox,
    };
    check_public_contract_read_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/aliases/auto-renew/plan",
        "alias_auto_renew_plan",
        None,
    )
    .await?;
    let authority = require_signed_alias_request(&app, &headers, &method, &uri, body.as_ref())?;
    let request: AliasAutoRenewPlanRequestV1 =
        norito::json::from_slice(body.as_ref()).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(error.to_string()),
            ))
        })?;
    if request.schema_version != AliasAutoRenewPlanRequestV1::VERSION {
        return Ok(alias_setup_plan_report_response(
            StatusCode::BAD_REQUEST,
            AliasSetupStatusV1::Blocked,
            "alias.auto_renew.plan.version_unsupported",
            Some(request.configuration.target.to_string()),
            Some(AliasAutoRenewPlanRequestV1::VERSION.to_string()),
            Some(request.schema_version.to_string()),
            "encode the request using the supported AliasAutoRenewPlanRequestV1 layout",
        ));
    }
    let state_view = app.state.view();
    let Some(latest_block) = state_view
        .latest_block()
        .map_err(crate::canonical_history::canonical_attempt_error)?
    else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            Some(request.configuration.target.to_string()),
            Some("a committed block anchor".to_owned()),
            Some("no committed block".to_owned()),
            "wait for bootstrap or block synchronization, then request a new plan",
        ));
    };
    let Some(latest_block_hash) = state_view.latest_block_hash() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            Some(request.configuration.target.to_string()),
            Some("a canonical committed block hash".to_owned()),
            Some("block hash unavailable".to_owned()),
            "wait for block synchronization, then request a new plan",
        ));
    };
    let now_ms =
        u64::try_from(latest_block.header().creation_time().as_millis()).unwrap_or(u64::MAX);
    let disposition = match iroha_core::alias_setup::classify_alias_auto_renew(
        state_view.world(),
        &state_view.nexus().dataspace_catalog,
        &authority,
        &request.configuration,
        now_ms,
    ) {
        Ok(disposition) => disposition,
        Err(error) => {
            return Ok(alias_setup_plan_report_response(
                StatusCode::CONFLICT,
                AliasSetupStatusV1::Blocked,
                error.code(),
                Some(request.configuration.target.to_string()),
                None,
                Some(error.message().to_owned()),
                "refresh the owner, revision, and policy fields, then request a new plan",
            ));
        }
    };
    let instruction = if disposition == AliasLifecyclePlanDispositionV1::Apply {
        let instruction: InstructionBox = request.configuration.clone().into();
        Some(alias_lifecycle_instruction_frame(&instruction)?)
    } else {
        None
    };
    let plan = AliasLifecycleTransactionPlanV1::new(AliasLifecycleTransactionPlanBodyV1 {
        version: AliasLifecycleTransactionPlanBodyV1::VERSION,
        authority,
        network_id: *app.state.network_id_ref(),
        anchor: AliasPlanAnchorV1 {
            block_height: u64::try_from(state_view.height()).unwrap_or(u64::MAX),
            block_hash: Hash::from(latest_block_hash),
        },
        operation: AliasLifecycleOperationV1::ConfigureAutoRenew(request.configuration),
        disposition,
        instruction,
        quote: None,
        totals_by_asset: Vec::new(),
        warnings: Vec::new(),
        blockers: Vec::new(),
        valid_until_ms: alias_plan_deadline(SystemTime::now(), None)?,
    });
    Ok(JsonBody(plan).into_response())
}
