#[cfg(feature = "app_api")]
async fn handler_ram_lfe_execute(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    AxPath(program_id_literal): AxPath<String>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    check_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/ram-lfe/programs/{program_id}/execute",
    )
    .await?;
    let caller =
        authenticate_identifier_owner_request(&app, &headers, &method, &uri, body.as_ref())?;
    let request: routing::RamLfeExecuteRequestDto = norito::json::from_slice(body.as_ref())
        .map_err(|error| identifier_conversion_error(error.to_string()))?;

    let program_id = iroha_data_model::ram_lfe::RamLfeProgramId::from_str(
        program_id_literal.trim(),
    )
    .map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
        ))
    })?;
    let world = app.state.world_view();
    let Some(program_policy) = world.ram_lfe_program_policies().get(&program_id).cloned() else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    if !program_policy.active {
        return Ok(StatusCode::CONFLICT.into_response());
    }
    require_identifier_program_owner(&caller, &program_policy)?;
    identifier_resolution::require_supported_program_policy(&program_policy)
        .map_err(identifier_execution_error)?;
    let Some(resolver) = app.identifier_resolver.as_ref() else {
        return Ok(StatusCode::SERVICE_UNAVAILABLE.into_response());
    };
    let draft = derive_ram_lfe_request_draft(
        resolver,
        &program_policy,
        &request,
        app.state.network_id_ref(),
    )?;
    let receipt = resolver
        .issue_execution_receipt(&program_policy, &draft)
        .map_err(identifier_execution_error)?;
    let response = ram_lfe_execute_response(&receipt, &draft);
    let response = json_ok(response)?;
    identifier_resolution::owner_prf::validate_owner_prf_lease(
        draft.executed_at_ms,
        draft.expires_at_ms,
    )
    .map_err(identifier_execution_error)?;
    Ok(response)
}
#[cfg(feature = "app_api")]
async fn handler_ram_lfe_receipt_verify(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    NoritoJson(request): NoritoJson<routing::RamLfeReceiptVerifyRequestDto>,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    check_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/ram-lfe/receipts/verify",
    )
    .await?;
    let output_hash_matches = match request.output_hex.as_deref() {
        Some(output_hex) => match parse_hex_bytes(output_hex, "output_hex") {
            Ok(output) => Some(
                iroha_crypto::ram_lfe_output_hash(&output) == request.receipt.payload.output_hash,
            ),
            Err(err) => {
                return json_ok(ram_lfe_receipt_verify_response(
                    &request.receipt,
                    None,
                    Some(err.to_string()),
                ));
            }
        },
        None => None,
    };
    let world = app.state.world_view();
    let Some(program_policy) = world
        .ram_lfe_program_policies()
        .get(&request.receipt.payload.program_id)
        .cloned()
    else {
        return json_ok(ram_lfe_receipt_verify_response(
            &request.receipt,
            output_hash_matches,
            Some(format!(
                "RAM-LFE program policy {} is not registered",
                request.receipt.payload.program_id
            )),
        ));
    };
    if let Err(error) = identifier_resolution::require_supported_program_policy(&program_policy)
        .and_then(|()| {
            request
                .receipt
                .payload
                .backend
                .require_production_support()
                .map_err(Into::into)
        })
    {
        return json_ok(ram_lfe_receipt_verify_response(
            &request.receipt,
            output_hash_matches,
            Some(error.to_string()),
        ));
    }
    let now_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|err| {
            identifier_internal_error(format!("system clock is before UNIX_EPOCH: {err}"))
        })?
        .as_millis()
        .try_into()
        .unwrap_or(u64::MAX);
    let validation = iroha_core::smartcontracts::isi::ram_lfe::validate_execution_receipt_at(
        &request.receipt,
        &program_policy,
        now_ms,
        iroha_core::zk_guardrails::guardrails_from_config(&app.state.zk_snapshot()),
    )
    .err();
    let validation = match (validation, output_hash_matches) {
        (None, Some(false)) => {
            Some("provided output_hex does not match receipt output_hash".to_owned())
        }
        (result, _) => result,
    };
    json_ok(ram_lfe_receipt_verify_response(
        &request.receipt,
        output_hash_matches,
        validation,
    ))
}
