#[cfg(feature = "app_api")]
async fn handler_identifier_resolve(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    check_access(&app, &headers, Some(remote.ip()), "v1/identifiers/resolve").await?;
    let caller =
        authenticate_identifier_owner_request(&app, &headers, &method, &uri, body.as_ref())?;
    let request: routing::IdentifierResolveRequestDto = norito::json::from_slice(body.as_ref())
        .map_err(|error| identifier_conversion_error(error.to_string()))?;

    let policy_id = iroha_data_model::identifier::IdentifierPolicyId::from_str(&request.policy_id)
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
            ))
        })?;
    let world = app.state.world_view();
    let Some(policy) = world.identifier_policies().get(&policy_id).cloned() else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    if !policy.active {
        return Ok(StatusCode::CONFLICT.into_response());
    }
    let Some(program_policy) = world
        .ram_lfe_program_policies()
        .get(&policy.program_id)
        .cloned()
    else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    if !program_policy.active {
        return Ok(StatusCode::CONFLICT.into_response());
    }
    require_identifier_program_owner(&caller, &program_policy)?;
    if caller != policy.owner || policy.program_id != program_policy.program_id {
        return Err(identifier_owner_unauthorized());
    }
    let Some(resolver) = app.identifier_resolver.as_ref() else {
        return Ok(StatusCode::SERVICE_UNAVAILABLE.into_response());
    };
    let draft = derive_identifier_request_draft(
        resolver,
        &policy,
        &program_policy,
        &request,
        app.state.network_id_ref(),
    )?;
    let Some(claim) = world.resolve_identifier_claim(&policy.id, &draft.opaque_id) else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    if policy.id.is_phone_retail()
        && claim.phone_retail_nullifier
            != draft
                .phone_retail_canonicality
                .as_ref()
                .map(|proof| proof.payload.canonical_phone_nullifier)
    {
        return Ok(StatusCode::CONFLICT.into_response());
    }
    let now_ms =
        identifier_resolution::owner_prf::owner_prf_now_ms().map_err(identifier_execution_error)?;
    if !identifier_claim_is_live_at(&claim, now_ms) {
        return Ok(StatusCode::NOT_FOUND.into_response());
    }
    let receipt = resolver
        .sign_receipt(&policy, &program_policy, &draft, &claim)
        .map_err(identifier_execution_error)?;
    let response = json_ok(identifier_receipt_response(
        &receipt,
        draft.backend.as_str(),
    )?)?;
    let delivery_now_ms =
        identifier_resolution::owner_prf::owner_prf_now_ms().map_err(identifier_execution_error)?;
    identifier_resolution::owner_prf::validate_owner_prf_lease_at(
        receipt.payload.opening.payload.opened_at_ms,
        receipt.payload.opening.payload.expires_at_ms,
        delivery_now_ms,
    )
    .map_err(identifier_execution_error)?;
    if !identifier_claim_is_live_at(&claim, delivery_now_ms) {
        return Ok(StatusCode::NOT_FOUND.into_response());
    }
    Ok(response)
}
#[cfg(feature = "app_api")]
async fn handler_identifier_claim_receipt(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    AxPath(account_literal): AxPath<String>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    check_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/accounts/{account_id}/identifiers/claim-receipt",
    )
    .await?;
    let caller =
        authenticate_identifier_owner_request(&app, &headers, &method, &uri, body.as_ref())?;
    let request: routing::IdentifierResolveRequestDto = norito::json::from_slice(body.as_ref())
        .map_err(|error| identifier_conversion_error(error.to_string()))?;

    let account_id = parse_account_id_for_endpoint(
        &app,
        &account_literal,
        "/v1/accounts/{account_id}/identifiers/claim-receipt",
    )?;
    // The signed path selects the beneficiary; its ledger account and UAID bind
    // the receipt. Both active ledger policies authorize the caller below,
    // allowing the policy owner to act for a distinct beneficiary.
    let policy_id = iroha_data_model::identifier::IdentifierPolicyId::from_str(&request.policy_id)
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
            ))
        })?;
    let world = app.state.world_view();
    let Some(policy) = world.identifier_policies().get(&policy_id).cloned() else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    if !policy.active {
        return Ok(StatusCode::CONFLICT.into_response());
    }
    let Some(program_policy) = world
        .ram_lfe_program_policies()
        .get(&policy.program_id)
        .cloned()
    else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    if !program_policy.active {
        return Ok(StatusCode::CONFLICT.into_response());
    }
    require_identifier_program_owner(&caller, &program_policy)?;
    if caller != policy.owner || policy.program_id != program_policy.program_id {
        return Err(identifier_owner_unauthorized());
    }
    let Some(account) = world.account(&account_id).ok() else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    let Some(uaid) = account.uaid().copied() else {
        return Ok(StatusCode::CONFLICT.into_response());
    };
    let Some(resolver) = app.identifier_resolver.as_ref() else {
        return Ok(StatusCode::SERVICE_UNAVAILABLE.into_response());
    };
    let network_id = app.state.network_id_ref().clone();
    if request.phase == "prepare" {
        if request.output_opening.is_some() || request.phone_retail_canonicality.is_some() {
            return Err(identifier_conversion_error(
                "prepare cannot contain an opening or phone attestation",
            ));
        }
        let normalized = zeroize::Zeroizing::new(
            policy
                .normalization
                .normalize(&request.normalized_input)
                .map_err(|error| identifier_conversion_error(error.to_string()))?,
        );
        if policy.program_id != program_policy.program_id
            || policy.owner != program_policy.owner
            || normalized.as_str() != request.normalized_input.as_str()
        {
            return Err(identifier_conversion_error(
                "prepare input must match the exact native policy normalization",
            ));
        }
        let nonce = zeroize::Zeroizing::new(parse_identifier_input_nonce(&request.input_nonce)?);
        let execution = resolver
            .execute_owner_prf(
                &program_policy,
                &request.normalized_input,
                &nonce,
                &network_id,
            )
            .map_err(identifier_execution_error)?;
        let output_opening = resolver
            .owner_prf_opening(&program_policy, &execution)
            .map_err(identifier_execution_error)?;
        let phone_like = policy.id.kind.as_ref() == "phone"
            || policy.normalization
                == iroha_data_model::identifier::IdentifierNormalization::PhoneE164
            || policy.program_id.to_string() == "phone_retail";
        let phone_retail_canonicality_payload = if phone_like {
            if !policy.id.is_phone_retail()
                || policy.normalization
                    != iroha_data_model::identifier::IdentifierNormalization::PhoneE164
                || policy.program_id.to_string() != "phone_retail"
            {
                return Err(identifier_conversion_error(
                    "prepare requires the exact phone#retail contract",
                ));
            }
            let key = policy
                .phone_retail_attestor_public_key
                .as_ref()
                .ok_or_else(|| {
                    identifier_conversion_error(
                        "phone#retail requires an independently pinned attestor key",
                    )
                })?;
            if key == &program_policy.resolver_public_key
                || key == &program_policy.output_opening_public_key
            {
                return Err(identifier_conversion_error(
                    "phone attestor must be independent of native resolver and opener",
                ));
            }
            Some(
                iroha_data_model::identifier::PhoneRetailCanonicalityPayloadV1 {
                    network_id,
                    policy_id: policy.id.clone(),
                    program_id: policy.program_id.clone(),
                    input_ciphertext_hash: execution.input_ciphertext_hash,
                    output_ciphertext_hash: execution.output_ciphertext_hash,
                    opened_output_hash: execution.output_hash,
                    canonical_phone_nullifier: execution.output_hash,
                    uaid,
                    account_id: account_id.clone(),
                    issued_at_ms: output_opening.payload.opened_at_ms,
                    expires_at_ms: output_opening.payload.expires_at_ms.ok_or_else(|| {
                        identifier_conversion_error("native opening requires a bounded expiry")
                    })?,
                },
            )
        } else {
            None
        };
        let original_opened_at_ms = output_opening.payload.opened_at_ms;
        let original_expires_at_ms = output_opening.payload.expires_at_ms;
        let response = json_ok(routing::IdentifierPrfPrepareResponseDto {
            network_id: hex::encode(network_id.as_bytes()),
            policy_id: policy.id.to_string(),
            account_id: account_id.to_string(),
            uaid: uaid.to_string(),
            output_opening,
            phone_retail_canonicality_payload,
        })?;
        identifier_resolution::owner_prf::validate_owner_prf_lease(
            original_opened_at_ms,
            original_expires_at_ms,
        )
        .map_err(identifier_execution_error)?;
        return Ok(response);
    }
    let draft = derive_identifier_request_draft(
        resolver,
        &policy,
        &program_policy,
        &request,
        app.state.network_id_ref(),
    )?;
    let receipt = resolver
        .issue_claim_receipt(&policy, &program_policy, &draft, uaid, account_id)
        .map_err(identifier_execution_error)?;
    let response = json_ok(identifier_receipt_response(
        &receipt,
        draft.backend.as_str(),
    )?)?;
    identifier_resolution::owner_prf::validate_owner_prf_lease(
        receipt.payload.opening.payload.opened_at_ms,
        receipt.payload.opening.payload.expires_at_ms,
    )
    .map_err(identifier_execution_error)?;
    Ok(response)
}
#[cfg(feature = "app_api")]
async fn handler_identifier_receipt_lookup(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    AxPath(receipt_hash_literal): AxPath<String>,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    check_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/identifiers/receipts/{receipt_hash}",
    )
    .await?;
    let receipt_hash = Hash::from_str(receipt_hash_literal.trim()).map_err(|err| {
        identifier_conversion_error(format!("invalid identifier receipt hash: {err}"))
    })?;
    let world = app.state.world_view();
    let Some(claim) = world.resolve_identifier_claim_by_receipt_hash(&receipt_hash) else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    json_ok(identifier_claim_lookup_response(&claim))
}
#[cfg(test)]
fn normalise_alias(input: &str) -> String {
    input
        .chars()
        .filter(|c| !c.is_ascii_whitespace())
        .map(|c| c.to_ascii_uppercase())
        .collect()
}
const LEDGER_HEADER_PAGE_CAP: u64 = 512;
async fn handler_ledger_headers(
    State(app): State<SharedAppState>,
    crate::NoritoQuery(window): crate::NoritoQuery<routing::HistoryWindowQuery>,
    headers: axum::http::HeaderMap,
) -> Result<Response, Error> {
    let accept = headers.get(axum::http::header::ACCEPT);
    let format = match crate::utils::negotiate_response_format(accept) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };
    let state_view = app.state.view();
    let current_height = u64::try_from(state_view.height()).unwrap_or(u64::MAX);
    let start_height = match window.from {
        Some(0) => return Err(conversion_error("from must be at least 1".to_owned())),
        Some(from) => from.min(current_height),
        None => current_height,
    };
    let limit = window
        .limit
        .filter(|&lim| lim > 0)
        .unwrap_or(LEDGER_HEADER_PAGE_CAP)
        .min(LEDGER_HEADER_PAGE_CAP)
        .min(usize::MAX as u64) as usize;
    let mut headers: Vec<BlockHeader> = Vec::new();
    let mut height = start_height;
    while height >= 1 && headers.len() < limit {
        if height > usize::MAX as u64 {
            return Err(conversion_error(
                "block height exceeds host pointer width".to_owned(),
            ));
        }
        let Some(nz_height) = NonZeroUsize::new(height as usize) else {
            break;
        };
        let block = state_view
            .canonical_block_by_height(nz_height)
            .map_err(crate::canonical_history::canonical_attempt_error)?;
        headers.push(block.header());
        if height == 1 {
            break;
        }
        height -= 1;
    }
    drop(state_view);
    match format {
        ResponseFormat::Norito => Ok(NoritoBody(headers).into_response()),
        ResponseFormat::Json => {
            let body = norito::json::to_json_pretty(&headers).map_err(|err| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(
                    err.to_string(),
                ))
            })?;
            let mut resp = Response::new(Body::from(body));
            resp.headers_mut().insert(
                axum::http::header::CONTENT_TYPE,
                HeaderValue::from_static("application/json"),
            );
            Ok(resp)
        }
    }
}
fn finalized_block_wire_internal_error(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::InternalError(
        message.into(),
    ))
}
fn block_proof_limits(state: &CoreState) -> BlockProofLimits {
    let wire_limit =
        iroha_data_model::block::proofs::AUTHENTICATED_BLOCK_PROOFS_MAX_BLOCK_WIRE_BYTES_V1 as u64;
    BlockProofLimits {
        max_source_blocks: state.pipeline_snapshot().query_max_fetch_size,
        max_source_wire_bytes: wire_limit,
        max_block_wire_bytes: wire_limit,
        max_work_items: state.pipeline_snapshot().query_max_fetch_size,
        max_response_bytes: wire_limit,
    }
}
fn block_proof_capacity_response(
    resource: BlockProofResource,
    actual: u64,
    limit: u64,
) -> Response {
    utils::respond_with_status_and_format(
        if matches!(
            resource,
            BlockProofResource::WorkItems | BlockProofResource::SourceBlocks
        ) {
            StatusCode::TOO_MANY_REQUESTS
        } else {
            StatusCode::PAYLOAD_TOO_LARGE
        },
        ErrorEnvelope::new(
            "block_proof_capacity_exceeded",
            format!(
                "The finalized block proof exceeds its {resource:?} serving limit (at least {actual} required, {limit} admitted)."
            ),
        ),
        utils::current_response_format(),
    )
}
fn executed_block_wire_too_large_response(height: NonZeroU64) -> Response {
    utils::respond_with_status_and_format(
        StatusCode::PAYLOAD_TOO_LARGE,
        ErrorEnvelope::new(
            "executed_block_wire_too_large",
            "The finalized block exceeds the authenticated block-proof carrier limit.",
        )
        .with_details(ErrorDetails {
            endpoint: Some(format!("/v1/ledger/block/{height}")),
            expected: Some(format!(
                "at most {} bytes",
                iroha_data_model::block::proofs::AUTHENTICATED_BLOCK_PROOFS_MAX_BLOCK_WIRE_BYTES_V1
            )),
            ..Default::default()
        }),
        utils::current_response_format(),
    )
}
// Whole-carrier responses include unrelated Network and internal output material.
// Exact-account and exact-dataspace grants cannot authorize this representation.
fn require_full_ledger_carrier_permission(
    app: &SharedAppState,
    account: &AccountId,
) -> Result<(), Error> {
    let permission: Permission = CanReadAllLedgerData.into();
    let view = app.state.view();
    if !torii_account_has_permission(view.world(), account, &permission) {
        return Err(Error::Query(
            iroha_data_model::ValidationFail::NotPermitted(
                "Full ledger carriers require CanReadAllLedgerData; use an authorized exact transaction query for selective inclusion".to_owned(),
            ),
        ));
    }
    Ok(())
}

fn authenticate_full_ledger_carrier_reader(
    app: &SharedAppState,
    headers: &HeaderMap,
    method: &Method,
    uri: &Uri,
) -> Result<AccountId, Error> {
    let authentication_owner =
        match crate::history_producer::HistoryProducerOwner::authentication_read(&app) {
            Ok(owner) => owner,
            Err(error) => {
                return Err(error);
            }
        };

    let request = crate::app_auth::verify_canonical_network_request(
        &app.state,
        app.state.network_id_ref(),
        headers,
        method,
        uri,
        &[],
        None,
        authentication_owner.allocation_context(),
    )?
    .ok_or_else(|| Error::AppUnauthorized {
        code: "canonical_authentication_required",
        message: "canonical account request authentication is required for full ledger carriers"
            .to_owned(),
    })?;
    require_full_ledger_carrier_permission(app, &request.account)?;
    Ok(request.account)
}

async fn handler_ledger_executed_block_wire(
    State(app): State<SharedAppState>,
    axum::extract::Path(height): axum::extract::Path<u64>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
) -> Result<Response, Error> {
    let account = authenticate_full_ledger_carrier_reader(&app, &headers, &method, &uri)?;
    let mut response =
        ledger_executed_block_wire_response(State(Arc::clone(&app)), axum::extract::Path(height))
            .await?;
    require_full_ledger_carrier_permission(&app, &account)?;
    response.headers_mut().insert(
        axum::http::header::CACHE_CONTROL,
        HeaderValue::from_static("private, no-store"),
    );
    Ok(response)
}

async fn handler_block_proof(
    State(app): State<SharedAppState>,
    axum::extract::Path(selector): axum::extract::Path<(u64, String)>,
    headers: HeaderMap,
    method: Method,
    uri: Uri,
) -> Result<Response, Error> {
    let account = authenticate_full_ledger_carrier_reader(&app, &headers, &method, &uri)?;
    let mut response =
        block_proof_response(State(Arc::clone(&app)), axum::extract::Path(selector)).await?;
    require_full_ledger_carrier_permission(&app, &account)?;
    response.headers_mut().insert(
        axum::http::header::CACHE_CONTROL,
        HeaderValue::from_static("private, no-store"),
    );
    Ok(response)
}

async fn ledger_executed_block_wire_response(
    State(app): State<SharedAppState>,
    axum::extract::Path(height): axum::extract::Path<u64>,
) -> Result<Response, Error> {
    let height = NonZeroU64::new(height)
        .ok_or_else(|| conversion_error("block height must be at least 1".to_owned()))?;
    let limits = block_proof_limits(&app.state);
    // State captures only the committed hash journal around an exact finalized
    // Kura read. Size admission precedes body I/O; original QC bytes are returned.
    let wire = match app.state.executed_block_wire(height, limits) {
        Ok(wire) => wire,
        Err(BlockProofError::CapacityExceeded {
            resource,
            actual,
            limit,
            ..
        }) => {
            return Ok(
                if matches!(
                    resource,
                    BlockProofResource::BlockWireBytes | BlockProofResource::ResponseBytes
                ) {
                    executed_block_wire_too_large_response(height)
                } else {
                    block_proof_capacity_response(resource, actual, limit)
                },
            );
        }
        Err(error) => return Err(map_block_proof_error(error)),
    };
    // HTTP retirement owns the original charged frame; no response byte copy or early refund.
    let mut response = Response::new(Body::from(Bytes::from_owner(wire)));
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static(utils::NORITO_MIME_TYPE),
    );
    response.headers_mut().insert(
        axum::http::header::X_CONTENT_TYPE_OPTIONS,
        HeaderValue::from_static("nosniff"),
    );
    Ok(response)
}
async fn block_proof_response(
    State(app): State<SharedAppState>,
    axum::extract::Path((height, entry_hex)): axum::extract::Path<(u64, String)>,
) -> Result<Response, Error> {
    let block_height = NonZeroU64::new(height)
        .ok_or_else(|| conversion_error("block height must be at least 1".to_owned()))?;
    let normalized = entry_hex.trim_start_matches("0x");
    let entry_hash: HashOf<TransactionEntrypoint> = normalized
        .parse()
        .map_err(|err| conversion_error(format!("invalid entry hash: {err}")))?;
    let limits = block_proof_limits(&app.state);
    let proofs = match app
        .state
        .block_proofs_for_entry(block_height, entry_hash, limits)
    {
        Ok(proofs) => proofs,
        Err(BlockProofError::CapacityExceeded {
            resource,
            actual,
            limit,
            ..
        }) => {
            return Ok(block_proof_capacity_response(resource, actual, limit));
        }
        Err(error) => return Err(map_block_proof_error(error)),
    };
    let maximum = usize::try_from(limits.max_response_bytes).map_err(|_| {
        finalized_block_wire_internal_error("proof response limit exceeds host width")
    })?;
    utils::respond_with_format_bounded(proofs, ResponseFormat::Norito, maximum)
        .map_err(|error| finalized_block_wire_internal_error(error.to_string()))
}

fn map_block_proof_error(error: BlockProofError) -> Error {
    match error {
        BlockProofError::Deferred(original) => canonical_history::query_attempt_error(
            iroha_core::execution_attempt::ExecutionAttemptError::Deferred(original),
        ),
        BlockProofError::HeightOutOfRange(_) => conversion_error(error.to_string()),
        BlockProofError::BlockNotFound(_) | BlockProofError::EntrypointNotFound { .. } => {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::NotFound,
            ))
        }
        BlockProofError::CapacityExceeded { .. } => {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
            ))
        }
        BlockProofError::Storage { .. }
        | BlockProofError::InvalidOutputs { .. }
        | BlockProofError::BlockHashMismatch { .. }
        | BlockProofError::BlockHeightMismatch { .. }
        | BlockProofError::MissingResults(_) => Error::Query(
            iroha_data_model::ValidationFail::InternalError(error.to_string()),
        ),
    }
}
